return ['x-generator'=>'GlotPress/4.1.0','translation-revision-date'=>'2026-10-14 02:30:04+0000','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','project-id-version'=>'Plugins - WP Mail SMTP by WPForms &#8211; Free SMTP Plugin with Gmail, Outlook, Amazon SES, SendGrid, Mailgun, Zoho &amp; other SMTP - Stable (latest release)','language'=>'sr_RS','messages'=>['Last checked: %s'=>'Последња провера: %s','Go To WPVibe'=>'Иди на WPVibe','Send a test email to check your email domain'=>'Пошаљите пробну е-поруку да бисте проверили свој домен е-поште','Your email domain is checked when you send a test email. No check has run yet for the current mailer and From email.'=>'Ваш домен е-поште се проверава када пошаљете пробну е-поруку. Још није покренута ниједна провера за тренутну услугу слања и е-адресу пошиљаоца.','No plugin was specified.'=>'Није наведен ниједан додатак.','This plugin is not allowed.'=>'Овај додатак није дозвољен.','Update Now'=>'Ажурирај сада','Emails'=>'Е-пошта','%s%%'=>'%s%%','What\'s New'=>'Шта је ново','Share'=>'Подели','Date Sent'=>'Датум слања','Completed'=>'Завршено','Your email address'=>'Ваша адреса е-поште','Complete'=>'Завршено','Incomplete'=>'Недовршено','Setup Checklist'=>'Контролни списак подешавања','Test Email'=>'Пробна е-порука','Import Settings'=>'Увези подешавања','Please enter a valid email address.'=>'Унесите исправну адресу е-поште.','View Complete Setup Checklist'=>'Прикажи цео списак за подешавање','Connect WordPress to mailers like SendLayer, Gmail, Outlook, Amazon SES, and more to start sending emails'=>'Повежите Вордпрес са програмима за слање као што су SendLayer, Gmail, Outlook, Amazon SES и други да бисте почели да шаљете е-поруке','Once your site starts sending emails, your stats will show up here. Send a test email to make sure everything works.'=>'Када ваш сајт почне да шаље е-поруке, ваше статистике ће се појавити овде. Пошаљите пробну е-поруку да бисте се уверили да све ради.','+%s More Step..'=>'+%s корак више..' . "\0" . '+%s корака више..' . "\0" . '+%s корака више..','The setup wizard needs JavaScript. Please enable it and reload this page.'=>'Чаробњаку за подешавање је потребан JavaScript. Омогућите га и поново учитајте ову страницу.','No Emails Sent Yet'=>'Још нема послатих е-порука','Sorry, there\'s not enough email data from this date range to show sources. Once your site sends more emails, sources will show up here.'=>'Нажалост, нема довољно података о е-порукама из овог временског опсега за приказ извора. Када ваш сајт пошаље више е-порука, извори ће се појавити овде.','No Email Source Data Yet'=>'Још нема података о извору е-порука','Upgrade to Pro to unlock the email log and see exactly where every email comes from.'=>'Надоградите на Pro да бисте откључали дневник е-порука и видели тачно одакле свака е-порука долази.','See Which Plugins Send Emails'=>'Погледајте који додаци шаљу е-поруке','View log entry'=>'Прикажи унос у дневнику','View email'=>'Прикажи е-поруку','No Emails Logged Yet'=>'Још нема забележених е-порука','Once your site starts sending emails, your recent emails will show up here. Send a test email to make sure everything works.'=>'Када ваш сајт почне да шаље е-поруке, ваше недавне е-поруке ће се појавити овде. Пошаљите пробну е-поруку да бисте се уверили да све ради.','Upgrade to Pro to unlock email logging and see every email your site sends right from your dashboard.'=>'Надоградите на Pro да бисте откључали бележење е-порука и видели сваку е-поруку коју ваш сајт шаље непосредно са своје контролне табле.','View Email Logs'=>'Прикажи дневнике е-порука','Widget settings'=>'Подешавања виџета','Reset to Default Settings'=>'Врати на подразумевана подешавања','The data shown behind this popup is for example purposes only. No email data has been recorded.'=>'Подаци приказани иза овог искачућег прозора служе само као пример. Нису забележени подаци о е-порукама.','Upgrade to Unlock'=>'Надогради за откључавање','%s for WP Mail SMTP Lite users!'=>'%s за кориснике WP Mail SMTP Lite!','Not completed'=>'Није завршено','Select SMTP Plugin'=>'Изаберите SMTP додатак','Take your website to the next level with our sister plugins.'=>'Подигните свој веб сајт на виши ниво уз наше сестринске додатке.','Set Up Recommended Growth Tools'=>'Подесите препоручене алате за раст','Select the SMTP plugin to import settings from'=>'Изаберите SMTP додатак из ког ћете увести подешавања','Toggle section'=>'Укључи/искључи одељак','Complete Setup Checklist'=>'Довршите списак за подешавање','Complete WP Mail SMTP Setup Checklist'=>'Довршите списак за подешавање WP Mail SMTP-а','Something went wrong dismissing the checklist. Please try again.'=>'Дошло је до грешке при одбацивању списка. Покушајте поново.','This will permanently dismiss the Setup Checklist, and you will not be able to bring it back. This cannot be undone.'=>'Ово ће трајно одбацити списак за подешавање и нећете моћи да га вратите. Ово се не може опозвати.','%d%% complete'=>'%d%% завршено','Yes, dismiss'=>'Да, одбаци','WP Mail SMTP Setup Checklist'=>'Списак за подешавање WP Mail SMTP-а','Website analytics made easy for WordPress. Form tracking, reports, and more.'=>'Аналитика веб сајта за Вордпрес постаје једноставна. Праћење образаца, извештаји и још много тога.','Get more email subscribers & sales with the #1 CRO toolkit for WordPress.'=>'Добијте више претплатника е-поште и продаја уз водећи CRO пакет алата за Вордпрес.','Import Settings From %s'=>'Увези подешавања из %s','Import Settings From Existing SMTP Plugins'=>'Увези подешавања из постојећих SMTP додатака','Count Me In!'=>'Рачунајте на мене!','Collect non-sensitive information from your website, such as the PHP version and features used, to help us fix bugs faster, make smarter decisions, and build features that actually matter to you.'=>'Прикупљајте неосетљиве податке са свог веб сајта, као што су PHP издање и коришћене функције, да бисте нам помогли да брже исправљамо грешке, доносимо паметније одлуке и правимо функције које су вам заиста важне.','Help Improve WP Mail SMTP'=>'Помозите у побољшању WP Mail SMTP-а','Sign Up for Free'=>'Пријави се бесплатно','Smart Recommendations from WP Mail SMTP'=>'Паметне препоруке од WP Mail SMTP-а','Improve GDPR, CCPA, and privacy compliance with cookie banner and consent records.'=>'Побољшајте усклађеност са GDPR-ом, CCPA-ом и прописима о приватности помоћу банера за колачиће и записа о пристанку.','Set Up Privacy Compliance'=>'Подесите усклађеност са прописима о приватности','Browse Snippets'=>'Прегледај исечке','Customize how WP Mail SMTP works with one-click, pre-built snippets powered by WPCode.'=>'Прилагодите начин рада WP Mail SMTP-а помоћу готових исечака на један притисак које покреће WPCode.','Review email logs and debug sending issues with Claude, ChatGPT, and more via the free WPVibe plugin.'=>'Прегледајте дневнике е-порука и отклањајте проблеме са слањем помоћу Claude-а, ChatGPT-а и других путем бесплатног додатка WPVibe.','Set Up Code Snippets'=>'Подесите исечке кода','View Domain Report'=>'Прикажи извештај о домену','We found issues with your domain\'s email authentication. Fix SPF, DKIM, and DMARC to keep your emails out of spam.'=>'Пронашли смо проблеме са провером идентитета е-поште вашег домена. Поправите SPF, DKIM и DMARC да ваше е-поруке не би завршавале у нежељеној пошти.','Fix Your Domain Setup'=>'Поправите подешавање свог домена','Set up your mailer first. Until then there is no connection to send a test email through.'=>'Прво подесите свој програм за слање. Дотле нема везе преко које би се послала пробна е-порука.','Confirm your site can send emails by delivering a test message to your inbox.'=>'Потврдите да ваш сајт може да шаље е-поруке тако што ћете испоручити пробну поруку у своје пријемно сандуче.','Successfully Send a Test Email'=>'Успешно пошаљите пробну е-поруку','We have detected other SMTP plugins installed on your website. Select which plugin\'s data to import'=>'Открили смо да су на вашем веб сајту постављени други SMTP додаци. Изаберите из ког додатка ћете увести податке','Connect WordPress to mailers like SendLayer, Gmail, Outlook, Amazon SES, and more to start sending emails.'=>'Повежите Вордпрес са програмима за слање као што су SendLayer, Gmail, Outlook, Amazon SES и други да бисте почели да шаљете е-поруке.','Setup Your Mailer'=>'Подесите свој програм за слање','Improve Your Email Sending Experience'=>'Побољшајте своје искуство слања е-порука','Connect Your Mailer'=>'Повежите свој програм за слање','You do not have permission to subscribe to the newsletter.'=>'Немате дозволу да се претплатите на билтен.','You do not have permission to change these settings.'=>'Немате дозволу да мењате ова подешавања.','You do not have permission to dismiss the Setup Checklist.'=>'Немате дозволу да одбаците списак за подешавање.','Post SMTP'=>'Post SMTP','Only a network administrator can install plugins for the sites on this network.'=>'Само администратор мреже може да поставља додатке за сајтове у овој мрежи.','Your account does not have permission to activate plugins on this site. The plugin is already installed, so an administrator only needs to switch it on.'=>'Ваш налог нема дозволу да укључује додатке на овом сајту. Додатак је већ постављен, па администратор треба само да га укључи.','Your account does not have permission to install plugins on this site.'=>'Ваш налог нема дозволу да поставља додатке на овом сајту.','The plugin was installed but could not be activated. Please activate it from the Plugins page.'=>'Додатак је постављен, али није могао да буде укључен. Укључите га са странице „Додаци“.','Could not activate the plugin. It is not installed.'=>'Није могуће укључити додатак. Није постављен.','Your account does not have permission to activate plugins on this site.'=>'Ваш налог нема дозволу да укључује додатке на овом сајту.','Insufficient permissions.'=>'Недовољне дозволе.','Session expired.'=>'Сесија је истекла.','Multisite Support'=>'Подршка за мрежу сајтова','You do not have permission to dismiss this notice.'=>'Немате дозволу да одбаците ово обавештење.','Try Again'=>'Покушајте поново','by'=>'by','Email Sent'=>'Е-порука је послата','Sending...'=>'Слање...','Enter a valid email address.'=>'Унесите исправну адресу е-поште.','WP Mail SMTP Pro'=>'WP Mail SMTP Pro','Opened'=>'Отворено','View All Documentation'=>'Погледај сву документацију','Getting Started'=>'Како почети','Enable'=>'Омогући','Could not install the plugin. Missing file system permission.'=>'Није могуће поставити додатак. Недостаје дозвола за систем датотека.','This plugin cannot be installed automatically.'=>'Овај додатак се не може самостално поставити.','License key format is not valid.'=>'Облик кључа лиценце није исправан.','Unknown mailer.'=>'Непознат програм за слање.','Too many attempts. Wait a moment and try again.'=>'Превише покушаја. Сачекајте тренутак и покушајте поново.','Please provide a mailer to remove the OAuth connection for.'=>'Наведите програм за слање за који ће се уклонити OAuth веза.','Please provide a mailer to get the OAuth authorization URL for.'=>'Наведите програм за слање за који ће се добити адреса OAuth овлашћења.','Please provide a mailer to get the connected account for.'=>'Наведите програм за слање за који ће се добити повезани налог.','Could not find any settings to import from the selected plugin.'=>'Није могуће пронаћи подешавања за увоз из изабраног додатка.','Please select a plugin to import settings from.'=>'Изаберите додатак из ког ћете увести подешавања.','The setup wizard is temporarily unavailable.'=>'Чаробњак за подешавање је привремено недоступан.','The setup wizard returned an unexpected response.'=>'Чаробњак за подешавање је вратио неочекиван одговор.','The setup wizard could not be reached.'=>'Чаробњак за подешавање није доступан.','The setup wizard could not be started for your account.'=>'Чаробњак за подешавање није могао да буде покренут за ваш налог.','Your session has expired. Please refresh this page and try again.'=>'Ваша сесија је истекла. Освежите ову страницу и покушајте поново.','Manage email settings across your network.'=>'Управљајте подешавањима е-поште у својој мрежи.','Get help from our email deliverability experts.'=>'Добијте помоћ од наших стручњака за испоручивост е-порука.','Download your email logs in CSV, Excel, or EML.'=>'Преузмите своје дневнике е-порука у CSV, Excel или EML облику.','Control how many emails your site sends per interval.'=>'Одредите колико е-порука ваш сајт шаље по интервалу.','Send each email type through the mailer you choose.'=>'Шаљите сваку врсту е-поруке преко програма за слање који изаберете.','Silence default WordPress emails you don\'t need.'=>'Утишајте подразумеване Вордпрес е-поруке које вам нису потребне.','Manage WordPress Notifications'=>'Управљајте Вордпрес обавештењима','See when emails are opened and links are clicked.'=>'Погледајте када се е-поруке отворе и везе притисну.','Track opens, clicks, and weekly deliverability stats.'=>'Пратите отварања, притиске и недељне статистике испоручивости.','Unlock Amazon SES, Microsoft 365, and Zoho.'=>'Откључајте Amazon SES, Microsoft 365 и Zoho.','Advanced Mailers'=>'Напредни програми за слање','Easily configure your Gmail and Outlook mailers.'=>'Лако подесите своје Gmail и Outlook програме за слање.','Never miss an email with an automatic backup mailer.'=>'Никада не пропустите е-поруку уз самостални резервни програм за слање.','Instant failure alerts via email, Slack, SMS, and more.'=>'Тренутна упозорења о неуспеху путем е-поште, Slack-а, SMS-а и других.','Log, track, and resend any email your site sends.'=>'Бележите, пратите и поново пошаљите сваку е-поруку коју ваш сајт шаље.','Your license key provides access to WP Mail SMTP Pro features, updates and support.'=>'Ваш кључ лиценце пружа приступ WP Mail SMTP Pro функцијама, ажурирањима и подршци.','You do not have permission to run a deliverability test.'=>'Немате дозволу да покренете проверу испоручивости.','You Cannot Run This Test'=>'Не можете покренути ову проверу','Your session expired. Please reload the page and try again.'=>'Ваша сесија је истекла. Поново учитајте страницу и покушајте поново.','Hey %s, welcome back.<br>Your full deliverability report is ready to view right away.'=>'Здраво, %s, добро дошли назад.<br>Ваш потпуни извештај о испоручивости спреман је за преглед.','Your Session Expired'=>'Ваша сесија је истекла','Your deliverability report is ready!<br>We\'ve emailed it to %s. Open the link inside to see your full results and what to fix first.'=>'Ваш извештај о испоручивости је спреман!<br>Послали смо га е-поштом на %s. Отворите везу у њему да бисте видели потпуне резултате и шта прво треба поправити.','We\'ll email your report to this address and may follow up with occasional deliverability tips. Unsubscribe anytime.'=>'Послаћемо ваш извештај на ову адресу и можда повремено пошаљемо савете о испоручивости. Можете се одјавити у било ком тренутку.','There is no test running. Please start a new one.'=>'Ниједна провера није у току. Покрените нову.','Finish setting up your primary connection before running a test.'=>'Довршите подешавање главне везе пре покретања провере.','Finish Your Connection Setup'=>'Довршите подешавање своје везе','A test is already running. Please wait for it to finish.'=>'Провера је већ у току. Сачекајте да се заврши.','Start a New Report'=>'Покрени нови извештај','Do you want a new report?'=>'Да ли желите нови извештај?','Email Detective Is Temporarily Unavailable'=>'Email Detective је привремено недоступан','Too Many Requests Right Now'=>'Тренутно има превише захтева','Your Report Is Ready!'=>'Ваш извештај је спреман!','View Your Deliverability Report'=>'Прикажи свој извештај о испоручивости','Resend the Report Email'=>'Поново пошаљи е-поруку са извештајем','Didn\'t get it? Check your spam or junk folder before resending.'=>'Нисте га добили? Проверите фасциклу нежељене поште пре поновног слања.','Check Your Inbox!'=>'Проверите своје пријемно сандуче!','View the Report Page'=>'Прикажи страницу извештаја','Your site sent the test email, but Email Detective never received it. That usually points to a deliverability problem worth fixing. The report page has the same verdict and what to try next.'=>'Ваш сајт је послао пробну е-поруку, али је Email Detective никада није примио. То обично указује на проблем са испоручивошћу који вреди поправити. Страница извештаја има исту оцену и шта даље да покушате.','We Couldn\'t Confirm Delivery'=>'Нисмо могли да потврдимо испоруку','Retry Test Email'=>'Поново пошаљи пробну е-поруку','Read the mailer setup guide'=>'Прочитајте водич за подешавање програма за слање','Your primary connection returned an error before Email Detective could run the check. Here\'s what your site reported:'=>'Ваша главна веза је вратила грешку пре него што је Email Detective могао да изврши проверу. Ево шта је ваш сајт пријавио:','The Test Email Couldn\'t Be Sent'=>'Пробна е-порука није могла да буде послата','This usually takes less than a minute.'=>'Ово обично траје мање од минута.','Your test email is on its way. We\'re watching how the receiving server treats it and putting your report together.'=>'Ваша пробна е-порука је на путу. Пратимо како је третира сервер примаоца и састављамо ваш извештај.','Email Detective Is on the Case...'=>'Email Detective је на задатку...','Example Email Detective report'=>'Пример Email Detective извештаја','Example Report'=>'Пример извештаја','Free report with clear, prioritized fixes'=>'Бесплатан извештај са јасним исправкама поређаним по приоритету','Your message scored by a real spam filter'=>'Вашу поруку оцењује прави филтер нежељене поште','Domain and IP checked on blocklists'=>'Домен и IP проверени на црним листама','SPF, DKIM, & DMARC checks'=>'Провере SPF, DKIM и DMARC','Run a Deliverability Test'=>'Покрени проверу испоручивости','Send the report to'=>'Пошаљи извештај на','We will send the report to your email address below.'=>'Послаћемо извештај на вашу адресу е-поште испод.','Finish Primary Connection Setup'=>'Довршите подешавање главне везе','Email Detective needs a fully configured primary connection before it can send a deliverability test. Finish setting up your primary connection first.'=>'Email Detective-у је потребна потпуно подешена главна веза пре него што може да пошаље проверу испоручивости. Прво довршите подешавање своје главне везе.','Find Out If Your Emails Actually Reach the Inbox'=>'Сазнајте да ли ваше е-поруке заиста стижу у пријемно сандуче','This test is not ready for that step. Please refresh the page and try again.'=>'Ова провера није спремна за тај корак. Освежите страницу и покушајте поново.','Your site sends a test email through your primary connection, and %s checks everything that decides where it lands: authentication, blacklists, and spam filters. You get a free report showing exactly what to fix before real emails get lost in spam or get rejected.'=>'Ваш сајт шаље пробну е-поруку преко ваше главне везе, а %s проверава све што одлучује где ће она завршити: проверу идентитета, црне листе и филтере нежељене поште. Добијате бесплатан извештај који тачно показује шта треба поправити пре него што праве е-поруке заврше у нежељеној пошти или буду одбијене.','We have not received your test email yet. Please wait for it to arrive before unlocking the report.'=>'Још нисмо примили вашу пробну е-поруку. Сачекајте да стигне пре откључавања извештаја.','Manage'=>'Уреди','%1$s - %2$s'=>'%1$s - %2$s','Sent'=>'Послато','Connected'=>'Повезано','Failed'=>'Није успело','Activating…'=>'Укључивање…','Dashboard'=>'Контролна табла','You do not have permission to do this.'=>'Немате дозволу да то урадите.','WP Mail SMTP Lite'=>'WP Mail SMTP Lite','Email Detective is temporarily unavailable. Please try again in a moment.'=>'Email Detective је привремено недоступан. Покушајте поново за тренутак.','You are sending requests too quickly. Please come back at %s and this page will pick up automatically.'=>'Шаљете захтеве пребрзо. Вратите се у %s и ова страница ће самостално наставити.','Failed Last Week'=>'Неуспешне прошле недеље','Emails Last Week'=>'Е-поруке прошле недеље','Email Detective'=>'Email Detective','Setup Checklist Overview'=>'Преглед списка за подешавање','Translate your website into 110+ languages quickly with AI.'=>'Брзо преведите свој веб сајт на 110+ језика помоћу ВИ.','Improve SEO rankings with AI tools and get valuable insights.'=>'Побољшајте SEO рангирање помоћу ВИ алата и добијте вредне увиде.','Fast, secure WordPress backups and migrations.'=>'Брзе, безбедне резервне копије и селидбе Вордпреса.','Customer reviews from Google, Yelp, and more to boost sales.'=>'Рецензије купаца са Google-а, Yelp-а и других за повећање продаје.','Recommended Growth Tools'=>'Препоручени алати за раст','Using WP Mail SMTP with AI Assistants'=>'Коришћење WP Mail SMTP-а са ВИ помоћницима','Understanding Email Reports'=>'Разумевање извештаја о е-порукама','Enabling Email Logging'=>'Омогућавање бележења е-порука','Sending a Test Email'=>'Слање пробне е-поруке','View All Settings'=>'Прикажи сва подешавања','Setting Up Your Mailer (Complete Guide)'=>'Подешавање програма за слање (потпун водич)','Plus dozens of other powerful features to keep your WordPress emails hitting the inbox.'=>'Плус десетине других моћних функција које ће ваше Вордпрес е-поруке одржати у пријемном сандучету.','Get the Most Out of WP Mail SMTP'=>'Извуците највише из WP Mail SMTP-а','%s OFF for WP Mail SMTP Lite users!'=>'%s ПОПУСТА за кориснике WP Mail SMTP Lite!','Take Your Emails to the Next Level'=>'Подигните своје е-поруке на виши ниво','Take Your Email Deliverability to the Next Level'=>'Подигните испоручивост својих е-порука на виши ниво','Upgrade to Pro and get instant alert notifications when emails fail to send.'=>'Надоградите на Pro и добијајте тренутна упозорења када слање е-порука не успе.','Get notified instantly when emails fail to send with the Email Alerts feature.'=>'Будите одмах обавештени када слање е-порука не успе уз функцију Email Alerts.','Your Site Had %d Failed Email in the Last 30 Days'=>'Ваш сајт је имао %d неуспешну е-поруку у последњих 30 дана' . "\0" . 'Ваш сајт је имао %d неуспешне е-поруке у последњих 30 дана' . "\0" . 'Ваш сајт је имао %d неуспешних е-порука у последњих 30 дана','Email Sources'=>'Извори е-порука','Emails Overview'=>'Преглед е-порука','Setup Primary Connection'=>'Подесите главну везу','Test Connections'=>'Провери везе','Setup incomplete'=>'Подешавање није довршено','Mailer error'=>'Грешка програма за слање','Domain check warning'=>'Упозорење провере домена','Connect a mailer to start sending emails'=>'Повежите програм за слање да бисте почели да шаљете е-поруке','No primary connection'=>'Нема главне везе','Setup a new mailer connection'=>'Подесите нову везу са програмом за слање','New Connection'=>'Нова веза','Backup helps when primary fails'=>'Резервна веза помаже када главна не успе','No backup added'=>'Није додата резервна веза','Connections'=>'Везе','Get Email Alerts with Pro'=>'Добијте упозорења о е-порукама уз Pro','Set Up Alerts'=>'Подеси упозорења','A large share of your recent emails failed to send. Set up alerts to get notified the next time it happens.'=>'Велики део ваших недавних е-порука није успешно послат. Подесите упозорења да бисте били обавештени следећи пут када се то деси.','Set Up Email Alerts'=>'Подесите упозорења о е-порукама','Invalid widget.'=>'Неисправан виџет.','Invalid card.'=>'Неисправна картица.','Your session has expired. Please reload the page.'=>'Ваша сесија је истекла. Поново учитајте страницу.','Don\'t have a license key yet? <a class="js-wp-mail-smtp-upgrade-modal-purchase wpms-license-key-card__link" href="%s" target="_blank" rel="noopener noreferrer">Purchase Here!</a>'=>'Још немате кључ лиценце? <a class="js-wp-mail-smtp-upgrade-modal-purchase wpms-license-key-card__link" href="%s" target="_blank" rel="noopener noreferrer">Купите овде!</a>','Your license key can be found in your <a class="wpms-license-key-card__link" href="%s" target="_blank" rel="noopener noreferrer">WP Mail SMTP Account Dashboard</a>.'=>'Ваш кључ лиценце можете пронаћи на <a class="wpms-license-key-card__link" href="%s" target="_blank" rel="noopener noreferrer">WP Mail SMTP контролној табли налога</a>.','Paste your license key below to verify your purchase and upgrade to WP Mail SMTP Pro. <a class="wpms-license-key-card__link" href="%s" target="_blank" rel="noopener noreferrer">Need Help?</a>'=>'Налепите свој кључ лиценце испод да бисте потврдили куповину и надоградили на WP Mail SMTP Pro. <a class="wpms-license-key-card__link" href="%s" target="_blank" rel="noopener noreferrer">Потребна вам је помоћ?</a>','50% off'=>'50% попуста на','regular price, automatically applied at checkout.'=>'редовну цену, што се аутоматски примењује при плаћању.','Bonus:'=>'Бонус:','Done'=>'Обављено','Upgrade'=>'Надогради','License key'=>'Кључ лиценце','Host'=>'Хост','Port'=>'Порт','WP Mail SMTP users get'=>'Корисници WP Mail SMTP-а добијају','Install it manually from WordPress.org'=>'Поставите га ручно са WordPress.org','WP Mail SMTP Pro has been successfully installed and activated. Feel free to close this window and start exploring your new Pro features.'=>'WP Mail SMTP Pro је успешно постављен и укључен. Слободно затворите овај прозор и почните да истражујете своје нове Pro функције.','Welcome to WP Mail SMTP Pro!'=>'Добро дошли у WP Mail SMTP Pro!','Upgrade to WP Mail SMTP Pro to unlock %name% and everything you need to keep your WordPress emails sending smoothly.'=>'Надоградите на WP Mail SMTP Pro да бисте откључали %name% и све што вам је потребно да би се ваше Вордпрес е-поруке несметано слале.','Configure Sender Details'=>'Подесите податке о пошиљаоцу','Login your account to create your API keys and then paste it below.'=>'Пријавите се на свој налог да бисте направили API кључеве, а затим их налепите испод.','Configure API Keys'=>'Подесите API кључеве','The name your emails are sent from.'=>'Име са ког се шаљу ваше е-поруке.','The name and address your emails are sent from.'=>'Име и адреса са којих се шаљу ваше е-поруке.','Edit connection lets you paste a new API key or connect a different account.'=>'Уређивање везе вам омогућава да налепите нови API кључ или повежете други налог.','Edit Connection'=>'Уреди везу','Your saved connection to %s'=>'Ваша сачувана веза са %s','Your saved connection'=>'Ваша сачувана веза','Paste your license key below to verify your purchase and upgrade to WP Mail SMTP Pro.'=>'Налепите свој кључ лиценце испод да бисте потврдили куповину и надоградили на WP Mail SMTP Pro.','%1$sNeed Help?%2$s'=>'%1$sПотребна вам је помоћ?%2$s','Don\'t have a license key yet? %1$sPurchase Here!%2$s'=>'Још немате кључ лиценце? %1$sКупите овде!%2$s','There was an error upgrading with your license key. Please try again later.'=>'Дошло је до грешке при надоградњи помоћу вашег кључа лиценце. Покушајте поново касније.','Enter your License Key'=>'Унесите свој кључ лиценце','Copy the Client ID and Client Secret from your Zoho app and paste them below.'=>'Умножите Client ID и Client Secret из свог Zoho програма и налепите их испод.','Pick the data center your Zoho account uses, create a new app in the Zoho Developer Console for that data center, then come back here. Follow our %1$sstep-by-step Zoho Mail setup guide%2$s if you need help.'=>'Изаберите центар података који користи ваш Zoho налог, направите нови програм у Zoho Developer Console за тај центар података, а затим се вратите овде. Пратите наш %1$sводич корак по корак за подешавање Zoho Mail-а%2$s ако вам је потребна помоћ.','Create your Zoho Mail App'=>'Направите свој Zoho Mail програм','Please paste this URL into "Client Details > Authorized Redirect URIs" for your app.'=>'Налепите ову адресу у „Client Details > Authorized Redirect URIs“ за свој програм.','Read how to set up Other SMTP'=>'Прочитајте како да подесите Other SMTP','The login your mail server checks before it sends mails. Often an app password, not your normal one.'=>'Подаци за пријаву које ваш сервер поште проверава пре слања порука. Често лозинка програма, а не ваша уобичајена.','Where your emails are sent through. Get these values from your host or email provider.'=>'Преко чега се шаљу ваше е-поруке. Ове вредности добијте од свог хостинга или пружаоца е-поште.','Configure Your Mail Server'=>'Подесите свој сервер поште','For most servers %1$sTLS is the recommended option%2$s. If your SMTP provider offers both SSL and TLS options, we recommend using TLS.'=>'За већину сервера %1$sTLS је препоручена могућност%2$s. Ако ваш SMTP пружалац нуди и SSL и TLS, препоручујемо TLS.','Auto-set from your encryption choice (TLS 587, SSL 465). Change only if your host differs.'=>'Самостално се поставља на основу вашег избора шифровања (TLS 587, SSL 465). Промените само ако се ваш хостинг разликује.','Your provider\'s outgoing mail server, e.g. smtp.gmail.com or smtp.office365.com.'=>'Сервер одлазне поште вашег пружаоца, нпр. smtp.gmail.com или smtp.office365.com.','Connected to SendLayer, sending from %s.'=>'Повезано са SendLayer-ом, слање са %s.','Paste your API Key'=>'Налепите свој API кључ','Create and copy the API key from your dashboard %1$sSettings > API Keys%2$s and paste it here.'=>'Направите и умножите API кључ са своје контролне табле %1$sSettings > API Keys%2$s и налепите га овде.','Connected to SendLayer.'=>'Повезано са SendLayer-ом.','Sign up or login an existing %1$sSendLayer Account%2$s.'=>'Региструјте се или се пријавите на постојећи %1$sSendLayer налог%2$s.','Create your SendLayer Account'=>'Направите свој SendLayer налог','<strong>%1$sSendLayer%2$s is our #1 recommended mailer.</strong> Easily start sending emails from your site in just a few clicks and enjoy your %3$sfirst 200 emails absolutely free!%4$s'=>'<strong>%1$sSendLayer%2$s је наш програм за слање препоручен као број 1.</strong> Лако почните да шаљете е-поруке са свог сајта у само неколико притисака и уживајте у %3$sпрвих 200 е-порука потпуно бесплатно!%4$s','Please paste this URL into "Authentication > Redirect URIs" for your app in the Microsoft Azure portal.'=>'Налепите ову адресу у „Authentication > Redirect URIs“ за свој програм у Microsoft Azure порталу.','SendLayer Quick Connect'=>'SendLayer брзо повезивање','Create your Microsoft Azure App'=>'Направите свој Microsoft Azure програм','Copy the Application ID and Application Password from your %1$sAzure app%2$s and paste them below.'=>'Умножите Application ID и Application Password из свог %1$sAzure програма%2$s и налепите их испод.','Register a new app in the %1$sMicrosoft Azure portal%3$s, then come back here. Follow our %2$sstep-by-step Outlook setup guide%3$s if you need help.'=>'Региструјте нови програм у %1$sMicrosoft Azure порталу%3$s, а затим се вратите овде. Пратите наш %2$sводич корак по корак за подешавање Outlook-а%3$s ако вам је потребна помоћ.','%1$sFollow this link%2$s to get an API Key from Mandrill.'=>'%1$sПратите ову везу%2$s да бисте добили API кључ од Mandrill-а.','Copy the Client ID and Client Secret from your %1$sGoogle Cloud app%3$s and paste them below. Please make sure your app\'s Publishing status is %2$sset to Production%3$s.'=>'Умножите Client ID и Client Secret из свог %1$sGoogle Cloud програма%3$s и налепите их испод. Уверите се да је стање објављивања вашег програма %2$sпостављено на Production%3$s.','Create a new app in the %1$sGoogle Cloud Console%3$s, then come back here. Follow our %2$sstep-by-step Gmail setup guide%3$s if you need help.'=>'Направите нови програм у %1$sGoogle Cloud Console%3$s, а затим се вратите овде. Пратите наш %2$sводич корак по корак за подешавање Gmail-а%3$s ако вам је потребна помоћ.','Connect with Gmail in about %1$s30 seconds%2$s. No manual Google Cloud project setup, no API keys, no hassle!'=>'Повежите се са Gmail-ом за око %1$s30 секунди%2$s. Без ручног подешавања Google Cloud пројекта, без API кључева, без муке!','Paste your app credentials'=>'Налепите акредитиве свог програма','Please only paste into "Authorized redirect URIs", not "Authorized JavaScript origins".'=>'Налепите само у „Authorized redirect URIs“, а не у „Authorized JavaScript origins“.','Create your Google Cloud App'=>'Направите свој Google Cloud програм','Manual Setup'=>'Ручно подешавање','Select a SES Identity first'=>'Прво изаберите SES идентитет','Must be an address or domain verified as an SES identity in this region, or Amazon will reject sending.'=>'Мора бити адреса или домен проверен као SES идентитет у овом региону, иначе ће Amazon одбити слање.','Select SES Identities'=>'Изаберите SES идентитете','These are the email addresses and domains which have been verified by SES for being used for sending emails.'=>'Ово су адресе е-поште и домени које је SES проверио за употребу при слању е-порука.','Copy the Access Key ID and Secret Access Key from your IAM user and paste them below. AWS shows the secret only once, so if you didn\'t save it, create a new access key.'=>'Умножите Access Key ID и Secret Access Key свог IAM корисника и налепите их испод. AWS приказује тајну само једном, па ако је нисте сачували, направите нови приступни кључ.','Paste your AWS credentials'=>'Налепите своје AWS акредитиве','Create your IAM user on Amazon Web Services'=>'Направите свог IAM корисника на Amazon Web Services','Verified SES Identities'=>'Проверени SES идентитети','Create an account on %1$sAmazon Web Services%2$s and then create an IAM user from the %3$sIAM Users page%4$s, then come back here. Follow our %5$sstep-by-step Amazon SES setup guide%6$s if you need help.'=>'Направите налог на %1$sAmazon Web Services%2$s, а затим направите IAM корисника са %3$sстранице IAM Users%4$s и вратите се овде. Пратите наш %5$sводич корак по корак за подешавање Amazon SES-а%6$s ако вам је потребна помоћ.','%1$sSMTP.com is one of our recommended mailers.%2$s Trusted by 100,000+ businesses for over 20 years, with a free 30-day trial for up to 50,000 emails.'=>'%1$sSMTP.com је један од наших препоручених програма за слање.%2$s Верује му 100.000+ предузећа више од 20 година, уз бесплатну пробу од 30 дана за до 50.000 е-порука.','Editing this connection lets you re-test it or connect to a different host.'=>'Уређивање ове везе вам омогућава да је поново проверите или се повежете са другим хостом.','Removing this connection disconnects your site from SendLayer. You can connect again with Quick Connect, or set up the mailer with an API key instead.'=>'Уклањање ове везе прекида везу вашег сајта са SendLayer-ом. Можете се поново повезати помоћу брзог повезивања или уместо тога подесити програм за слање помоћу API кључа.','You have successfully linked the current site with SendLayer!'=>'Успешно сте повезали тренутни сајт са SendLayer-ом!','%1$sBrevo (formerly Sendinblue) is one of our recommended mailers.%2$s It scales with your business, start free with 300 emails/day, no credit card needed!'=>'%1$sBrevo (раније Sendinblue) је један од наших препоручених програма за слање.%2$s Расте са вашим пословањем, почните бесплатно са 300 е-порука дневно, није потребна кредитна картица!','Edit connection lets you paste new AWS credentials or connect a different AWS account.'=>'Уређивање везе вам омогућава да налепите нове AWS акредитиве или повежете други AWS налог.','Re-Test Email'=>'Поново провери е-поруку','Hide Mailer Configuration'=>'Сакриј подешавање програма за слање','Edit Mailer Configuration'=>'Уреди подешавање програма за слање','We couldn\'t send the test email due to errors in your mailer configuration. <strong>Please update your mailer configuration and try again.</strong>'=>'Нисмо могли да пошаљемо пробну е-поруку због грешака у подешавању вашег програма за слање. <strong>Ажурирајте подешавање програма за слање и покушајте поново.</strong>','We\'ve identified your error as a known issue and have a clear, step-by-step solution ready for you! <strong>Just refer our troubleshoot guide to get started.</strong>'=>'Препознали смо вашу грешку као познат проблем и имамо спремно јасно решење корак по корак! <strong>Само погледајте наш водич за отклањање проблема да бисте почели.</strong>','Your test email was unsuccessful'=>'Ваша пробна е-порука није успела','Zoho sends from your connected account, %s.'=>'Zoho шаље са вашег повезаног налога, %s.','Your mailer is set up correctly, but your domain is missing some records that inbox providers use to verify your emails. <strong>Fix the items below to keep your messages out of spam.</strong> %1$sLearn More%2$s'=>'Ваш програм за слање је исправно подешен, али вашем домену недостају неки записи које пружаоци пријемних сандучића користе за проверу ваших е-порука. <strong>Поправите ставке испод да ваше поруке не би завршавале у нежељеној пошти.</strong> %1$sСазнајте више%2$s','Your settings could not be saved, so no test email was sent. Please try again.'=>'Ваша подешавања нису могла да буду сачувана, па пробна е-порука није послата. Покушајте поново.','Skip and Finish Setup'=>'Прескочи и заврши подешавање','Save and Re-Test Email'=>'Сачувај и поново провери е-поруку','The email address your emails are sent from. Best to match your authenticated address for deliverability.'=>'Адреса е-поште са које се шаљу ваше е-поруке. Најбоље је да одговара вашој провереној адреси ради испоручивости.','Also double-check your sender details — your From Email should use the same domain you just authenticated.'=>'Такође још једном проверите податке о пошиљаоцу — ваша е-пошта пошиљаоца треба да користи исти домен који сте управо проверили.','Fill out the required settings below to set up this mailer.'=>'Попуните захтевана подешавања испод да бисте поставили овај програм за слање.','Your license has expired.'=>'Ваша лиценца је истекла.','Recheck From Email'=>'Поново провери е-пошту пошиљаоца','We checked your domain for the DNS records that email providers look for. Each item below includes a step-by-step guide for adding the missing record.'=>'Проверили смо ваш домен у потрази за DNS записима које траже пружаоци е-поште. Свака ставка испод укључује водич корак по корак за додавање записа који недостаје.','Your test email was sent, but it needs better deliverability.'=>'Ваша пробна е-порука је послата, али јој је потребна боља испоручивост.','Action Needed to Improve Deliverability'=>'Потребна је радња за побољшање испоручивости','Your connection was verified, but your settings were not saved. Use Save and Continue to try again.'=>'Ваша веза је проверена, али ваша подешавања нису сачувана. Користите „Сачувај и настави“ да бисте покушали поново.','Authorize Connection'=>'Овласти везу','Verify Connection'=>'Провери везу','Continue Anyway'=>'Ипак настави','Configure %s Settings'=>'Подеси %s подешавања','Still stuck? Please log in to your %1$sWP Mail SMTP account%2$s and submit a support ticket with the error log.'=>'И даље имате проблем? Пријавите се на свој %1$sWP Mail SMTP налог%2$s и пошаљите захтев за подршку са дневником грешака.','The license key no longer exists or the user associated with it has been deleted.'=>'Кључ лиценце више не постоји или је корисник повезан са њим избрисан.','Your license is invalid.'=>'Ваша лиценца није исправна.','Your license has been disabled.'=>'Ваша лиценца је онемогућена.','Your license has no site activations left.'=>'Ваша лиценца нема више преосталих укључивања сајтова.','An active license is needed to access Pro features, plugin updates (including security improvements), and our world class support!'=>'Активна лиценца је потребна за приступ Pro функцијама, ажурирањима додатка (укључујући безбедносна побољшања) и нашој врхунској подршци!','Let\'s start by activating your license, this unlocks Pro features and automatic updates.'=>'Почнимо укључивањем ваше лиценце, што откључава Pro функције и самостална ажурирања.','Re-verify & Continue'=>'Поново провери и настави','Your license key can be found in your %1$sWP Mail SMTP Account Dashboard%2$s. Don’t have a license key? %3$sSign up today!%4$s'=>'Ваш кључ лиценце можете пронаћи на %1$sWP Mail SMTP контролној табли налога%2$s. Немате кључ лиценце? %3$sРегиструјте се данас!%4$s','Activate & Continue'=>'Укључи и настави','Your license key can be found in your %1$sWP Mail SMTP Account Dashboard%2$s. Don’t have a renewed license key yet? %3$sRenew Your Plan%4$s'=>'Ваш кључ лиценце можете пронаћи на %1$sWP Mail SMTP контролној табли налога%2$s. Још немате обновљен кључ лиценце? %3$sОбновите свој план%4$s','Your license key can be found in your %1$sWP Mail SMTP Account Dashboard%2$s.'=>'Ваш кључ лиценце можете пронаћи на %1$sWP Mail SMTP контролној табли налога%2$s.','%1$sPlease use a different license key%2$s to use WP Mail SMTP Pro features and enable automatic updates.'=>'%1$sКористите други кључ лиценце%2$s да бисте користили WP Mail SMTP Pro функције и омогућили самостална ажурирања.','You can update the list of your sites or upgrade the license in the %1$sAccount area%2$s. Or you can %3$spurchase a new license key%4$s.'=>'Списак својих сајтова можете ажурирати или надоградити лиценцу у %1$sделу налога%2$s. Или можете %3$sкупити нови кључ лиценце%4$s.','If your license has been renewed or upgraded, then please force a %1$sstatus refresh%2$s.'=>'Ако је ваша лиценца обновљена или надограђена, принудно %1$sосвежите стање%2$s.','There was an error removing your license key. Please try again later.'=>'Дошло је до грешке при уклањању вашег кључа лиценце. Покушајте поново касније.','There was an error verifying your license key. Please try again later.'=>'Дошло је до грешке при провери вашег кључа лиценце. Покушајте поново касније.','Your license is still not active.'=>'Ваша лиценца још увек није активна.','Please enter your license key.'=>'Унесите свој кључ лиценце.','Please add these CNAME records to your domain\'s DNS settings. For information on how to add CNAME DNS records, please refer to the %1$sAmazon SES documentation%2$s. Once verified, the domain will appear in the Verified SES Identities list above.'=>'Додајте ове CNAME записе у DNS подешавања свог домена. За податке о томе како да додате CNAME DNS записе, погледајте %1$sAmazon SES документацију%2$s. Када буде проверен, домен ће се појавити на списку проверених SES идентитета изнад.','Connection Details'=>'Појединости везе','Verify New Email Address'=>'Провери нову адресу е-поште','Add DNS records to your domain'=>'Додајте DNS записе свом домену','Please open your email to complete the next steps of verifying your new email address with SES. Once verified, the address will appear in the Verified SES Identities list above.'=>'Отворите своју е-пошту да бисте довршили следеће кораке провере нове адресе е-поште у SES-у. Када буде проверена, адреса ће се појавити на списку проверених SES идентитета изнад.','Verification email has been sent!'=>'Е-порука за проверу је послата!','Please enter a domain, like example.com.'=>'Унесите домен, као што је example.com.','Please enter an email address, like you@example.com.'=>'Унесите адресу е-поште, као што је you@example.com.','Verify New Address'=>'Провери нову адресу','Add New Email Address or Domain'=>'Додај нову адресу е-поште или домен','Verify New Domain'=>'Провери нови домен','Please enter your new email address'=>'Унесите своју нову адресу е-поште','Enter the new email address to verify it on Amazon SES. We\'ll send you a confirmation mail on the added address.'=>'Унесите нову адресу е-поште да бисте је проверили на Amazon SES-у. Послаћемо вам поруку за потврду на додату адресу.','Need a different sender?'=>'Потребан вам је други пошиљалац?','Verify a new email address or domain in SES'=>'Проверите нову адресу е-поште или домен у SES-у','No verified identities in this region yet.'=>'У овом региону још нема проверених идентитета.','Thanks for choosing WP Mail SMTP Pro! We’ll guide you through each step to get everything set up on your site.'=>'Хвала што сте изабрали WP Mail SMTP Pro! Провешћемо вас кроз сваки корак да бисте све подесили на свом сајту.','Select from verified identities'=>'Изаберите међу провереним идентитетима','Activate Your License'=>'Покрените своју лиценцу','Your mailer has not been setup correctly to allow your site to send emails. We recommend you set it up correctly before moving further.'=>'Ваш програм за слање није исправно подешен да би ваш сајт могао да шаље е-поруке. Препоручујемо да га исправно подесите пре него што наставите.','Mailer not setup correctly'=>'Програм за слање није исправно подешен','Too many checks in a row'=>'Превише провера заредом','Connection verified'=>'Веза је проверена','Successfully connected to %s'=>'Успешно повезано са %s','Give it a minute and verify again. This limit counts every mailer you\'ve tested, so it can trip while you\'re comparing a few.'=>'Сачекајте минут и поново проверите. Ово ограничење рачуна сваки програм за слање који сте проверили, па се може активирати док поредите неколико њих.','Your settings may be correct, we just weren\'t able to confirm it. You can verify again, or continue and send a test email once setup is done.'=>'Ваша подешавања су можда исправна, само нисмо могли то да потврдимо. Можете поново проверити или наставити и послати пробну е-поруку када подешавање буде завршено.','Still stuck? Get priority support by %1$sUpgrading to Pro%2$s or %3$screate a support thread%4$s along with the error log on WordPress.org forums.'=>'И даље имате проблем? Добијте приоритетну подршку %1$sнадоградњом на Pro%2$s или %3$sнаправите тему за подршку%4$s заједно са дневником грешака на WordPress.org форумима.','Need hands-on help? Our %1$sWhite Glove Setup%2$s handles everything for you, just share your site details and we\'ll do the rest.'=>'Потребна вам је непосредна помоћ? Наша услуга %1$sWhite Glove Setup%2$s обавља све уместо вас, само поделите податке о свом сајту и ми ћемо урадити остало.','Resolve your email sending issues with %1$sSendLayer%2$s, and send your first 200 emails for free with just a few clicks!'=>'Решите проблеме са слањем е-порука помоћу %1$sSendLayer-а%2$s и пошаљите својих првих 200 е-порука бесплатно у само неколико притисака!','It offers no sign-in method we can use. If your provider doesn\'t require credentials, switch Authentication off.'=>'Не нуди начин пријаве који можемо да користимо. Ако ваш пружалац не захтева акредитиве, искључите проверу идентитета.','This server doesn\'t accept a username and password'=>'Овај сервер не прихвата корисничко име и лозинку','The security certificate doesn\'t cover this hostname. Use the exact SMTP Host from your provider\'s setup guide rather than your own domain.'=>'Безбедносни сертификат не покрива ово име хоста. Користите тачан SMTP Host из водича за подешавање свог пружаоца уместо свог домена.','The certificate is for a different server'=>'Сертификат је за други сервер','We couldn\'t confirm this connection is private. The certificate may be expired or self-signed, which your provider or host will need to fix.'=>'Нисмо могли да потврдимо да је ова веза приватна. Сертификат је можда истекао или је самопотписан, што ваш пружалац или хостинг треба да поправи.','The server\'s security certificate didn\'t check out'=>'Безбедносни сертификат сервера није прошао проверу','It won\'t accept a sign-in over an unencrypted connection. Set Encryption to TLS or SSL, on the SMTP Port your provider documents.'=>'Не прихвата пријаву преко нешифроване везе. Поставите шифровање на TLS или SSL, на SMTP порту који наводи ваш пружалац.','This server requires encryption'=>'Овај сервер захтева шифровање','The secure handshake failed on this combination. TLS is usually 587 and SSL is usually 465, so check which pair your provider documents.'=>'Безбедно руковање није успело за ову комбинацију. TLS је обично 587, а SSL обично 465, па проверите који пар наводи ваш пружалац.','This port expects different encryption'=>'Овај порт очекује другачије шифровање','The server turned your site away'=>'Сервер је одбио ваш сајт','It answered, then refused the connection before asking for any credentials. Your provider may be blocking your site\'s IP address, or need it added to an allow list.'=>'Одговорио је, а затим одбио везу пре него што је затражио акредитиве. Ваш пружалац можда блокира IP адресу вашег сајта или је треба додати на списак дозвољених.','The server answered on a different port, so this one is closed or blocked. Try another SMTP Port.'=>'Сервер је одговорио на другом порту, па је овај затворен или блокиран. Пробајте други SMTP порт.','This port didn\'t answer'=>'Овај порт није одговорио','The connection opened and then went quiet, so we couldn\'t finish checking. A firewall on your host blocking outbound mail is the usual cause, so try another SMTP Port, or ask your host to open this one.'=>'Веза се отворила, а затим је утихнула, па нисмо могли да завршимо проверу. Хостинг заштитни зид који блокира одлазну пошту је уобичајен узрок, па пробајте други SMTP порт или затражите од хостинга да отвори овај.','The server stopped responding'=>'Сервер је престао да одговара','The server didn\'t start a conversation'=>'Сервер није започео комуникацију','It accepted the connection but sent nothing back, which usually means this port expects a different Encryption setting. Try SSL on 465, or TLS on 587.'=>'Прихватио је везу, али није ништа вратио, што обично значи да овај порт очекује другачије подешавање шифровања. Пробајте SSL на 465 или TLS на 587.','We couldn\'t finish checking. A firewall on your host blocking outbound mail is the usual cause, so try another SMTP Port, or ask your host to open it.'=>'Нисмо могли да завршимо проверу. Хостинг заштитни зид који блокира одлазну пошту је уобичајен узрок, па пробајте други SMTP порт или затражите од хостинга да га отвори.','The server didn\'t answer in time'=>'Сервер није одговорио на време','Common host settings'=>'Уобичајена подешавања хостинга','Couldn\'t reach the mail server'=>'Није могуће доћи до сервера поште','We couldn\'t open a connection to this host on this port. Check both with your provider (TLS is usually 587, SSL 465), or your host may block outbound SMTP.'=>'Нисмо могли да отворимо везу са овим хостом на овом порту. Проверите оба код свог пружаоца (TLS је обично 587, SSL 465) или ваш хостинг можда блокира одлазни SMTP.','Connected and secured — but the server rejected your username or password. Most hosts need an app password, not your normal login password.'=>'Повезано и обезбеђено — али је сервер одбио ваше корисничко име или лозинку. Већина хостинга захтева лозинку програма, а не вашу уобичајену лозинку за пријаву.','Authentication failed'=>'Провера идентитета није успела','Your provider recognized these settings, but in its other region. Change the Region setting, then verify again.'=>'Ваш пружалац је препознао ова подешавања, али у свом другом региону. Промените подешавање региона, а затим поново проверите.','This looks like the wrong region'=>'Изгледа да је ово погрешан регион','Your settings may be correct, we just couldn\'t confirm it. Save them and send a test email to check, and contact support if that fails.'=>'Ваша подешавања су можда исправна, само нисмо могли то да потврдимо. Сачувајте их и пошаљите пробну е-поруку ради провере, а обратите се подршци ако то не успе.','Your provider doesn\'t have this domain on your account. Check that it matches exactly, including any subdomain.'=>'Ваш пружалац нема овај домен на вашем налогу. Проверите да ли се тачно поклапа, укључујући поддомен.','Your site couldn\'t open a connection, so we couldn\'t check these settings. If your host blocks outgoing requests, they\'ll need to allow them before email can send.'=>'Ваш сајт није могао да отвори везу, па нисмо могли да проверимо ова подешавања. Ако ваш хостинг блокира одлазне захтеве, мораће да их дозволи пре него што е-пошта може да се шаље.','We couldn\'t read your provider\'s answer'=>'Нисмо могли да прочитамо одговор вашег пружаоца','This is on their side, not yours, so we couldn\'t check these settings. Try again shortly, or look at your provider\'s status page.'=>'Ово је на њиховој страни, а не на вашој, па нисмо могли да проверимо ова подешавања. Покушајте поново ускоро или погледајте страницу стања свог пружаоца.','Your provider asked us to slow down'=>'Ваш пружалац је затражио да успоримо','We couldn\'t finish checking, so we can\'t tell you whether these settings work. Wait a moment and verify again.'=>'Нисмо могли да завршимо проверу, па не можемо да вам кажемо да ли ова подешавања раде. Сачекајте тренутак и поново проверите.','We couldn\'t reach your provider'=>'Нисмо могли да дођемо до вашег пружаоца','You can continue. Send a test email to confirm it reaches you.'=>'Можете да наставите. Пошаљите пробну е-поруку да бисте потврдили да стиже до вас.','Your provider didn\'t respond'=>'Ваш пружалац није одговорио','We couldn\'t check this connection'=>'Нисмо могли да проверимо ову везу','Recheck your connection settings against your provider\'s dashboard, then verify again.'=>'Поново упоредите подешавања везе са контролном таблом свог пружаоца, а затим поново проверите.','This connection works, with a limitation'=>'Ова веза ради, уз ограничење','Your settings may be correct, we just couldn\'t confirm it. Verify again, or save and send a test email.'=>'Ваша подешавања су можда исправна, само нисмо могли то да потврдимо. Поново проверите или сачувајте и пошаљите пробну е-поруку.','This connection didn\'t work'=>'Ова веза није успела','Where to find your API key'=>'Где да пронађете свој API кључ','Mailgun setup guide'=>'Водич за подешавање Mailgun-а','Mailgun didn\'t accept this key + domain combination. Check that the domain matches exactly, the region is right (US vs EU), and the key is the Private API key.'=>'Mailgun није прихватио ову комбинацију кључа и домена. Проверите да ли се домен тачно поклапа, да ли је регион исправан (US или EU) и да ли је кључ Private API key.','A GovCloud region needs an access key created inside GovCloud. Either pick a standard region, or paste a GovCloud key pair.'=>'GovCloud регион захтева приступни кључ направљен унутар GovCloud-а. Изаберите стандардни регион или налепите GovCloud пар кључева.','The provider didn\'t recognize this key. Verify that you\'re using the correct credentials from your provider’s dashboard and that they’re still valid.'=>'Пружалац није препознао овај кључ. Проверите да ли користите исправне акредитиве са контролне табле свог пружаоца и да ли су и даље важећи.','These credentials aren\'t for GovCloud'=>'Ови акредитиви нису за GovCloud','Couldn\'t verify this domain'=>'Није могуће проверити овај домен','Amazon SES doesn\'t run in the selected region. Pick one from the Region list, ideally the closest to your site.'=>'Amazon SES не ради у изабраном региону. Изаберите један са списка региона, по могућству најближи вашем сајту.','That region isn\'t available'=>'Тај регион није доступан','The provider didn\'t recognize this key. Copy it again from your dashboard - make sure it has sending permission and no trailing spaces.'=>'Пружалац није препознао овај кључ. Поново га умножите са своје контролне табле - уверите се да има дозволу за слање и да нема размака на крају.','Where to find your access keys'=>'Где да пронађете своје приступне кључеве','Access Key ID was rejected'=>'Access Key ID је одбијен','That API key was rejected'=>'Тај API кључ је одбијен','How to create a new access key'=>'Како да направите нови приступни кључ','Amazon recognized your Access Key ID but not the signature made with this secret. Amazon shows the Secret Access Key only once, so if you didn\'t save it, create a new access key.'=>'Amazon је препознао ваш Access Key ID, али не и потпис направљен овом тајном. Amazon приказује Secret Access Key само једном, па ако га нисте сачували, направите нови приступни кључ.','Secret Access Key was rejected'=>'Secret Access Key је одбијен','SMTP.com has no sender by that name on your account. Check the Sender Name setting against your SMTP.com dashboard, and note it can\'t be left empty.'=>'SMTP.com нема пошиљаоца са тим именом на вашем налогу. Упоредите подешавање Sender Name са својом SMTP.com контролном таблом и имајте у виду да не може остати празно.','That Sender Name doesn\'t exist'=>'То име пошиљаоца не постоји','Your Server API Token is fine, but this server has no stream with that ID. Copy it from the Message Streams page in Postmark, or clear Message Stream ID to use the default.'=>'Ваш Server API Token је у реду, али овај сервер нема ток са тим ИБ-ом. Умножите га са странице Message Streams у Postmark-у или очистите Message Stream ID да бисте користили подразумевани.','That message stream doesn\'t exist'=>'Тај ток порука не постоји','It asked us to try later, so we couldn\'t check your username and password. Verify again in a few minutes.'=>'Затражио је да покушамо касније, па нисмо могли да проверимо ваше корисничко име и лозинку. Поново проверите за неколико минута.','This server accepts a sign-in'=>'Овај сервер прихвата пријаву','The server couldn\'t sign you in right now'=>'Сервер тренутно не може да вас пријави','You can leave Authentication off, but most servers deliver more reliably for senders who sign in. Turn on Authentication in your connection settings and add your username and password.'=>'Проверу идентитета можете оставити искљученом, али већина сервера поузданије испоручује поруке пошиљалаца који се пријаве. Укључите проверу идентитета у подешавањима везе и додајте своје корисничко име и лозинку.','How to create an app password'=>'Како да направите лозинку програма','Your account password won\'t work here. Create an app-specific password in your email account\'s security settings and paste it into the SMTP Password setting.'=>'Лозинка вашег налога овде неће радити. Направите лозинку специфичну за програм у безбедносним подешавањима свог налога е-поште и налепите је у подешавање SMTP Password.','This server needs an app password'=>'Овом серверу је потребна лозинка програма','A wp-config constant is defined for %s. The value was not stored. Remove the constant first, then re-run this command.'=>'За %s је дефинисана wp-config константа. Вредност није сачувана. Прво уклоните константу, а затим поново покрените ову наредбу.','Configuration errors:'=>'Грешке подешавања:','Invalid integer for --%1$s: %2$s'=>'Неисправан цео број за --%1$s: %2$s','Cannot read --%1$s file: %2$s'=>'Није могуће прочитати --%1$s датотеку: %2$s','Invalid email for --%1$s: %2$s'=>'Неисправна е-адреса за --%1$s: %2$s','Invalid value for --%1$s: %2$s (allowed: %3$s)'=>'Неисправна вредност за --%1$s: %2$s (дозвољено: %3$s)','Missing required flag: --%1$s (required when %2$s)'=>'Недостаје обавезна заставица: --%1$s (обавезна када %2$s)','Missing required flag: --%s (needed to fully specify the configuration when other gating flags are set)'=>'Недостаје обавезна заставица: --%s (потребна за потпуно одређивање подешавања када су постављене друге заставице услова)','Missing required flag: --%s'=>'Недостаје обавезна заставица: --%s','Mandrill API key.'=>'Mandrill API кључ.','Elastic Email API key.'=>'Elastic Email API кључ.','Optional Brevo sending domain.'=>'Необавезни Brevo домен за слање.','Brevo (formerly Sendinblue) API key.'=>'Brevo (раније Sendinblue) API кључ.','MailerSend API key.'=>'MailerSend API кључ.','Set if your MailerSend account is on a paid plan.'=>'Поставите ако је ваш MailerSend налог на плаћеном плану.','Mailjet secret key.'=>'Mailjet тајни кључ.','Mailjet API key.'=>'Mailjet API кључ.','SparkPost region (US or EU).'=>'SparkPost регион (US или EU).','SMTP2GO API key.'=>'SMTP2GO API кључ.','SparkPost API key.'=>'SparkPost API кључ.','SMTP.com sender channel name.'=>'Име канала пошиљаоца за SMTP.com.','Resend API key.'=>'Resend API кључ.','SMTP.com API key.'=>'SMTP.com API кључ.','SendLayer API key.'=>'SendLayer API кључ.','Optional Postmark message stream.'=>'Необавезни Postmark ток порука.','Mailgun region (US or EU).'=>'Mailgun регион (US или EU).','Postmark server API token.'=>'Postmark API токен сервера.','Mailgun sending domain.'=>'Mailgun домен за слање.','Mailgun API key.'=>'Mailgun API кључ.','Optional sending domain.'=>'Необавезни домен за слање.','SendGrid API key.'=>'SendGrid API кључ.','SMTP password.'=>'SMTP лозинка.','SMTP username.'=>'SMTP корисничко име.','Auto TLS when supported by server.'=>'Аутоматски TLS када га сервер подржава.','Whether the SMTP server requires authentication.'=>'Да ли SMTP сервер захтева потврђивање идентитета.','Encryption: none, ssl, or tls.'=>'Шифровање: none, ssl или tls.','SMTP server port (e.g. 25, 465, 587).'=>'Порт SMTP сервера (нпр. 25, 465, 587).','Hide Awesome Motive product notifications.'=>'Сакриј обавештења о производима Awesome Motive.','SMTP server hostname.'=>'Име домаћина SMTP сервера.','Disable all outgoing email.'=>'Искључи сву одлазну е-пошту.','Force From name on every outgoing message.'=>'Наметни име пошиљаоца на свакој одлазној поруци.','Force From email on every outgoing message.'=>'Наметни е-адресу пошиљаоца на свакој одлазној поруци.','Set Return-Path to match From email.'=>'Постави Return-Path да одговара е-адреси пошиљаоца.','Mailer to use. One of: %s.'=>'Услуга слања која се користи. Једна од: %s.','From name.'=>'Име пошиљаоца.','From email address.'=>'Е-адреса пошиљаоца.','Rate Limiting'=>'Ограничавање учесталости','Required when %s.'=>'Обавезно када %s.','These flags accept their value as a literal (--flag=value), from a file (--flag-file=<path>), or from an environment variable (WPMS_<UPPER>).'=>'Ове заставице прихватају вредност као дословну (--flag=value), из датотеке (--flag-file=<path>) или из променљиве окружења (WPMS_<UPPER>).','CONFIGURATION FLAGS'=>'ЗАСТАВИЦЕ ПОДЕШАВАЊА','and'=>'и','wp_mail() returned false (no further detail available).'=>'wp_mail() је вратио false (нема додатних детаља).','Test email failed: %s'=>'Пробна е-порука није успела: %s','Test email sent to %1$s via mailer "%2$s".'=>'Пробна е-порука је послата на %1$s преко услуге слања „%2$s“.','No mailer is configured. Run `wp wp-mail-smtp setup ...` first.'=>'Није подешена ниједна услуга слања. Прво покрените `wp wp-mail-smtp setup ...`.','Configured WP Mail SMTP (mailer: %s). Run `wp wp-mail-smtp test <recipient>` to verify.'=>'WP Mail SMTP је подешен (услуга слања: %s). Покрените `wp wp-mail-smtp test <recipient>` ради провере.','Pass a valid recipient: wp wp-mail-smtp test <recipient>'=>'Проследите исправног примаоца: wp wp-mail-smtp test <recipient>','No settings were stored — every flag passed was shadowed by a wp-config constant. Remove the constants and re-run, or pass flags for non-shadowed settings.'=>'Ниједно подешавање није сачувано — сваку прослеђену заставицу засенила је wp-config константа. Уклоните константе и поново покрените или проследите заставице за подешавања која нису засенчена.','No configuration flags provided. Pass at least --mail.from_email, --mail.from_name, and --mail.mailer (plus the credentials for that mailer).'=>'Нису наведене заставице подешавања. Проследите бар --mail.from_email, --mail.from_name и --mail.mailer (плус акредитиве за ту услугу слања).','WP Mail SMTP is already configured (mailer: %s).
Use `wp wp-mail-smtp option set <group>.<key> <value>` to change individual settings, or pass --force to override this check.'=>'WP Mail SMTP је већ подешен (услуга слања: %s).
Користите `wp wp-mail-smtp option set <group>.<key> <value>` да промените појединачна подешавања или проследите --force да заобиђете ову проверу.','Skip the refusal that fires when the plugin is already configured. Does NOT wipe existing settings — only flags you pass are written.'=>'Прескочи одбијање које се јавља када је додатак већ подешен. НЕ брише постојећа подешавања — уписују се само заставице које проследите.','Configure WP Mail SMTP from the command line.'=>'Подесите WP Mail SMTP из командне линије.','Updated %s.'=>'Ажуриран %s.','No value provided for --%1$s (positional, --value-file, or env var %2$s).'=>'Није наведена вредност за --%1$s (позициона, --value-file или променљива окружења %2$s).','Could not store %s — value is shadowed by a wp-config constant.'=>'Није могуће сачувати %s — вредност је засенчена wp-config константом.','(not set)'=>'(није постављено)','Unknown flag: %s'=>'Непозната заставица: %s','Action must be one of: get, set, list.'=>'Радња мора бити једна од: get, set, list.','Output format for `list`. table | json | yaml. Default: table.'=>'Облик излаза за `list`. table | json | yaml. Подразумевано: table.','Show sensitive values instead of masking them.'=>'Прикажи осетљиве вредности уместо да их маскираш.','Read a sensitive value from a file.'=>'Прочитај осетљиву вредност из датотеке.','Value (required for set; can also be supplied via --value-file or env var).'=>'Вредност (обавезна за set; може се навести и преко --value-file или променљиве окружења).','Sensitive: also accepts --%1$s-file=<path> or env var %2$s.'=>'Осетљиво: прихвата и --%1$s-file=<path> или променљиву окружења %2$s.','Usage: wp wp-mail-smtp option set <group>.<key> <value>'=>'Употреба: wp wp-mail-smtp option set <group>.<key> <value>','Usage: wp wp-mail-smtp option get <group>.<key>'=>'Употреба: wp wp-mail-smtp option get <group>.<key>','Dotted flag (e.g. smtp.host). Required for get and set.'=>'Заставица са тачкама (нпр. smtp.host). Обавезна за get и set.','One of: get, set, list.'=>'Једна од: get, set, list.','Read and write individual WP Mail SMTP settings.'=>'Читајте и уписујте појединачна WP Mail SMTP подешавања.','You\'ve reached your free SendLayer limit. Emails are failing and won\'t be delivered! <a href="%s" target="_blank" rel="noopener noreferrer">Upgrade your plan</a> to start sending again.'=>'Достигли сте ограничење бесплатног SendLayer-а. Е-поруке не успевају и неће бити испоручене! <a href="%s" target="_blank" rel="noopener noreferrer">Надоградите свој план</a> да бисте поново почели да шаљете.','You\'ve used %1$d of your %2$d free SendLayer emails. <a href="%3$s" target="_blank" rel="noopener noreferrer">Upgrade your plan</a> to keep your emails flowing without interruption.'=>'Искористили сте %1$d од својих %2$d бесплатних SendLayer е-порука. <a href="%3$s" target="_blank" rel="noopener noreferrer">Надоградите свој план</a> да би ваше е-поруке наставиле да се шаљу без прекида.','You\'re sending through a shared SendLayer domain. For better deliverability, add your own domain on the <a href="%1$s" target="_blank" rel="noopener noreferrer">SendLayer dashboard</a> and follow our <a href="%2$s" target="_blank" rel="noopener noreferrer">custom domain guide</a>.'=>'Шаљете преко дељеног SendLayer домена. За бољу испоручивост додајте сопствени домен на <a href="%1$s" target="_blank" rel="noopener noreferrer">SendLayer контролној табли</a> и пратите наш <a href="%2$s" target="_blank" rel="noopener noreferrer">водич за произвољни домен</a>.','SMTP Debug:'=>'SMTP отклањање грешака:','The mail transport accepted the message but rejected %1$d recipient address: %2$s. Other recipients in the same email have been sent.'=>'Систем за пренос поште прихватио је поруку, али је одбио %1$d адресу примаоца: %2$s. Остали примаоци у истој е-поруци су добили поруку.' . "\0" . 'Систем за пренос поште прихватио је поруку, али је одбио %1$d адресе прималаца: %2$s. Остали примаоци у истој е-поруци су добили поруку.' . "\0" . 'Систем за пренос поште прихватио је поруку, али је одбио %1$d адреса прималаца: %2$s. Остали примаоци у истој е-поруци су добили поруку.','Install WPCode to use this snippet.'=>'Поставите WPCode да бисте користили овај исечак.','Deactivate %1$s'=>'Искључи %1$s','Unknown'=>'Непознат','Could not dismiss the section. Please reload the page and try again.'=>'Није могуће одбацити одељак. Поново учитајте страницу и покушајте поново.','Could not activate ActiveLayer. Please activate it from the Plugins page.'=>'Није могуће укључити ActiveLayer. Укључите га са странице додатака.','Could not install ActiveLayer. Please download it from WordPress.org and install manually.'=>'Није могуће поставити ActiveLayer. Преузмите га са WordPress.org и поставите ручно.','Get ActiveLayer'=>'Набави ActiveLayer','View ActiveLayer Settings'=>'Погледај ActiveLayer подешавања','ActiveLayer is protecting customer registration and product reviews.'=>'ActiveLayer штити регистрацију купаца и рецензије производа.','Connect Your Free Account'=>'Повежите свој бесплатни налог','ActiveLayer is active. Connect your free account to start blocking fake registrations and review spam.'=>'ActiveLayer је активан. Повежите свој бесплатни налог да бисте почели да блокирате лажне регистрације и непожељне рецензије.','Blocks bot signups and review spam on My Account, checkout, and product reviews. No CAPTCHA anywhere on the path to purchase. Free plugin from WordPress.org, with 1,000 free spam checks and no credit card required.'=>'Блокира регистрације ботова и непожељне рецензије на страницама „Мој налог“, плаћања и рецензија производа. Без CAPTCHA-е било где на путу до куповине. Бесплатан додатак са WordPress.org, са 1.000 бесплатних провера непожељних порука и без потребе за кредитном картицом.','Stop Fake Customer Registrations and Review Spam'=>'Зауставите лажне регистрације купаца и непожељне рецензије','Translations'=>'Преводи','Dismiss this section'=>'Одбаци овај одељак','Backups'=>'Резервне копије','Spam Protection'=>'Заштита од непожељних порука','Privacy Compliance'=>'Усклађеност са прописима о приватности','Open WPVibe'=>'Отвори WPVibe','Open WPVibe and authorize your AI client in one click.'=>'Отворите WPVibe и овластите свој ВИ клијент једним притиском.','Connect Your AI Assistant'=>'Повежите свог ВИ помоћника','Install WPVibe'=>'Постави WPVibe','WPVibe Installed & Activated'=>'WPVibe је постављен и укључен','WPVibe'=>'WPVibe','Install WPVibe from the WordPress.org plugin repository.'=>'Поставите WPVibe из складишта додатака на WordPress.org.','WPVibe is free to use. Explore the docs to see every ability your AI assistant now has for your WordPress site.'=>'WPVibe је бесплатан за коришћење. Истражите документацију да бисте видели све способности које ваш ВИ помоћник сада има за ваш Вордпресов сајт.','View Docs'=>'Погледајте документацију','See What Your AI Can Do'=>'Погледајте шта ваша ВИ може','WPVibe screenshot'=>'Снимак екрана WPVibe','Run 40+ WP-CLI commands without leaving your AI chat.'=>'Покрећите више од 40 WP-CLI наредби без напуштања ВИ ћаскања.','One-click setup in about a minute.'=>'Подешавање једним притиском за око минут.','Create and edit posts, pages, media, and users through conversation.'=>'Правите и уређујте чланке, странице, садржај и кориснике кроз разговор.','Works with Claude, ChatGPT, Cursor, and any MCP client.'=>'Ради са Claude, ChatGPT, Cursor и било којим MCP клијентом.','Manage WordPress through conversation, not clicking.'=>'Управљајте Вордпресом кроз разговор, а не притискањем.','WPVibe connects your AI assistant straight to your WordPress site, so you can create posts, manage plugins, and run tasks just by asking. Built-in guardrails keep your site safe.'=>'WPVibe повезује вашег ВИ помоћника директно са вашим Вордпресовим сајтом, тако да можете правити чланке, управљати додацима и покретати задатке само тако што ћете затражити. Уграђене заштите чувају ваш сајт безбедним.','Backup'=>'Резервна копија','WP Mail SMTP ♥ WPVibe'=>'WP Mail SMTP ♥ WPVibe','Your AI Just Learned WordPress'=>'Ваша ВИ је управо научила Вордпрес','Run Setup Wizard'=>'Покрени чаробњак за подешавање','WPConsent has an intuitive setup wizard to guide you through the cookie consent configuration process.'=>'WPConsent има интуитиван чаробњак за подешавање који вас води кроз подешавање пристанка на колачиће.','Set Up WPConsent'=>'Подеси WPConsent','Activate WPConsent'=>'Укључи WPConsent','WPConsent Installed & Activated'=>'WPConsent је постављен и укључен','Install WPConsent'=>'Постави WPConsent','Install WPConsent from the WordPress.org plugin repository.'=>'Поставите WPConsent из складишта додатака на WordPress.org.','Install & Activate WPConsent'=>'Постави и укључи WPConsent','WPConsent Pro Installed & Activated'=>'WPConsent Pro је постављен и укључен','With WPConsent Pro you can access advanced features like geolocation, popup layout, records of consent, multilanguage support, and more.'=>'Уз WPConsent Pro можете приступити напредним могућностима као што су геолокација, распоред искачућег прозора, записи о пристанку, подршка за више језика и друго.','Get Advanced Cookie Consent Features'=>'Набавите напредне могућности пристанка на колачиће','WPConsent screenshot'=>'Снимак екрана WPConsent','Self-hosted. Your data remains on your site.'=>'Самостално смештање. Ваши подаци остају на вашем сајту.','Peace of mind knowing you’re aligned with global laws.'=>'Мир јер знате да сте усклађени са светским законима.','Tools like Google Analytics and Facebook Pixel paused until consent.'=>'Алати као што су Google Analytics и Facebook Pixel паузирани су до пристанка.','A professional banner that fits your site.'=>'Професионална трака која одговара вашем сајту.','Built for transparency. Designed for ease.'=>'Направљено за транспарентност. Осмишљено за лакоћу.','Build trust with clear, compliant privacy practices. WPConsent adds clean, professional banners and handles the technical side for you.'=>'Изградите поверење јасним, усклађеним праксама приватности. WPConsent додаје чисте, професионалне траке и брине о техничкој страни уместо вас.','WP Mail SMTP ♥ WPConsent'=>'WP Mail SMTP ♥ WPConsent','Make Your Website Privacy-Compliant in Minutes'=>'Усагласите свој веб сајт са прописима о приватности за неколико минута','Open WPCode'=>'Отвори WPCode','Open WPCode to create your first snippet and start customizing your site safely.'=>'Отворите WPCode да бисте направили свој први исечак и почели безбедно да прилагођавате сајт.','WPCode Installed & Activated'=>'WPCode је постављен и укључен','Set Up WPCode'=>'Подеси WPCode','Install WPCode'=>'Постави WPCode','WPCode'=>'WPCode','WPCode Pro Installed & Activated'=>'WPCode Pro је постављен и укључен','Install WPCode from the WordPress.org plugin repository.'=>'Поставите WPCode из складишта додатака на WordPress.org.','WPCode Pro adds conditional logic, a cloud snippet library, revisions, and conversion pixels to your workflow.'=>'WPCode Pro вашем радном току додаје условну логику, библиотеку исечака у облаку, ревизије и пикселе за конверзију.','Get Advanced Code Snippet Features'=>'Набавите напредне могућности исечака кода','WPCode screenshot'=>'Снимак екрана WPCode','Auto-insert and one-click toggle for every snippet.'=>'Аутоматско убацивање и укључивање једним притиском за сваки исечак.','100+ ready-made snippets for common tasks.'=>'Више од 100 готових исечака за честе задатке.','PHP, JavaScript, CSS, and HTML all supported.'=>'Подржани су PHP, JavaScript, CSS и HTML.','Add snippets without editing theme files.'=>'Додајте исечке без уређивања датотека теме.','Trusted by over 3 million websites.'=>'Верује му више од 3 милиона веб сајтова.','WPCode lets you safely add PHP, JavaScript, CSS, and HTML snippets with no theme edits and no risk of losing changes when your theme updates. Built-in error handling keeps your site from breaking.'=>'WPCode вам омогућава да безбедно додате PHP, JavaScript, CSS и HTML исечке без измена теме и без ризика да изгубите измене када се тема ажурира. Уграђено руковање грешкама спречава да се сајт поквари.','WP Mail SMTP ♥ WPCode'=>'WP Mail SMTP ♥ WPCode','Add Custom Code to WordPress Without Breaking Your Site'=>'Додајте произвољни кôд у Вордпрес без кварења сајта','Add your API key on the settings page and choose the languages for your site.'=>'Додајте свој API кључ на страници подешавања и изаберите језике за свој сајт.','Connect Universally'=>'Повежи Universally','Universally Installed & Activated'=>'Universally је постављен и укључен','Activate Universally'=>'Укључи Universally','Install Universally'=>'Постави Universally','Install & Activate Universally'=>'Постави и укључи Universally','Install Universally from the WordPress.org plugin repository.'=>'Поставите Universally из складишта додатака на WordPress.org.','Upgrade your plan for more languages and higher translation limits.'=>'Надоградите свој план за више језика и већа ограничења превођења.','Reach Even More of the World'=>'Досегните још већи део света','Exclude specific pages, classes, or IDs from translation.'=>'Изузмите одређене странице, класе или ID-ове из превођења.','Universally screenshot'=>'Снимак екрана Universally','Auto-translates new content when you publish.'=>'Аутоматски преводи нови садржај када објавите.','Multilingual SEO with translated URLs and meta.'=>'Вишејезични SEO са преведеним URL-овима и метаподацима.','Built for global reach. Designed for everyone.'=>'Направљено за глобални досег. Осмишљено за свакога.','AI translation into 110+ languages.'=>'ВИ превод на више од 110 језика.','Universally uses AI to translate your entire WordPress site into 110+ languages in minutes, understanding context and keeping your brand voice intact. No coding required.'=>'Universally користи ВИ да за неколико минута преведе цео ваш Вордпресов сајт на више од 110 језика, разумевајући контекст и чувајући глас вашег бренда. Није потребно програмирање.','WP Mail SMTP ♥ Universally'=>'WP Mail SMTP ♥ Universally','Translate Your Website and Go Global in Minutes'=>'Преведите свој веб сајт и изађите на светско тржиште за неколико минута','Duplicator Pro Installed & Activated'=>'Duplicator Pro је постављен и укључен','Backup Created'=>'Резервна копија је направљена','Create First Backup'=>'Направи прву резервну копију','Back up your site, in just one click.'=>'Направите резервну копију сајта једним притиском.','Create Your First Backup'=>'Направите своју прву резервну копију','Duplicator Installed & Activated'=>'Duplicator је постављен и укључен','Activate Duplicator'=>'Укључи Duplicator','Install Duplicator'=>'Постави Duplicator','Your first step toward bulletproof backups.'=>'Ваш први корак ка непробојним резервним копијама.','Install & Activate Duplicator'=>'Постави и укључи Duplicator','Cloud Backups Set Up'=>'Резервне копије у облаку су подешене','Set Up Cloud Backups'=>'Подеси резервне копије у облаку','Set Up Scheduled Cloud Backups'=>'Подесите заказане резервне копије у облаку','Keep your data safe forever with automatic daily backups to Google Drive, Dropbox, or Amazon S3.'=>'Чувајте своје податке заувек уз аутоматске дневне резервне копије на Google Drive, Dropbox или Amazon S3.','Duplicator screenshot'=>'Снимак екрана Duplicator','Schedule daily backups so you never have to think about it.'=>'Закажите дневне резервне копије да никада не морате да размишљате о томе.','Restore your site with one click if anything goes wrong.'=>'Вратите сајт једним притиском ако нешто пође наопако.','Back up your entire site automatically.'=>'Аутоматски правите резервну копију целог сајта.','Store backups safely in Google Drive, Dropbox, or Amazon S3.'=>'Чувајте резервне копије безбедно на Google Drive, Dropbox или Amazon S3.','Trusted by over 1.5 million websites.'=>'Верује му више од 1,5 милиона веб сајтова.','Your email settings and sender reputation live in your database. One bad update, one crash, and everything is gone. Duplicator backs up your entire WordPress site automatically so you can restore with one click.'=>'Ваша подешавања е-поште и углед пошиљаоца налазе се у вашој бази података. Једно лоше ажурирање, један пад, и све нестаје. Duplicator аутоматски прави резервну копију целог Вордпресовог сајта да бисте могли да га вратите једним притиском.','WP Mail SMTP ♥ Duplicator'=>'WP Mail SMTP ♥ Duplicator','WP Mail SMTP Delivers It. Duplicator Protects It.'=>'WP Mail SMTP испоручује. Duplicator штити.','Open Settings'=>'Отвори подешавања','Add your free API key on the settings page to switch on protection.'=>'Додајте свој бесплатни API кључ на страници подешавања да бисте укључили заштиту.','Setup Complete'=>'Подешавање је завршено','Connect ActiveLayer'=>'Повежи ActiveLayer','Activate ActiveLayer'=>'Укључи ActiveLayer','ActiveLayer Installed & Activated'=>'ActiveLayer је постављен и укључен','Install ActiveLayer'=>'Постави ActiveLayer','Install ActiveLayer from the WordPress.org plugin repository.'=>'Поставите ActiveLayer из складишта додатака на WordPress.org.','Protect Even More of Your Site'=>'Заштитите још већи део свог сајта','Upgrade your plan for higher limits and advanced controls across all your forms, comments, and reviews.'=>'Надоградите свој план за већа ограничења и напредне контроле у свим обрасцима, коментарима и рецензијама.','Install & Activate ActiveLayer'=>'Постави и укључи ActiveLayer','Step 3'=>'Корак 3','ActiveLayer screenshot'=>'Снимак екрана ActiveLayer','Works with 9+ popular form plugins out of the box.'=>'Ради са више од 9 популарних додатака за обрасце одмах по постављању.','Millisecond verdicts, invisible to legitimate users.'=>'Одлуке за милисекунде, невидљиве стварним корисницима.','No CAPTCHAs, no friction for real visitors.'=>'Без CAPTCHA-е, без препрека за стварне посетиоце.','AI detection using content, sender reputation, and behavior signals.'=>'ВИ откривање помоћу садржаја, угледа пошиљаоца и сигнала понашања.','Smarter protection for your forms, comments, and reviews.'=>'Паметнија заштита за ваше обрасце, коментаре и рецензије.','ActiveLayer uses server-side AI to catch spam in milliseconds, invisible to your real visitors and deadly to bots. No CAPTCHAs, no friction, no lost conversions.'=>'ActiveLayer користи ВИ на серверу да ухвати непожељне поруке за милисекунде, невидљив стварним посетиоцима, а смртоносан за ботове. Без CAPTCHA-е, без препрека, без изгубљених конверзија.','WP Mail SMTP ♥ ActiveLayer'=>'WP Mail SMTP ♥ ActiveLayer','Block Spam Without Blocking Real Visitors'=>'Блокирајте непожељне поруке без блокирања стварних посетилаца','Activate Now'=>'Укључи сада','Install Now'=>'Постави сада','Activating...'=>'Укључивање у току...','Installing...'=>'Постављање...','Plugin unavailable.'=>'Додатак није доступан.','You do not have permission.'=>'Немате дозволу.','Step 2'=>'Корак 2','Protect your site with automated backups'=>'Заштитите свој сајт аутоматизованим резервним копијама','Step 1'=>'Корак 1','Automated, encrypted backups with 1-click restore to keep your site safe.'=>'Аутоматизоване, шифроване резервне копије са враћањем једним притиском чувају ваш сајт безбедним.','Add Secure WordPress Backups'=>'Додајте безбедне Вордпресове резервне копије','Add a cookie consent banner to your site and meet privacy laws in minutes.'=>'Додајте траку за пристанак на колачиће на свој сајт и испуните законе о приватности за неколико минута.','Stay GDPR & Privacy compliant'=>'Будите усклађени са GDPR-ом и прописима о приватности','Stay GDPR & Privacy Compliant'=>'Будите усклађени са GDPR-ом и прописима о приватности','Stop spam at the door'=>'Зауставите непожељне поруке на улазу','Catch spam in milliseconds with AI, invisible to your real visitors.'=>'Ухватите непожељне поруке за милисекунде помоћу ВИ, невидљиво за стварне посетиоце.','Smarter Spam Protection for WordPress'=>'Паметнија заштита од непожељних порука за Вордпрес','Install %s (Free)'=>'Постави %s (бесплатно)','%1$s with our sister plugin %2$s'=>'%1$s уз наш сестрински додатак %2$s','Pro Tip:'=>'Професионални савет:','A person celebrating after sending an email.'=>'Особа која слави после слања е-поруке.','for WP Mail SMTP users, applied at checkout.'=>'за кориснике WP Mail SMTP, примењено при плаћању.','Priority support from our email deliverability experts'=>'Приоритетна подршка наших стручњака за испоручивост е-поште','...and much more!'=>'...и још много тога!','Level Up Your Email Game! Unlock these %s features and get even more from WP Mail SMTP.'=>'Подигните своју е-пошту на виши ниво! Откључајте ове %s могућности и извуците још више из WP Mail SMTP.','Test email sent successfully! Check your inbox to confirm delivery.'=>'Пробна е-порука је успешно послата! Проверите сандуче да бисте потврдили испоруку.','Never miss an email with an automatic backup mailer'=>'Никада не пропустите е-поруку уз аутоматску резервну услугу слања','Get instant failure alerts via Email, Slack, SMS, Discord, etc'=>'Добијајте тренутна упозорења о неуспеху преко е-поште, Slack-а, SMS-а, Discord-а итд.','Log, track, and resend any email your site sends'=>'Бележите, пратите и поново шаљите сваку е-поруку коју ваш сајт шаље','Connect WP Mail SMTP to multiple providers, then route emails through your preferred provider based on custom conditional logic rules.'=>'Повежите WP Mail SMTP са више пружалаца услуга, а затим усмеравајте е-поруке преко жељеног пружаоца на основу произвољних правила условне логике.','Send emails through more than one SMTP provider.'=>'Шаљите е-поруке преко више од једног SMTP пружаоца.','Includes total number of emails sent, emails delivered, failed emails, opened emails, links clicked.'=>'Обухвата укупан број послатих е-порука, испоручених е-порука, неуспелих е-порука, отворених е-порука и притиснутих веза.','View advanced email reports in your WordPress dashboard.'=>'Прегледајте напредне извештаје о е-пошти на Вордпресовој контролној табли.','Monitor email open and click-through rates.'=>'Пратите стопе отварања и притисака на везе.','Open & Click Tracking'=>'Праћење отварања и притисака','Choose which default WordPress email notifications your site sends.'=>'Изаберите која подразумевана Вордпресова обавештења е-поштом ваш сајт шаље.','Manage Email Notifications'=>'Управљај обавештењима е-поштом','Choose one primary connection, then select another connection as a backup. If an email fails to send via your primary connection, it will automatically be resent using your backup connection.'=>'Изаберите једну главну везу, а затим изаберите другу везу као резервну. Ако е-порука не успе да се пошаље преко главне везе, аутоматски ће бити поново послата преко резервне везе.','Connect to multiple SMTP providers.'=>'Повежите се са више SMTP пружалаца.','Email, Slack, SMS via Twilio, Microsoft Teams, Discord, or custom webhooks.'=>'Е-пошта, Slack, SMS преко Twilio-а, Microsoft Teams, Discord или произвољне куке.','Receive an alert via your preferred channel whenever an email fails to send.'=>'Добијте упозорење преко жељеног канала кад год е-порука не успе да се пошаље.','View detailed email logs in your WordPress dashboard.'=>'Прегледајте детаљне дневнике е-поште на Вордпресовој контролној табли.','Includes delivery status, email content, attachments, source, and technical details, plus the option to resend the email.'=>'Обухвата стање испоруке, садржај е-поруке, прилоге, извор и техничке детаље, уз могућност поновног слања е-поруке.','Email Logging'=>'Бележење е-поште','Access Outlook immediately with Outlook One Click Setup'=>'Одмах приступите Outlook-у уз подешавање Outlook-а једним притиском','Manually connect to your account with Google Workspace/ Gmail mailer'=>'Ручно се повежите са својим налогом помоћу услуге слања Google Workspace/ Gmail','Access your Google Workspace immediately with Gmail One Click Setup'=>'Одмах приступите свом Google Workspace-у уз подешавање Gmail-а једним притиском','Google Workspace'=>'Google Workspace','View email sending errors in your WordPress dashboard.'=>'Прегледајте грешке слања е-поште на Вордпресовој контролној табли.','Receive a detailed report of your total and previous week\'s metrics for emails sent, failed, and delivered, plus statistics for your top 5 popular emails.'=>'Добијте детаљан извештај о укупним мерама и мерама претходне недеље за послате, неуспеле и испоручене е-поруке, уз статистику за 5 најпопуларнијих е-порука.','Receive a basic report of your total emails sent including a summary of the previous week\'s sent emails.'=>'Добијте основни извештај о укупном броју послатих е-порука, укључујући сажетак е-порука послатих претходне недеље.','Weekly Email Summaries'=>'Недељни сажеци е-поште','Amazon SES, Microsoft 365 / Outlook, and Zoho Mail.'=>'Amazon SES, Microsoft 365 / Outlook и Zoho Mail.','SendLayer, SMTP.com, Brevo, Google Workspace / Gmail, Mailgun, Postmark, SendGrid, SMTP2GO, Sparkpost, and any other SMTP provider using your SMTP credentials.'=>'SendLayer, SMTP.com, Brevo, Google Workspace / Gmail, Mailgun, Postmark, SendGrid, SMTP2GO, Sparkpost и било којим другим SMTP пружаоцем помоћу својих SMTP акредитива.','Connect your WordPress site to any of our Lite SMTP providers, as well as:'=>'Повежите свој Вордпресов сајт са било којим од наших Lite SMTP пружалаца, као и са:','Connect your WordPress site to any of the following SMTP providers:'=>'Повежите свој Вордпресов сајт са било којим од следећих SMTP пружалаца:','Use conditional logic to send emails through different providers.'=>'Користите условну логику за слање е-порука преко различитих пружалаца.','Advanced mailers'=>'Напредне услуге слања','Connect with top providers like Amazon SES, Microsoft 365 / Outlook, and Zoho Mail.'=>'Повежите се са водећим пружаоцима као што су Amazon SES, Microsoft 365 / Outlook и Zoho Mail.','An easy and secure way to configure your Gmail and Outlook mailers.'=>'Лак и безбедан начин подешавања услуга слања Gmail и Outlook.','One-Click Mailer Setups'=>'Подешавање услуга слања једним притиском','Set up a secondary email provider in case your primary provider fails.'=>'Подесите секундарног пружаоца е-поште у случају да главни пружалац не успе.','Backup Connections'=>'Резервне везе','Receive immediate alerts for email failures to quickly address issues.'=>'Добијајте тренутна упозорења о неуспесима е-поште да бисте брзо решили проблеме.','for WP Mail SMTP Lite users'=>'за кориснике WP Mail SMTP Lite','Save details about every email sent from your WordPress site.'=>'Чувајте детаље о свакој е-поруци послатој са вашег Вордпресовог сајта.','Email Failure Alerts'=>'Упозорења о неуспеху е-поште','$50 OFF'=>'50 $ ПОПУСТА','Not available'=>'Није доступно','Available'=>'Доступно','Partially available'=>'Делимично доступно','Lite'=>'Lite','Lite vs Pro: What\'s the Difference?'=>'Lite или Pro: у чему је разлика?','Compare Lite vs Pro features'=>'Упореди могућности Lite и Pro издања','Features you\'ll love with Pro'=>'Могућности које ћете заволети уз Pro','Get email logs, delivery tracking, backup connections, and instant failure alerts so you catch issues before your customers do.'=>'Добијте дневнике е-поште, праћење испоруке, резервне везе и тренутна упозорења о неуспеху, тако да уочите проблеме пре ваших купаца.','Take complete control of your WordPress emails'=>'Преузмите потпуну контролу над својим Вордпресовим е-порукама','Get Pro'=>'Набави Pro','View'=>'Погледај','Edit Snippet'=>'Уреди исечак','Sorry, we didn\'t find any snippets that match your criteria.'=>'Нажалост, нисмо пронашли ниједан исечак који одговара вашим мерилима.','Search Snippets'=>'Претражи исечке','Using WPCode, you can install WP Mail SMTP code snippets with 1 click directly from this page or the <a href="%s" target="_blank" rel="noopener noreferrer">WPCode library</a>.'=>'Помоћу WPCode-а можете поставити WP Mail SMTP исечке кода једним притиском директно са ове странице или из <a href="%s" target="_blank" rel="noopener noreferrer">WPCode библиотеке</a>.','Activate it manually.'=>'Укључите га ручно.','WPCode could not be installed. Please try again.'=>'WPCode није могао да се постави. Покушајте поново.','WPCode was installed but could not be activated.'=>'WPCode је постављен, али није могао да се укључи.','Activate WPCode'=>'Укључи WPCode','WPCode is installed but not active. Activate it to install WP Mail SMTP code snippets with 1 click right from this page.'=>'WPCode је постављен, али није активан. Укључите га да бисте постављали WP Mail SMTP исечке кода једним притиском директно са ове странице.','Learn more about WPCode'=>'Сазнајте више о WPCode-у','Please Activate WPCode to Use the Snippet Library'=>'Укључите WPCode да бисте користили библиотеку исечака','Install & Activate WPCode'=>'Постави и укључи WPCode','Using WPCode, you can install WP Mail SMTP code snippets with 1 click right from this page.'=>'Помоћу WPCode-а можете поставити WP Mail SMTP исечке кода једним притиском директно са ове странице.','Could not load this snippet. Please try again.'=>'Није могуће учитати овај исечак. Покушајте поново.','Please Install WPCode to Use the Snippet Library'=>'Поставите WPCode да бисте користили библиотеку исечака','Loading snippet…'=>'Учитавање исечка…','Installing…'=>'Постављање…','Install Snippet'=>'Постави исечак','Code Snippets'=>'Исечци кода','Pro feature'=>'Pro могућност','View Abilities API Documentation'=>'Погледај документацију Abilities API-ја','Everything WP Mail SMTP Can Do With AI'=>'Све што WP Mail SMTP може помоћу ВИ','Connect your WordPress site and WP Mail SMTP to AI assistants like Claude, ChatGPT, Cursor, and more. Ask them to review your email logs, sending stats, and debug events in plain English. No copy-pasting, no exports. Connect them with the free %s plugin.'=>'Повежите свој Вордпресов сајт и WP Mail SMTP са ВИ помоћницима као што су Claude, ChatGPT, Cursor и други. Замолите их да прегледају ваше дневнике е-поште, статистику слања и догађаје за отклањање грешака обичним језиком. Без умножавања и убацивања, без извоза. Повежите их помоћу бесплатног додатка %s.','Use WP Mail SMTP With Your Favorite AI'=>'Користите WP Mail SMTP са својом омиљеном ВИ','WordPress Abilities API + WP Mail SMTP'=>'WordPress Abilities API + WP Mail SMTP','List recorded send errors and debug entries'=>'Набројте забележене грешке слања и уносе за отклањање грешака','Scope stats to a single mailer and check the success rate'=>'Ограничите статистику на једну услугу слања и проверите стопу успешности','See aggregate sending stats for any period or date range'=>'Погледајте збирну статистику слања за било који период или опсег датума','Email Stats'=>'Статистика е-поште','Get a single email\'s full details and content'=>'Добијте све детаље и садржај једне е-поруке','Browse and filter logged emails by status, mailer, date, and recipient'=>'Прегледајте и филтрирајте забележене е-поруке по стању, услузи слања, датуму и примаоцу','Install & Activate WPVibe'=>'Постави и укључи WPVibe','Activate WPVibe'=>'Укључи WPVibe','Set Up WPVibe'=>'Подеси WPVibe','AI MCP'=>'ВИ MCP','Something went wrong. Please try again.'=>'Догодила се грешка. Покушајте поново.','Make your WordPress site accessible to everyone. Automatic accessibility fixes and a visitor widget, no coding required.'=>'Учините свој Вордпресов сајт доступним свима. Аутоматске исправке приступачности и виџет за посетиоце, без програмирања.','Universally'=>'Universally','Vibe AI'=>'Vibe AI','AI-powered tools for WordPress. Work faster and smarter with automation built for your WordPress workflow.'=>'Алати за Вордпрес засновани на ВИ. Радите брже и паметније уз аутоматизацију направљену за ваш Вордпресов радни ток.','Stay GDPR & privacy compliant. Add a cookie consent banner to your site and meet privacy laws in minutes.'=>'Будите усклађени са GDPR-ом и прописима о приватности. Додајте траку за пристанак на колачиће на свој сајт и испуните законе о приватности за неколико минута.','WPConsent'=>'WPConsent','Smarter spam protection for WordPress. Catch spam in milliseconds with AI, invisible to your real visitors.'=>'Паметнија заштита од непожељних порука за Вордпрес. Ухватите непожељне поруке за милисекунде помоћу ВИ, невидљиво за стварне посетиоце.','ActiveLayer'=>'ActiveLayer','Need Help?'=>'Треба вам помоћ?','Still stuck? Please log in to your <a href="%s" target="_blank" rel="noopener noreferrer">WP Mail SMTP account</a> and submit a support ticket with the error log.'=>'И даље сте заглављени? Пријавите се на свој <a href="%s" target="_blank" rel="noopener noreferrer">WP Mail SMTP налог</a> и пошаљите захтев за подршку уз дневник грешака.','Still stuck? Get priority support by <a href="%1$s" target="_blank" rel="noopener noreferrer">Upgrading to Pro</a> or <a href="%2$s" target="_blank" rel="noopener noreferrer">create a support thread</a> along with the error log on WordPress.org forums. '=>'И даље сте заглављени? Добијте приоритетну подршку <a href="%1$s" target="_blank" rel="noopener noreferrer">надоградњом на Pro</a> или <a href="%2$s" target="_blank" rel="noopener noreferrer">отворите тему подршке</a> уз дневник грешака на форумима WordPress.org. ','Need hands-on help? Our <a href="%s" target="_blank" rel="noopener noreferrer">White Glove Setup</a> handles everything for you, just share your site details and we’ll do the rest.'=>'Треба вам непосредна помоћ? Наше <a href="%s" target="_blank" rel="noopener noreferrer">White Glove подешавање</a> брине о свему уместо вас, само поделите детаље сајта, а ми ћемо урадити остало.','Triple-check your plugin settings, reconfigure if needed to make sure everything is correct.'=>'Трипут проверите подешавања додатка, по потреби их поново подесите да бисте били сигурни да је све исправно.','Resolve your email sending issues with <a href="#" class="js-wp-mail-smtp-sendlayer-quick-connect-link wpms:focus:outline-none! wpms:focus:shadow-none!">SendLayer</a>, and send your <strong>first 200 emails for free</strong> with just a few clicks!'=>'Решите проблеме са слањем е-поште помоћу <a href="#" class="js-wp-mail-smtp-sendlayer-quick-connect-link wpms:focus:outline-none! wpms:focus:shadow-none!">SendLayer</a>-а и пошаљите <strong>првих 200 е-порука бесплатно</strong> у само неколико притисака!','As a temporary workaround, you can downgrade to PHP 7.3 on your server.'=>'Као привремено заобилазно решење, можете се вратити на PHP 7.3 на свом серверу.','Contact your web hosting provider and inform them you are having issues with the libpcre2 library on PHP 7.4. They should be able to resolve this.'=>'Обратите се свом пружаоцу хостинга и обавестите га да имате проблема са библиотеком libpcre2 на PHP 7.4. Требало би да може да реши проблем.','Your server is running PHP 7.4.x with an outdated libpcre2 library (version 10.32 or earlier) that fails email address validation.'=>'Ваш сервер користи PHP 7.4.x са застарелом библиотеком libpcre2 (издање 10.32 или старије) која не успева да провери е-адресе.','Your SparkPost account region is incorrect.'=>'Регион вашег SparkPost налога није тачан.','Your SparkPost API key is missing the "Transmissions: Read/Write" permission.'=>'Вашем SparkPost API кључу недостаје дозвола „Transmissions: Read/Write“.','Your SparkPost API key is incorrect.'=>'Ваш SparkPost API кључ није тачан.','If you cannot edit php.ini yourself, share the Error Log below with your hosting support and ask them to make this change.'=>'Ако не можете сами да измените php.ini, поделите дневник грешака испод са подршком хостинга и замолите их да направе ову измену.','(Or) Enable allow_url_fopen by adding allow_url_fopen = On to php.ini.'=>'(Или) укључите allow_url_fopen додавањем allow_url_fopen = On у php.ini.','(Recommended) Enable the cURL PHP extension by adding extension=curl to php.ini.'=>'(Препоручено) укључите cURL PHP проширење додавањем extension=curl у php.ini.','The allow_url_fopen PHP setting is disabled on your server.'=>'PHP подешавање allow_url_fopen је искључено на вашем серверу.','Your SMTP.com Sender Name is incorrect.'=>'Ваше SMTP.com име пошиљаоца није тачно.','In Google Cloud Console, re-enable the disabled OAuth client, or create a new OAuth client and update the plugin settings with the new Client ID/Secret.'=>'У Google Cloud Console поново укључите искљученог OAuth клијента или направите новог OAuth клијента и ажурирајте подешавања додатка новим Client ID/Secret.','Make sure your Client ID/Secret corresponds to a project that has the Gmail API enabled.'=>'Уверите се да ваш Client ID/Secret одговара пројекту који има укључен Gmail API.','Your Google OAuth client has been disabled.'=>'Ваш Google OAuth клијент је искључен.','Make sure the Client ID/Secret in your settings corresponds to a project that has the Gmail API enabled.'=>'Уверите се да Client ID/Secret у вашим подешавањима одговара пројекту који има укључен Gmail API.','The Google Cloud project linked to your Client ID/Secret no longer exists.'=>'Google Cloud пројекат повезан са вашим Client ID/Secret више не постоји.','The Gmail API is not enabled on the project.'=>'Gmail API није укључен у пројекту.','Your Google Workspace trial period has expired.'=>'Ваш пробни период за Google Workspace је истекао.','Gmail is not enabled in your Google Workspace account.'=>'Gmail није укључен у вашем Google Workspace налогу.','The Gmail API is not enabled in your Google Cloud project.'=>'Gmail API није укључен у вашем Google Cloud пројекту.','Make sure there is no aggressive caching on admin pages, or clear the cache between attempts.'=>'Уверите се да нема агресивног чувања у остави на администраторским страницама или очистите оставу између покушаја.','Go to the WP Mail SMTP plugin Settings page and click the "Remove OAuth Connection" button.'=>'Идите на страницу подешавања додатка WP Mail SMTP и притисните дугме „Уклони OAuth везу“.','The Google authorization code has already been used.'=>'Google кôд за овлашћење је већ искоришћен.','Do not manually clean up the plugin options to retry the "Allow..." step.'=>'Немојте ручно да чистите могућности додатка да бисте поновили корак „Дозволи...“.','Then click the "Allow plugin to send emails using your Google account" button and re-enable access.'=>'Затим притисните дугме „Дозволи додатку да шаље е-поруке помоћу вашег Google налога“ и поново укључите приступ.','Your Gmail OAuth refresh token has expired.'=>'Ваш Gmail OAuth токен за освежавање је истекао.','Access was revoked from your Google account.'=>'Приступ је опозван са вашег Google налога.','It should look like %1$s. These are invalid: %2$s.'=>'Требало би да изгледа као %1$s. Ово није исправно: %2$s.','If you are generating the email yourself, make sure it includes a TO header.'=>'Ако сами правите е-поруку, уверите се да садржи заглавље TO.','Check the "Send To" email address and confirm it is valid and not empty.'=>'Проверите е-адресу „Пошаљи на“ и потврдите да је исправна и да није празна.','The recipient email address is empty or invalid.'=>'Е-адреса примаоца је празна или није исправна.','On the Google authorization screen, click "Allow" to grant the plugin permission to send emails on your behalf.'=>'На Google екрану за овлашћење притисните „Allow“ да бисте додатку дали дозволу да шаље е-поруке у ваше име.','Click the "Allow plugin to send emails using your Google account" button.'=>'Притисните дугме „Дозволи додатку да шаље е-поруке помоћу вашег Google налога“.','Gmail authorization has not been completed.'=>'Gmail овлашћење није довршено.','Your Mailgun account is still on the free trial plan.'=>'Ваш Mailgun налог је још на бесплатном пробном плану.','Your Mailgun domain has not been verified.'=>'Ваш Mailgun домен није потврђен.','Your Mailgun region is incorrect.'=>'Ваш Mailgun регион није тачан.','Your Mailgun API key is incorrect.'=>'Ваш Mailgun API кључ није тачан.','Your Mailgun domain name is incorrect.'=>'Име вашег Mailgun домена није тачно.','If you do not see the activation email, go to your Mailgun control panel and resend it.'=>'Ако не видите е-поруку за укључивање, идите на своју Mailgun контролну таблу и поново је пошаљите.','Follow our <a href="%s" target="_blank" rel="noopener noreferrer">Gmail tutorial</a> to ensure your project and credentials are configured correctly.'=>'Пратите наше <a href="%s" target="_blank" rel="noopener noreferrer">упутство за Gmail</a> да бисте обезбедили да су ваш пројекат и акредитиви исправно подешени.','Enable the Gmail API in your project from <a href="%s" target="_blank" rel="noopener noreferrer">Google Cloud Console</a>.'=>'Укључите Gmail API у свом пројекту из <a href="%s" target="_blank" rel="noopener noreferrer">Google Cloud Console</a>.','In the Apps list of <a href="%s" target="_blank" rel="noopener noreferrer">Google Workspace Admin</a>, confirm that Gmail is enabled.'=>'На списку апликација у <a href="%s" target="_blank" rel="noopener noreferrer">Google Workspace Admin</a> потврдите да је Gmail укључен.','Verify in <a href="%s" target="_blank" rel="noopener noreferrer">Google Workspace Admin</a> that your trial period has not expired.'=>'Проверите у <a href="%s" target="_blank" rel="noopener noreferrer">Google Workspace Admin</a> да ваш пробни период није истекао.','The cURL PHP extension is disabled on your server.'=>'PHP проширење cURL је искључено на вашем серверу.','Your Mailgun account has not been activated.'=>'Ваш Mailgun налог није укључен.','Contact your hosting support and share the Error Log below along with this <a href="%s" target="_blank" rel="noopener noreferrer">link</a>.'=>'Обратите се подршци хостинга и поделите дневник грешака испод уз ову <a href="%s" target="_blank" rel="noopener noreferrer">везу</a>.','Your web server is blocking the outbound connection.'=>'Ваш веб сервер блокира одлазну везу.','Triple-check your SMTP settings: host, email, password, port, and security.'=>'Трипут проверите своја SMTP подешавања: домаћина, е-адресу, лозинку, порт и безбедност.','Your server\'s OpenSSL CA bundle is outdated.'=>'OpenSSL CA пакет вашег сервера је застарео.','Enable Authentication.'=>'Укључите потврђивање идентитета.','The SMTP host\'s SSL certificate is misconfigured or expired.'=>'SSL сертификат SMTP домаћина није исправно подешен или је истекао.','Your SMTP host requires authentication, but it is disabled in the plugin settings.'=>'Ваш SMTP домаћин захтева потврђивање идентитета, али је оно искључено у подешавањима додатка.','Install an email-logging plugin to inspect your TO, CC, and BCC recipients.'=>'Поставите додатак за бележење е-поште да бисте прегледали примаоце у TO, CC и BCC.','Reduce the recipient count per email: keep single emails to under 10 recipients.'=>'Смањите број прималаца по е-поруци: појединачне е-поруке нека имају мање од 10 прималаца.','You are sending more emails than your SMTP host allows.'=>'Шаљете више е-порука него што ваш SMTP домаћин дозвољава.','Your message was flagged as spam by the SMTP host.'=>'SMTP домаћин је означио вашу поруку као непожељну.','Your SMTP host requires a different authentication method.'=>'Ваш SMTP домаћин захтева други начин потврђивања идентитета.','Your SMTP username or password is incorrect.'=>'Ваше SMTP корисничко име или лозинка нису тачни.','Your server is unable to make outbound HTTP connections.'=>'Ваш сервер не може да успоставља одлазне HTTP везе.','Your hosting provider is blocking the request.'=>'Ваш пружалац хостинга блокира захтев.','Your SendGrid API key is invalid or has been revoked.'=>'Ваш SendGrid API кључ није исправан или је опозван.','If using the "Other SMTP" Mailer, triple-check your SMTP settings (host, email, password) and confirm with your SMTP host that they accept outside connections using those settings.'=>'Ако користите услугу слања „Други SMTP“, трипут проверите своја SMTP подешавања (домаћин, е-адреса, лозинка) и потврдите са SMTP домаћином да прихвата спољне везе са тим подешавањима.','Contact your web hosting provider and ask them to verify your server can make outbound connections, and whether a firewall or security policy may be blocking them.'=>'Обратите се свом пружаоцу хостинга и замолите га да провери да ли ваш сервер може да успоставља одлазне везе и да ли их можда блокира заштитни зид или безбедносна политика.','Your web server is blocking outbound connections.'=>'Ваш веб сервер блокира одлазне везе.','Share the Error Log below with them so they can resolve the issue.'=>'Поделите са њима дневник грешака испод да би могли да реше проблем.','Your server\'s CA certificate bundle is outdated.'=>'Пакет CA сертификата вашег сервера је застарео.','Your server cannot establish secure HTTPS connections.'=>'Ваш сервер не може да успостави безбедне HTTPS везе.','Hide Error Log'=>'Сакриј дневник грешака','View Error Log'=>'Погледај дневник грешака','No structured error code was recorded for this failure. The diagnostic from the mailer is below.'=>'За овај неуспех није забележен структурисани кôд грешке. Дијагностика услуге слања налази се испод.','Send Test Email'=>'Пошаљи пробну е-поруку','Open Troubleshoot Guide'=>'Отвори водич за решавање проблема','We\'ve identified your error as a known issue and have a clear, step-by-step solution ready for you! Just refer our troubleshoot guide to get started.'=>'Препознали смо вашу грешку као познати проблем и имамо спремно јасно решење корак по корак! Само погледајте наш водич за решавање проблема за почетак.','Heads up! The last email your site attempted to send was unsuccessful'=>'Пажња! Последња е-порука коју је ваш сајт покушао да пошаље није успела','Heads up! The last test email your site attempted to send was unsuccessful'=>'Пажња! Последња пробна е-порука коју је ваш сајт покушао да пошаље није успела','Warning'=>'Упозорење','Missing connection identifier.'=>'Недостаје идентификатор везе.','You don\'t have permission to perform this action.'=>'Немате дозволу да извршите ову радњу.','Security check failed. Please reload the page and try again.'=>'Безбедносна провера није успела. Поново учитајте страницу и покушајте поново.','View details'=>'Види детаље','WP Mail SMTP: One or more emails recently failed to send.'=>'WP Mail SMTP: једна или више е-порука недавно није успело да се пошаље.','<p>Hiding email delivery errors means you will no longer be warned when emails fail to send. This is not recommended and should only be used on staging or development sites.</p>'=>'<p>Скривање грешака испоруке е-поште значи да више нећете бити упозоравани када е-поруке не успеју да се пошаљу. Ово се не препоручује и треба га користити само на пробним или развојним сајтовима.</p>','Are you sure?'=>'Да ли сте сигурни?','Setup Now'=>'Подеси сада','Could not dismiss the notice. Please try again.'=>'Није могуће одбацити обавештење. Покушајте поново.','Filter events by severity.'=>'Филтрирај догађаје по озбиљности.','Number of events to skip.'=>'Број догађаја за прескакање.','Maximum number of events to return.'=>'Највећи број догађаја за враћање.','List recorded WP Mail SMTP debug events (errors and debug entries).'=>'Наведи забележене WP Mail SMTP догађаје за отклањање грешака (грешке и уносе за отклањање грешака).','Get Debug Events'=>'Преузми догађаје за отклањање грешака','Number of records to skip.'=>'Број записа за прескакање.','Maximum number of records to return.'=>'Највећи број записа за враћање.','Read-only access to WP Mail SMTP email logs, statistics, and debug events.'=>'Приступ само за читање WP Mail SMTP дневницима е-поште, статистици и догађајима за отклањање грешака.','You do not have permission to access this data.'=>'Немате дозволу за приступ овим подацима.','Something went wrong while connecting to SendLayer. Please try again, or contact support and provide the error code.'=>'Нешто није у реду при повезивању са SendLayer-ом. Покушајте поново или се обратите подршци и наведите кôд грешке.','You can customize your From Email by adding your own domain first on the <a href="%1$s" target="_blank" rel="noopener noreferrer">SendLayer dashboard</a>. Check our <a href="%2$s" target="_blank" rel="noopener noreferrer">documentation</a> on how to add a custom domain.'=>'Е-адресу пошиљаоца можете прилагодити тако што ћете прво додати сопствени домен на <a href="%1$s" target="_blank" rel="noopener noreferrer">SendLayer контролној табли</a>. Погледајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију</a> о томе како да додате произвољни домен.','From Email Address'=>'Е-адреса пошиљаоца','Dismiss'=>'Одбаци','Setup SendLayer'=>'Подеси SendLayer','You\'re using the default WordPress mailer, which often lands in spam! Switch to <a href="%s" target="_blank" rel="noopener noreferrer">SendLayer</a>, our recommended mailer, and send your <strong>first 200 emails for free with just a few clicks!</strong>'=>'Користите подразумевану Вордпресову услугу слања, чије поруке често заврше међу непожељним! Пређите на <a href="%s" target="_blank" rel="noopener noreferrer">SendLayer</a>, нашу препоручену услугу слања, и пошаљите <strong>првих 200 е-порука бесплатно у само неколико притисака!</strong>','Seems like you don\'t have a mailer setup yet!'=>'Изгледа да још немате подешену услугу слања!','SendLayer disconnect failed. The nonce is invalid. Please try again.'=>'SendLayer прекид везе није успео. Nonce није исправан. Покушајте поново.','SendLayer disconnect failed. You do not have permission to perform this action.'=>'SendLayer прекид везе није успео. Немате дозволу да извршите ову радњу.','SendLayer connection failed. Your connection code has expired. Please try again.'=>'SendLayer повезивање није успело. Ваш кôд за повезивање је истекао. Покушајте поново.','SendLayer connection failed. Too many attempts. Please wait a few minutes and try again.'=>'SendLayer повезивање није успело. Превише покушаја. Сачекајте неколико минута и покушајте поново.','SendLayer connection failed. Your session has expired. Please try again.'=>'SendLayer повезивање није успело. Ваша сесија је истекла. Покушајте поново.','SendLayer connection failed. You do not have permission to perform this action.'=>'SendLayer повезивање није успело. Немате дозволу да извршите ову радњу.','SendLayer connected successfully! You can now send emails through SendLayer.'=>'SendLayer је успешно повезан! Сада можете слати е-поруке преко SendLayer-а.','SendLayer disconnected successfully.'=>'Веза са SendLayer-ом је успешно прекинута.','You will need to register your own domain first on the <a href="%1$s" target="_blank" rel="noopener noreferrer">SendLayer dashboard</a> to change it here. Check our <a href="%2$s" target="_blank" rel="noopener noreferrer">documentation</a> on how to add a custom domain.'=>'Прво морате да региструјете сопствени домен на <a href="%1$s" target="_blank" rel="noopener noreferrer">SendLayer контролној табли</a> да бисте ово променили овде. Погледајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију</a> о томе како да додате произвољни домен.','You do not have permission to perform this action.'=>'Немате овлашћење да извршите ову радњу.','This is a shared domain created for you via SendLayer Connect.'=>'Ово је дељени домен направљен за вас преко SendLayer Connect.','Connect manually with API Key'=>'Повежи се ручно помоћу API кључа','Please save this additional connection first to use Quick Connect or enter an API Key manually.'=>'Прво сачувајте ову додатну везу да бисте користили брзо повезивање или ручно унесите API кључ.','<strong><a href="%1$s" target="_blank" rel="noopener noreferrer">SendLayer</a> is our #1 recommended mailer.</strong> It offers affordable pricing and is easy to set up, which makes it an excellent option for WordPress sites. With SendLayer, your domain will be authenticated so all your outgoing emails reach your customers\' inboxes. Our detailed <a href="%2$s" target="_blank" rel="noopener noreferrer">documentation</a> will walk you through the entire process, start to finish. <span class="wp-mail-smtp-text-blue wp-mail-smtp-text-italic">When you sign up for a free trial, you can send your first emails at no charge.</span>'=>'<strong><a href="%1$s" target="_blank" rel="noopener noreferrer">SendLayer</a> је наша препоручена услуга слања бр. 1.</strong> Нуди приступачне цене и лако се подешава, што је чини одличним избором за Вордпресове сајтове. Уз SendLayer ваш домен ће бити потврђен, тако да све ваше одлазне е-поруке стижу у сандучиће ваших купаца. Наша детаљна <a href="%2$s" target="_blank" rel="noopener noreferrer">документација</a> провешће вас кроз цео поступак, од почетка до краја. <span class="wp-mail-smtp-text-blue wp-mail-smtp-text-italic">Када се пријавите за бесплатну пробу, прве е-поруке можете послати бесплатно.</span>','Connecting...'=>'Повезивање...','Easily start sending emails from your site in just a few clicks and enjoy your %1$sfirst 200 emails absolutely free!%2$s'=>'Лако почните да шаљете е-поруке са свог сајта у само неколико притисака и уживајте у %1$sпрвих 200 е-порука потпуно бесплатно!%2$s','Takes about 2 mins'=>'Траје око 2 минута','Read how to setup manually'=>'Прочитајте како да подесите ручно','Quick Connect'=>'Брзо повезивање','Change'=>'Промени','Connected to'=>'Повезано са','Domain'=>'Домен','If enabled, your specified From Email Address will be used for all outgoing emails, regardless of values set by other plugins.'=>'Ако је укључено, наведена е-адреса пошиљаоца користиће се за све одлазне е-поруке, без обзира на вредности које постављају други додаци.','Copy error code'=>'Умножи кôд грешке','Retry Connecting'=>'Покушај поново да се повежеш','This is a shared domain created for you via SendLayer Connect. You will need to register your own domain first on the %1$sSendLayer dashboard%2$s to change it here. Check our %3$sdocumentation%4$s on how to add a custom domain.'=>'Ово је дељени домен направљен за вас преко SendLayer Connect. Прво морате да региструјете сопствени домен на %1$sSendLayer контролној табли%2$s да бисте ово променили овде. Погледајте нашу %3$sдокументацију%4$s о томе како да додате произвољни домен.','The email address that emails are sent from. You can customize your From Email by adding your domain on %1$sSendLayer dashboard%2$s. Check our %3$sdocumentation%4$s on how to add a custom domain.'=>'Е-адреса са које се шаљу е-поруке. Е-адресу пошиљаоца можете прилагодити додавањем свог домена на %1$sSendLayer контролној табли%2$s. Погледајте нашу %3$sдокументацију%4$s о томе како да додате произвољни домен.','Your site was not connected to SendLayer. You can retry or connect manually with API key. Our detailed documentation for manually connecting will walk you through the entire process.'=>'Ваш сајт није повезан са SendLayer-ом. Можете покушати поново или се повезати ручно помоћу API кључа. Наша детаљна документација за ручно повезивање провешће вас кроз цео поступак.','SendLayer Connection Failed!'=>'Повезивање са SendLayer-ом није успело!','Your site was successfully connected to SendLayer. This site will now send emails via your SendLayer account.'=>'Ваш сајт је успешно повезан са SendLayer-ом. Овај сајт ће сада слати е-поруке преко вашег SendLayer налога.','A server error occurred. Please try again.'=>'Дошло је до грешке сервера. Покушајте поново.','An error occurred. Please try again.'=>'Дошло је до грешке. Покушајте поново.','Disconnect'=>'Прекини','API Keys'=>'API кључеви','Follow this link to get the API key from Resend: %s.'=>'Пратите ову везу да бисте добили API кључ од Resend-а: %s.','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Resend documentation</a>.'=>'Да бисте почели, прочитајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију за Resend</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Resend</a> is a modern email delivery platform that enables developers to send transactional and marketing emails quickly and reliably. If you\'re just getting started, you can send up to 3000 emails per month without a credit card.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Resend</a> је савремена платформа за испоруку е-поште која градитељима омогућава брзо и поуздано слање трансакционих и маркетиншких е-порука. Ако тек почињете, можете слати до 3.000 е-порука месечно без кредитне картице.','Read how to set up Resend'=>'Прочитајте како да подесите Resend','%1$sFollow this link%2$s to get an API Key for Resend.'=>'%1$sПратите ову везу%2$s да бисте добили API кључ за Resend.','Send WordPress emails reliably via SMTP or API using SendLayer, Brevo, SMTP.com, Gmail, Outlook, or another email service of your choice.'=>'Поуздано шаљите Вордпресове е-поруке преко SMTP-а или API-ја помоћу SendLayer, Brevo, SMTP.com, Gmail, Outlook или друге услуге е-поште по вашем избору.','Follow this link to get an API Key from Mandrill: %s.'=>'Пратите ову везу да бисте добили API кључ од Mandrill-а: %s.','Mandrill'=>'Mandrill','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Mandrill documentation</a>.'=>'Да бисте почели, прочитајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију за Mandrill</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Mandrill</a> is a transactional email API for MailChimp users. It is a reliable, scalable, and secure delivery API for transactional emails. Mandrill requires a paid monthly subscription to send emails.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Mandrill</a> је API за трансакциону е-пошту за кориснике MailChimp-а. То је поуздан, скалабилан и безбедан API за испоруку трансакционих е-порука. Mandrill захтева плаћену месечну претплату за слање е-порука.','The email failed to be sent. Reason: %s'=>'Слање е-поруке није успело. Разлог: %s','Discount'=>'Попуст','Professional Setup and World-Class Support'=>'Професионално подешавање и врхунска подршка','White Glove Setup - Sit back while we handle everything'=>'White Glove подешавање – опустите се док ми бринемо о свему','Smart Routing, Multisite Support, and Manage Notifications'=>'Паметно усмеравање, подршка за мрежу сајтова и управљање обавештењима','Effortless Management - Control your email experience'=>'Управљање без напора – управљајте својим искуством е-поште','Gmail one-click setup, Microsoft 365 / Outlook, Amazon SES, and Zoho Mail'=>'Подешавање Gmail-а једним притиском, Microsoft 365 / Outlook, Amazon SES и Zoho Mail','Professional Email Services - Access enterprise-grade email providers'=>'Професионалне услуге е-поште – приступите пружаоцима е-поште на нивоу предузећа','Email Logging, Alerts, and Backup Connection'=>'Бележење е-поште, упозорења и резервна веза','Peace of Mind - Never wonder about your email status'=>'Мир – никада се не питајте какво је стање ваше е-поште','Key Features You’ll Unlock:'=>'Кључне могућности које ћете откључати:','Level Up Your Email Game - Get Pro Features Now'=>'Подигните своју е-пошту на виши ниво – набавите Pro могућности сада','As a valued WP Mail SMTP Lite user, you can enjoy an exclusive <strong>%s discount</strong>, automatically applied at checkout to unlock even more features!'=>'Као цењени корисник WP Mail SMTP Lite можете уживати у ексклузивном <strong>попусту од %s</strong>, аутоматски примењеном при плаћању, да бисте откључали још више могућности!','Email Logs'=>'Дневници е-поште','You’re using WP Mail SMTP Lite. To unlock more features, consider <a href="%1$s" target="_blank" rel="noopener noreferrer">upgrading to Pro</a> for <strong>%2$s OFF</strong>.'=>'Користите WP Mail SMTP Lite. Да бисте откључали више могућности, размислите о <a href="%1$s" target="_blank" rel="noopener noreferrer">надоградњи на Pro</a> уз <strong>%2$s ПОПУСТА</strong>.','Read how to set up Mandrill'=>'Прочитајте како да подесите Mandrill','Follow this link to get an API Key from Mandrill.'=>'Пратите ову везу да бисте добили API кључ од Mandrill-а.','<strong>%s OFF</strong> for WP Mail SMTP users, applied at checkout.'=>'<strong>%s ПОПУСТА</strong> за кориснике WP Mail SMTP, примењено при плаћању.','Upgrade and join over <strong>4,000,000</strong> websites!'=>'Надоградите и придружите се више од <strong>4.000.000</strong> веб сајтова!','You\'re using <strong>WP Mail SMTP Lite</strong> - no license needed. Enjoy!'=>'Користите <strong>WP Mail SMTP Lite</strong> – лиценца није потребна. Уживајте!','pricing page'=>'страницу са ценама','Activate if you have a Professional or higher plan with MailerSend. This allows you to use custom headers. For more information about MailerSend plans, check their %s.'=>'Укључите ако имате Professional или виши план код MailerSend-а. Ово вам омогућава да користите произвољна заглавља. За више података о MailerSend плановима погледајте њихову %s.','Professional Plan'=>'Professional план','Follow this link to get an API Key from MailerSend: %s.'=>'Пратите ову везу да бисте добили API кључ од MailerSend-а: %s.','MailerSend'=>'MailerSend','<a href="%1$s" target="_blank" rel="noopener noreferrer">MailerSend</a> is a reliable transactional email provider with powerful features. They offer 12,000 emails per month for free and have affordable plans for higher volumes. Their modern API and excellent deliverability make them a great choice for WordPress sites.<br><br>To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">MailerSend documentation</a>.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">MailerSend</a> је поуздан пружалац трансакционе е-поште са моћним могућностима. Нуди 12.000 е-порука месечно бесплатно и има приступачне планове за веће обиме. Савремени API и одлична испоручивост чине га одличним избором за Вордпресове сајтове.<br><br>Да бисте почели, прочитајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију за MailerSend</a>.','Phone Number ID'=>'ID броја телефона','WhatsApp Business Account ID'=>'ID WhatsApp Business налога','Access Token'=>'Приступни токен','WhatsApp Alerts'=>'WhatsApp упозорења','Enter your WhatsApp Cloud API credentials to receive alerts when email sending fails. You\'ll need to create a Meta developer account and set up WhatsApp Business Platform.'=>'Унесите своје WhatsApp Cloud API акредитиве да бисте добијали упозорења када слање е-поште не успе. Мораћете да направите Meta налог за градитеље и подесите WhatsApp Business Platform.','WhatsApp'=>'WhatsApp','Read how to set up MailerSend'=>'Прочитајте како да подесите MailerSend','Enable if you have a Pro plan or higher to use advanced features like custom headers.'=>'Укључите ако имате Pro или виши план да бисте користили напредне могућности као што су произвољна заглавља.','Pro Plan Features'=>'Могућности Pro плана','Connection Name'=>'Име везе','Push Notification Alerts'=>'Упозорења push обавештењима','Notice was successfully dismissed.'=>'Обавештење је успешно одбачено.','To receive push notifications on this device, you\'ll need to allow our plugin to send notifications via this browser. Read our documentation on setting up Push Notification alerts.'=>'Да бисте добијали push обавештења на овом уређају, морате дозволити нашем додатку да шаље обавештења преко овог прегледача. Прочитајте нашу документацију о подешавању упозорења push обавештењима.','Push Notifications'=>'Push обавештења','Follow this link to get an API Key from Elastic Email: %s.'=>'Пратите ову везу да бисте добили API кључ од Elastic Email-а: %s.','Elastic Email'=>'Elastic Email','%1$s <a href="%2$s" target="_blank" rel="noopener noreferrer">Upgrade to Pro now for easy, one-click Outlook setup</a>.'=>'%1$s <a href="%2$s" target="_blank" rel="noopener noreferrer">Надоградите на Pro сада за лако подешавање Outlook-а једним притиском</a>.','<strong>%1$s</strong><br>Heads up! Microsoft is <a href="%2$s" target="_blank" rel="noopener noreferrer">discontinuing support for basic SMTP connections</a>. To continue using Outlook or Hotmail, switch to our Outlook mailer for uninterrupted email sending.'=>'<strong>%1$s</strong><br>Пажња! Microsoft <a href="%2$s" target="_blank" rel="noopener noreferrer">укида подршку за основне SMTP везе</a>. Да бисте наставили да користите Outlook или Hotmail, пређите на нашу Outlook услугу слања ради непрекидног слања е-поште.','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Elastic Email documentation</a>.'=>'Да бисте почели, прочитајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију за Elastic Email</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Elastic Email</a> is a cloud-based email marketing platform offering tools for email campaigns, automation, transactional emails, and analytics, designed for businesses of all sizes.<br><br>If you\'re just starting out, you can use Elastic Email\'s free plan to send emails to your account address from one of your verified email addresses. You don\'t need to use a credit card to try it out. When you\'re ready, you can upgrade to a higher plan.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Elastic Email</a> је платформа за маркетинг е-поштом у облаку која нуди алате за кампање е-поштом, аутоматизацију, трансакционе е-поруке и аналитику, осмишљена за предузећа свих величина.<br><br>Ако тек почињете, можете користити бесплатни план Elastic Email-а за слање е-порука на адресу свог налога са неке од својих потврђених е-адреса. Не морате да користите кредитну картицу да бисте га испробали. Када будете спремни, можете надоградити на виши план.','One-Click Setup for Microsoft Outlook requires an active license. Verify your license to proceed with this One-Click Setup, please.'=>'Подешавање Microsoft Outlook-а једним притиском захтева активну лиценцу. Потврдите лиценцу да бисте наставили са овим подешавањем једним притиском.','Sign in with Outlook'=>'Пријави се помоћу Outlook-а','Provides a quick and easy way to connect to Outlook that doesn\'t require creating your own app.'=>'Пружа брз и лак начин повезивања са Outlook-ом који не захтева прављење сопствене апликације.','You have successfully connected your site with your Outlook account. Now you can start sending emails through Outlook.'=>'Успешно сте повезали свој сајт са Outlook налогом. Сада можете почети да шаљете е-поруке преко Outlook-а.','%1$sFollow this link%2$s to get an API Key for Elastic Email.'=>'%1$sПратите ову везу%2$s да бисте добили API кључ за Elastic Email.','Read how to set up Elastic Email'=>'Прочитајте како да подесите Elastic Email','Remove Server API Token'=>'Уклони API токен сервера','Follow this link to get the Secret key from Mailjet: %s.'=>'Пратите ову везу да бисте добили тајни кључ од Mailjet-а: %s.','Remove Secret Key'=>'Уклони тајни кључ','API Key Management'=>'Управљање API кључевима','Follow this link to get the API key from Mailjet: %s.'=>'Пратите ову везу да бисте добили API кључ од Mailjet-а: %s.','Mailjet'=>'Mailjet','Remove API Key'=>'Уклони API кључ','Remove Client Secret'=>'Уклони тајну клијента','Discord Alerts'=>'Discord упозорења','Paste in the Discord webhook URL you’d like to use to receive alerts when email sending fails. Read our documentation on setting up Discord alerts.'=>'Убаците URL Discord куке који желите да користите за добијање упозорења када слање е-поште не успе. Прочитајте нашу документацију о подешавању Discord упозорења.','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Mailjet documentation</a>.'=>'Да бисте почели, прочитајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију за Mailjet</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Mailjet</a> is a cloud-based email service platform that enables businesses to send marketing and transactional emails, offering features like email automation, real-time analytics, and responsive design templates. If you\'re just starting out, you can send up to 200 emails per day without a credit card.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Mailjet</a> је платформа за услуге е-поште у облаку која предузећима омогућава слање маркетиншких и трансакционих е-порука, нудећи могућности као што су аутоматизација е-поште, аналитика у стварном времену и прилагодљиви шаблони дизајна. Ако тек почињете, можете слати до 200 е-порука дневно без кредитне картице.','Follow this link to get the Secret key from Mailjet: %1$sAPI Key Management%2$s.'=>'Пратите ову везу да бисте добили тајни кључ од Mailjet-а: %1$sУправљање API кључевима%2$s.','Discord'=>'Discord','Follow this link to get the API key from Mailjet: %1$sAPI Key Management%2$s.'=>'Пратите ову везу да бисте добили API кључ од Mailjet-а: %1$sУправљање API кључевима%2$s.','Read how to set up Mailjet'=>'Прочитајте како да подесите Mailjet','Secret Key'=>'Тајни кључ','control panel'=>'контролној табли','Generate an API key on the Sending &rarr; API Keys page in your %s.'=>'Направите API кључ на страници Sending &rarr; API Keys на својој %s.','SMTP2GO'=>'SMTP2GO','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">SMTP2GO documentation</a>.'=>'Да бисте почели, прочитајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију за SMTP2GO</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">SMTP2GO</a> provides a robust and reliable email delivery service with global infrastructure, real-time analytics, and advanced security features. If you\'re just starting out, you can use SMTP2GO\'s free plan to send up to 1000 emails per month.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">SMTP2GO</a> пружа снажну и поуздану услугу испоруке е-поште са глобалном инфраструктуром, аналитиком у стварном времену и напредним безбедносним могућностима. Ако тек почињете, можете користити бесплатни план SMTP2GO за слање до 1.000 е-порука месечно.','Remove Password'=>'Уклони лозинку','Microsoft Teams Alerts'=>'Microsoft Teams упозорења','Paste in the Microsoft Teams webhook URL you’d like to use to receive alerts when email sending fails. Read our documentation on setting up Microsoft Teams alerts.'=>'Убаците URL Microsoft Teams куке који желите да користите за добијање упозорења када слање е-поште не успе. Прочитајте нашу документацију о подешавању Microsoft Teams упозорења.','Remove'=>'Уклони','Microsoft Teams'=>'Microsoft Teams','Read how to set up SMTP2GO'=>'Прочитајте како да подесите SMTP2GO','Generate an API key on the Sending → API Keys page in your %1$scontrol panel%2$s.'=>'Направите API кључ на страници Sending → API Keys на својој %1$sконтролној табли%2$s.','[Emails Queue] Skipped processing enqueued email. %1$s. Email ID: %2$d'=>'[Ред е-порука] Прескочена обрада е-поруке у реду. %1$s. ID е-поруке: %2$d','[Emails Queue] Failed to update queue record after sending email from the queue. %1$s. Email ID: %2$d'=>'[Ред е-порука] Ажурирање записа у реду после слања е-поруке из реда није успело. %1$s. ID е-поруке: %2$d','[Emails Queue] Skipped email sending from the queue. Wrong email status. Email ID: %1$d, email status: %2$s.'=>'[Ред е-порука] Прескочено слање е-поруке из реда. Погрешно стање е-поруке. ID е-поруке: %1$d, стање е-поруке: %2$s.','[Emails Queue] Skipped email sending from the queue. %1$s. Email ID:  %2$s'=>'[Ред е-порука] Прескочено слање е-поруке из реда. %1$s. ID е-поруке:  %2$s','[Emails Queue] Skipped enqueueing email. %1$s.'=>'[Ред е-порука] Прескочено стављање е-поруке у ред. %1$s.','Insert/update SQL query error: %1$s'=>'Грешка SQL упита за убацивање/ажурирање: %1$s','[Emails Queue] Skipped email sending from the queue. Queue::send_email method was called directly. Email ID: %1$d.'=>'[Ред е-порука] Прескочено слање е-поруке из реда. Метода Queue::send_email позвана је директно. ID е-поруке: %1$d.','Data JSON encoding error: %1$s'=>'Грешка JSON кодирања података: %1$s','Data JSON decoding error: %1$s'=>'Грешка JSON декодирања података: %1$s','Invalid record format'=>'Неисправан облик записа','Record not found in DB'=>'Запис није пронађен у бази података','Yes, I\'ll rate it with 5-stars'=>'Да, оцените га са 5 звездица','That\'s fantastic! Would you consider giving it a 5-star rating on WordPress.org? It will help other users with email issues and it will mean the world to us!'=>'То је фантастично! Да ли бисте размислили да му дате оцену од 5 звездица на WordPress.org? То ће помоћи другим корисницима са проблемима са е-поштом и много ће нам значити!','Provide Feedback'=>'Пошаљи утиске','Limit the number of emails this site will send in each time interval (per minute, hour, day, week and month). Emails that will cross those set limits will be queued and sent as soon as your limits allow. <a href="%1$s" target="_blank" rel="noopener noreferrer">Learn More</a>'=>'Ограничите број е-порука које ће овај сајт слати у сваком временском интервалу (у минуту, сату, дану, недељи и месецу). Е-поруке које пређу постављена ограничења биће стављене у ред и послате чим ограничења дозволе. <a href="%1$s" target="_blank" rel="noopener noreferrer">Сазнајте више</a>','No'=>'Не','Email Rate Limiting'=>'Ограничавање учесталости слања е-поште','Send emails asynchronously, which will make pages with email requests load faster, but may delay email delivery by a minute or two. <a href="%1$s" target="_blank" rel="noopener noreferrer">Learn More</a>'=>'Шаљите е-поруке асинхроно, што ће убрзати учитавање страница са захтевима за е-пошту, али може одложити испоруку е-поруке за минут или два. <a href="%1$s" target="_blank" rel="noopener noreferrer">Сазнајте више</a>','Optimize Email Sending'=>'Оптимизуј слање е-поште','WP Mail SMTP is using custom database tables for some of its features. In order to work properly, the custom tables should be created, and it seems they are missing. Please try to <a href="%1$s">create the missing DB tables by clicking on this link</a>. If this issue persists, please <a href="%2$s" target="_blank" rel="noopener noreferrer">contact our support</a>.'=>'WP Mail SMTP користи произвољне табеле базе података за неке своје могућности. Да би исправно радио, произвољне табеле морају бити направљене, а изгледа да недостају. Покушајте да <a href="%1$s">направите недостајуће табеле базе података притиском на ову везу</a>. Ако се овај проблем настави, <a href="%2$s" target="_blank" rel="noopener noreferrer">обратите се нашој подршци</a>.','WP Mail SMTP is using custom database tables for some of its features. In order to work properly, the custom tables should be created, and it seems they are missing. Please try to <a href="%1$s">create the missing DB tables by clicking on this link</a>. If this issue persists, please <a href="%2$s" target="_blank" rel="noopener noreferrer">contact our support</a> and provide the error message below:'=>'WP Mail SMTP користи произвољне табеле базе података за неке своје могућности. Да би исправно радио, произвољне табеле морају бити направљене, а изгледа да недостају. Покушајте да <a href="%1$s">направите недостајуће табеле базе података притиском на ову везу</a>. Ако се овај проблем настави, <a href="%2$s" target="_blank" rel="noopener noreferrer">обратите се нашој подршци</a> и наведите поруку о грешци испод:','We\'re sorry, Email Rate Limiting is not available on your plan. Please upgrade to the Pro plan to unlock all these awesome features.'=>'Нажалост, ограничавање учесталости слања е-поште није доступно у вашем плану. Надоградите на Pro план да бисте откључали све ове сјајне могућности.','Email Rate Limiting <br> is a Pro Feature'=>'Ограничавање учесталости слања е-поште <br> је Pro могућност','Install the WPForms plugin and create beautiful contact forms with just a few clicks.'=>'Поставите додатак WPForms и направите лепе обрасце за контакт у само неколико притисака.','Our Gmail mailer works with any Gmail or Google Workspace account via the Google API. You can send WordPress emails from your main email address or a Gmail alias, and it\'s more secure than connecting to Gmail using SMTP credentials. We now have a One-Click Setup, which simply asks you to authorize your Google account to use our app and takes care of everything for you. Alternatively, you can connect manually, which involves several steps that are more technical than other mailer options, so we created a detailed guide to walk you through the process.<br><br>To get started, read our <a href="%s" target="_blank" rel="noopener noreferrer">Gmail documentation</a>.'=>'Наша Gmail услуга слања ради са било којим Gmail или Google Workspace налогом преко Google API-ја. Вордпресове е-поруке можете слати са своје главне е-адресе или Gmail алијаса, а то је безбедније од повезивања са Gmail-ом помоћу SMTP акредитива. Сада имамо подешавање једним притиском, које од вас само тражи да овластите свој Google налог да користи нашу апликацију и брине о свему уместо вас. Или се можете повезати ручно, што обухвата неколико корака који су технички захтевнији од других услуга слања, па смо направили детаљан водич који вас води кроз поступак.<br><br>Да бисте почели, прочитајте нашу <a href="%s" target="_blank" rel="noopener noreferrer">документацију за Gmail</a>.','We\'re sorry, One-Click Setup for Google Mailer is not available on your plan. Please upgrade to the Pro plan to unlock all these awesome features.'=>'Нажалост, подешавање једним притиском за Google услугу слања није доступно у вашем плану. Надоградите на Pro план да бисте откључали све ове сјајне могућности.','The email address that emails are sent from. The email address that emails are sent from. You can use only the connected email address or its alias.'=>'Е-адреса са које се шаљу е-поруке. Е-адреса са које се шаљу е-поруке. Можете користити само повезану е-адресу или њен алијас.','The email address that emails are sent from. You can use only the connected email address or its alias.'=>'Е-адреса са које се шаљу е-поруке. Можете користити само повезану е-адресу или њен алијас.','The email address that emails are sent from. You can use only connected email address or his alias.'=>'Е-адреса са које се шаљу е-поруке. Можете користити само повезану е-адресу или њен алијас.','The email address that emails are sent from. You can use only connected email address or '=>'Е-адреса са које се шаљу е-поруке. Можете користити само повезану е-адресу или ','You have successfully connected your site with your Gmail account. Now you can start sending emails through Gmail.'=>'Успешно сте повезали свој сајт са Gmail налогом. Сада можете почети да шаљете е-поруке преко Gmail-а.','You have successfully connected your site with your Gmail account. This site will now send emails via your Gmail account.'=>'Успешно сте повезали свој сајт са Gmail налогом. Овај сајт ће сада слати е-поруке преко вашег Gmail налога.','One-Click Setup for Google Mailer requires an active license. Verify your license to proceed with this One-Click Setup, please.'=>'Подешавање једним притиском за Google услугу слања захтева активну лиценцу. Потврдите лиценцу да бисте наставили са овим подешавањем једним притиском.','One-Click Setup for Google Mailer requires an active license. Verify your license to proceed with this one-click setup, please.'=>'Подешавање једним притиском за Google услугу слања захтева активну лиценцу. Потврдите лиценцу да бисте наставили са овим подешавањем једним притиском.','Gmail mailer requires a valid Easy WP SMTP Pro license. Please activate your license key.'=>'Gmail услуга слања захтева исправну Easy WP SMTP Pro лиценцу. Укључите свој лиценцни кључ.','One-Click Setup for Google Mailer requires an active license. Verify your license to proceed with this one-click setup.'=>'Подешавање једним притиском за Google услугу слања захтева активну лиценцу. Потврдите лиценцу да бисте наставили са овим подешавањем једним притиском.','One-Click Setup for Google Mailer requires an active license. Emails are currently not being sent.'=>'Подешавање једним притиском за Google услугу слања захтева активну лиценцу. Е-поруке се тренутно не шаљу.','Now you can continue mailer configuration.'=>'Сада можете наставити са подешавањем услуге слања.','Sign in with Google'=>'Пријави се помоћу Google-а','There was an error while processing the authentication request.'=>'Дошло је до грешке при обради захтева за потврђивање идентитета.','Disabled'=>'Онемогућено','Enabled'=>'Омогућено','Provides a quick and easy way to connect to Google that doesn\'t require creating your own app.'=>'Пружа брз и лак начин повезивања са Google-ом који не захтева прављење сопствене апликације.','One-Click Setup'=>'Подешавање једним притиском','One-Click Setup for Google Mailer <br> is a Pro Feature'=>'Подешавање једним притиском за Google услугу слања <br> је Pro могућност','Send emails from different additional connections based on your configured conditions. Emails that do not match any of the conditions below will be sent via your Primary Connection.'=>'Шаљите е-поруке преко различитих додатних веза на основу подешених услова. Е-поруке које не одговарају ниједном од услова испод биће послате преко главне везе.','All settings will be unrecoverable.'=>'Сва подешавања неће моћи да се поврате.','Remove ALL WP Mail SMTP data upon plugin deletion.'=>'Уклони СВЕ WP Mail SMTP податке при брисању додатка.','Miscellaneous'=>'Разно','Email logging makes it easy to save details about all of the emails sent from your WordPress site. You can search and filter the email log to find specific messages and check the color-coded delivery status. Email logging also allows you to resend emails, save attachments, and export your logs in different formats.'=>'Бележење е-поште олакшава чување детаља о свим е-порукама послатим са вашег Вордпресовог сајта. Дневник е-поште можете претраживати и филтрирати да бисте пронашли одређене поруке и проверили стање испоруке означено бојама. Бележење е-поште вам омогућава и да поново шаљете е-поруке, чувате прилоге и извозите дневнике у различитим облицима.','Easily export your logs to CSV or Excel. Filter the logs before you export and only download the data you need. This feature lets you easily create your own deliverability reports. You can also use the data in 3rd party dashboards to track deliverability along with your other website statistics.'=>'Лако извезите дневнике у CSV или Excel. Филтрирајте дневнике пре извоза и преузмите само податке који су вам потребни. Ова могућност вам омогућава да лако направите сопствене извештаје о испоручивости. Податке можете користити и на контролним таблама трећих страна за праћење испоручивости заједно са другом статистиком вашег веб сајта.','Email reports make it easy to track deliverability and engagement at-a-glance. Your open and click-through rates are grouped by subject line, making it easy to review the performance of campaigns or notifications. The report also displays Sent and Failed emails each week so you spot any issues quickly. When you upgrade, we\'ll also add an email report chart right in your WordPress dashboard.'=>'Извештаји о е-пошти олакшавају праћење испоручивости и ангажовања на први поглед. Ваше стопе отварања и притисака на везе груписане су по наслову, што олакшава преглед учинка кампања или обавештења. Извештај приказује и послате и неуспеле е-поруке сваке недеље да бисте брзо уочили проблеме. Када надоградите, додаћемо и графикон извештаја о е-пошти директно на вашу Вордпресову контролну таблу.','Get notified about emails that were successfully sent, but have hard bounced on delivery attempt. A hard bounce is an email that has failed to deliver for permanent reasons, such as the recipient\'s email address being invalid.'=>'Добијајте обавештења о е-порукама које су успешно послате, али су трајно одбијене при покушају испоруке. Трајно одбијање је е-порука која није испоручена из трајних разлога, као што је неисправна е-адреса примаоца.','Email controls allow you to manage the automatic notifications you receive from your WordPress website. With the flick of a switch, you can reduce inbox clutter and focus on the alerts that matter the most. It\'s easy to disable emails about comments, email or password changes, WordPress updates, user registrations, and personal data requests.'=>'Контроле е-поште вам омогућавају да управљате аутоматским обавештењима која добијате са свог Вордпресовог веб сајта. Једним прекидачем можете смањити претрпаност сандучета и усредсредити се на упозорења која су најважнија. Лако је искључити е-поруке о коментарима, променама е-адресе или лозинке, ажурирањима Вордпреса, регистрацијама корисника и захтевима за личне податке.','The deliverability verification process detects a hard bounce'=>'Поступак провере испоручивости открије трајно одбијање','This option is always enabled and will notify you about instant email sending failures.'=>'Ова могућност је увек укључена и обавестиће вас о тренутним неуспесима слања е-поште.','The initial email sending request fails'=>'Почетни захтев за слање е-поруке не успе','Notify when'=>'Обавести када','Configure at least one of these integrations to receive notifications when email fails to send from your site. Alert notifications will contain the following important data: email subject, email Send To address, the error message, and helpful links to help you fix the issue.'=>'Подесите бар једну од ових уградњи да бисте добијали обавештења када е-порука не успе да се пошаље са вашег сајта. Обавештења о упозорењу садржаће следеће важне податке: наслов е-поруке, адресу примаоца, поруку о грешци и корисне везе за решавање проблема.','Create additional connections to set a backup for your Primary Connection or to configure Smart Routing.'=>'Направите додатне везе да бисте поставили резервну за главну везу или подесили паметно усмеравање.','Free Plugins'=>'Бесплатни додаци','Made with ♥ by the WP Mail SMTP team'=>'Направљено са ♥ од стране WP Mail SMTP тима','Support'=>'Подршка','Improve your SEO rankings with the All in One SEO plugin.'=>'Побољшајте своју позицију у претрази помоћу додатка All in One SEO.','The following DB table is still missing.'=>'Следећа табела базе података и даље недостаје.' . "\0" . 'Следеће табеле базе података и даље недостају.' . "\0" . 'Следеће табеле базе података и даље недостају.','Code Snippets by WPCode'=>'Исечци кода помоћу WPCode-а','Follow this link to <a href="%s" target="_blank" rel="noopener noreferrer">get a Mailgun API Key</a>. Generate a key in the "Mailgun API Keys" section.'=>'Пратите ову везу да бисте <a href="%s" target="_blank" rel="noopener noreferrer">добили Mailgun API кључ</a>. Направите кључ у одељку „Mailgun API Keys“.','Dismiss email alert block'=>'Одбаци блок упозорења е-поштом','We detected %d failed email in the last 30 days.'=>'Открили смо %d неуспелу е-поруку у последњих 30 дана.' . "\0" . 'Открили смо %d неуспеле е-поруке у последњих 30 дана.' . "\0" . 'Открили смо %d неуспелих е-порука у последњих 30 дана.','Error icon'=>'Иконица грешке','%1$sFollow this link%2$s to get a Mailgun API Key. Generate a key in the "Mailgun API Keys" section.'=>'%1$sПратите ову везу%2$s да бисте добили Mailgun API кључ. Направите кључ у одељку „Mailgun API Keys“.','Mailgun API Key'=>'Mailgun API кључ','The following plugin will be installed for free:'=>'Следећи додатак биће бесплатно постављен:','WordPress SEO Toolkit'=>'SEO скуп алата за Вордпрес','Improve your website\'s SEO ranking with our toolkit.'=>'Побољшајте позицију свог веб сајта у претрази помоћу нашег скупа алата.','<a href="%s" target="_blank" rel="noopener noreferrer">Upgrade to Pro</a> and get instant alert notifications when they fail.'=>'<a href="%s" target="_blank" rel="noopener noreferrer">Надоградите на Pro</a> и добијајте тренутна обавештења о упозорењу када не успеју.','The Email Test tab was moved to <a href="%s">WP Mail SMTP > Tools</a>.'=>'Језичак „Проба е-поште“ премештен је у <a href="%s">WP Mail SMTP > Алати</a>.','We Detected %d Failed Email in the Last 30 Days'=>'Открили смо %d неуспешну е-поруку у последњих 30 дана' . "\0" . 'Открили смо %d неуспешне е-поруке у последњих 30 дана' . "\0" . 'Открили смо %d неуспешних е-порука у последњих 30 дана','Brevo'=>'Brevo','We believe in full transparency. The Brevo (formerly Sendinblue) links above are tracking links as part of our partnership with Brevo. We can recommend just about any SMTP service, but we only recommend products that we believe will add value to our users.'=>'Верујемо у потпуну транспарентност. Brevo (раније Sendinblue) везе изнад су везе за праћење као део нашег партнерства са Brevo-ом. Можемо да препоручимо скоро сваку SMTP услугу, али препоручујемо само производе за које верујемо да ће донети вредност нашим корисницима.','Get Brevo Now (Free)'=>'Набави Brevo сада (бесплатно)','We believe in full transparency. The Brevo links above are tracking links as part of our partnership with Brevo. We can recommend just about any SMTP service, but we only recommend products that we believe will add value to our users.'=>'Верујемо у потпуну транспарентност. Brevo везе изнад су везе за праћење као део нашег партнерства са Brevo-ом. Можемо да препоручимо скоро сваку SMTP услугу, али препоручујемо само производе за које верујемо да ће донети вредност нашим корисницима.','Get Started with Brevo'=>'Почните са Brevo-ом','Read how to set up Brevo'=>'Прочитајте како да подесите Brevo','Please input the sending domain/subdomain you configured in your Brevo dashboard. More information can be found in our %1$sBrevo documentation%2$s'=>'Унесите домен/поддомен за слање који сте подесили на Brevo контролној табли. Више података можете пронаћи у нашој %1$sдокументацији за Brevo%2$s','Leading WordPress backup & site migration plugin. Over 1,500,000+ smart website owners use Duplicator to make reliable and secure WordPress backups to protect their websites. It also makes website migration really easy.'=>'Водећи Вордпресов додатак за резервне копије и пренос сајта. Више од 1.500.000 паметних власника веб сајтова користи Duplicator за поуздане и безбедне резервне копије Вордпреса ради заштите својих веб сајтова. Такође веома олакшава пренос веб сајта.','Duplicator'=>'Duplicator','Future proof your WordPress customizations with the most popular code snippet management plugin for WordPress. Trusted by over 1,500,000+ websites for easily adding code to WordPress right from the admin area.'=>'Заштитите своја Вордпресова прилагођавања за будућност уз најпопуларнији додатак за управљање исечцима кода за Вордпрес. Верује му више од 1.500.000 веб сајтова за лако додавање кода у Вордпрес директно из администрације.','WPCode Lite'=>'WPCode Lite','Top-rated WordPress donation and fundraising plugin. Over 10,000+ non-profit organizations and website owners use Charitable to create fundraising campaigns and raise more money online.'=>'Најбоље оцењени Вордпресов додатак за донације и прикупљање средстава. Више од 10.000 непрофитних организација и власника веб сајтова користи Charitable за прављење кампања и прикупљање више новца на мрежи.','WP Core (%s)'=>'WP основа (%s)','Primary'=>'Главни','Friendly reminder, your Primary Connection will be used for all emails that do not match the conditions above.'=>'Подсетник: ваша главна веза користиће се за све е-поруке које не одговарају условима изнад.','Light bulb icon'=>'Иконица сијалице','Initiator'=>'Покретач','Contact Emails (SMTP.com)'=>'Е-поруке за контакт (SMTP.com)','Add New Group'=>'Додај нову групу','or'=>'или','And'=>'И','Is'=>'Јесте','Arrow Down'=>'Стрелица надоле','Contains'=>'Садржи','Arrow Up'=>'Стрелица нагоре','if the following conditions are met...'=>'ако су испуњени следећи услови...','WooCommerce Emails (SendLayer)'=>'WooCommerce е-поруке (SendLayer)','Send with'=>'Пошаљи помоћу','Enable Smart Routing'=>'Укључи паметно усмеравање','Order'=>'Редослед','Primary Connection'=>'Главна веза','Create advanced routing rules'=>'Правите напредна правила усмеравања','Use mailers for different purposes'=>'Користите услуге слања за различите намене','With additional connections you can...'=>'Уз додатне везе можете...','Set a Backup Connection'=>'Поставите резервну везу','Smart Routing'=>'Паметно усмеравање','Backup Connection'=>'Резервна веза','Additional Connections'=>'Додатне везе','There was an error while processing the authentication request. The state key is invalid. Please try again.'=>'Дошло је до грешке при обради захтева за потврђивање идентитета. Кључ стања није исправан. Покушајте поново.','Don’t worry about losing emails. Add an additional connection, then set it as your Backup Connection. Emails that fail to send with the Primary Connection will be sent via the selected Backup Connection. <a href="%s" target="_blank" rel="noopener noreferrer">Upgrade to WP Mail SMTP Pro!</a>'=>'Не брините о губитку е-порука. Додајте додатну везу, а затим је поставите као резервну везу. Е-поруке које не успеју да се пошаљу преко главне везе биће послате преко изабране резервне везе. <a href="%s" target="_blank" rel="noopener noreferrer">Надоградите на WP Mail SMTP Pro!</a>','Remove OAuth Connection'=>'Уклони OAuth везу','It looks like we can\'t remove OAuth connection.'=>'Изгледа да не можемо да уклонимо OAuth везу.','Once you add an <a href="%s">additional connection</a>, you can select it here.'=>'Када додате <a href="%s">додатну везу</a>, можете је изабрати овде.','Go to WP Mail SMTP settings page.'=>'Иди на страницу WP Mail SMTP подешавања.','create the missing DB tables by clicking on this link'=>'направите недостајуће табеле базе података притиском на ову везу','WP Mail SMTP is using custom database tables for some of its features. In order to work properly, the custom tables should be created, and it seems they are missing. Please try to <a href="%1$s" target="_self" aria-label="%2$s" rel="noopener noreferrer">%3$s</a>. If this issue persists, please contact our support.'=>'WP Mail SMTP користи произвољне табеле базе података за неке своје могућности. Да би исправно радио, произвољне табеле морају бити направљене, а изгледа да недостају. Покушајте да <a href="%1$s" target="_self" aria-label="%2$s" rel="noopener noreferrer">%3$s</a>. Ако се овај проблем настави, обратите се нашој подршци.','Some DB Tables are still missing.'=>'Неке табеле базе података и даље недостају.','Missing DB tables were created successfully.'=>'Недостајуће табеле базе података успешно су направљене.','Unknown.'=>'Непознато.','%d Day'=>'%d дан' . "\0" . '%d дана' . "\0" . '%d дана','1 Year'=>'1 година','3 Months'=>'3 месеца','6 Months'=>'6 месеци','1 Month'=>'1 месец','1 Week'=>'1 недеља','Debug events older than the selected period will be permanently deleted from the database.'=>'Догађаји за отклањање грешака старији од изабраног периода биће трајно избрисани из базе података.','Forever'=>'Заувек','Events Retention Period'=>'Период чувања догађаја','[%1$d] %2$s called at [%3$s:%4$s]'=>'[%1$d] %2$s позвано у [%3$s:%4$s]','Backtrace:'=>'Траг позива:','Track when a link in an email is clicked'=>'Прати када се притисне веза у е-поруци','Complete Email Reports'=>'Потпуни извештаји о е-пошти','See the delivery status, track opens and clicks, and create deliverability graphs.'=>'Погледајте стање испоруке, пратите отварања и притиске и правите графиконе испоручивости.','Instant Email Alerts'=>'Тренутна упозорења е-поштом','Get notifications via email, SMS, Slack, or webhook when emails fail to send.'=>'Добијајте обавештења е-поштом, SMS-ом, преко Slack-а или куке када е-поруке не успеју да се пошаљу.','Enable these powerful logging features for more control of your WordPress emails.'=>'Укључите ове моћне могућности бележења за већу контролу над Вордпресовим е-порукама.','This option must be enabled if you\'d like to be able to resend emails. Please be aware that all email content will be stored in your WordPress database. This may include sensitive data, passwords, and personal details.'=>'Ова могућност мора бити укључена ако желите да можете поново да шаљете е-поруке. Имајте на уму да ће сав садржај е-порука бити сачуван у вашој Вордпресовој бази података. То може обухватати осетљиве податке, лозинке и личне детаље.','See which emails were opened by the recipients. Email open tracking works with emails that are sent in HTML format.'=>'Погледајте које е-поруке су примаоци отворили. Праћење отварања е-порука ради са е-порукама послатим у HTML облику.','See which links were clicked in emails sent from your WordPress site. Click tracking works with emails that are sent in HTML format.'=>'Погледајте које везе су притиснуте у е-порукама послатим са вашег Вордпресовог сајта. Праћење притисака ради са е-порукама послатим у HTML облику.','Track when an email is opened'=>'Прати када се е-порука отвори','All file attachments sent from your site will be saved to the WordPress Uploads folder. Please note that this may reduce available disk space on your server.'=>'Сви прилози послати са вашег сајта биће сачувани у Вордпресовој фасцикли отпремања. Имајте на уму да то може смањити доступан простор на диску вашег сервера.','Save file attachments sent from WordPress'=>'Чувај прилоге послате из Вордпреса','Store the content for all sent emails'=>'Чувај садржај свих послатих е-порука','<strong>Table:</strong> %1$s. <strong>Reason:</strong> %2$s'=>'<strong>Табела:</strong> %1$s. <strong>Разлог:</strong> %2$s','%1$sFollow this link%2$s to get a Private API Key from Mailgun.'=>'%1$sПратите ову везу%2$s да бисте добили приватни API кључ од Mailgun-а.','Configure Email Logs'=>'Подеси дневнике е-поште','Let’s see how many emails you’ve sent with WP Mail SMTP.'=>'Погледајмо колико сте е-порука послали помоћу WP Mail SMTP.','Current function path: %s'=>'Тренутна путања функције: %s','It looks like it\'s overwritten in the "wp-config.php" file. Please reach out to your hosting provider on how to disable or remove the "wp_mail" function overwrite to prevent conflicts with WP Mail SMTP.'=>'Изгледа да је замењена у датотеци „wp-config.php“. Обратите се свом пружаоцу хостинга за упутства о томе како да искључите или уклоните замену функције „wp_mail“ да бисте спречили сукобе са WP Mail SMTP.','It looks like the "%s" must-use plugin is overwriting the "wp_mail" function. Please reach out to your hosting provider on how to disable or remove the "wp_mail" function overwrite to prevent conflicts with WP Mail SMTP.'=>'Изгледа да must-use додатак „%s“ замењује функцију „wp_mail“. Обратите се свом пружаоцу хостинга за упутства о томе како да искључите или уклоните замену функције „wp_mail“ да бисте спречили сукобе са WP Mail SMTP.','It looks like the "%s" plugin is overwriting the "wp_mail" function. Please reach out to the plugin developer on how to disable or remove the "wp_mail" function overwrite to prevent conflicts with WP Mail SMTP.'=>'Изгледа да додатак „%s“ замењује функцију „wp_mail“. Обратите се градитељу додатка за упутства о томе како да искључите или уклоните замену функције „wp_mail“ да бисте спречили сукобе са WP Mail SMTP.','WP Mail SMTP has detected incorrect "wp_mail" function location. Usually, this means that emails will not be sent successfully!'=>'WP Mail SMTP је открио нетачну локацију функције „wp_mail“. Обично то значи да е-поруке неће бити успешно послате!','Or deactivate "SMTP" module in Branda > Emails > SMTP.'=>'Или искључите модул „SMTP“ у Branda > Emails > SMTP.','Webhook Alerts'=>'Упозорења преко кука','Paste in the webhook URL you’d like to use to receive alerts when email sending fails. Read our documentation on setting up webhook alerts.'=>'Убаците URL куке који желите да користите за добијање упозорења када слање е-поште не успе. Прочитајте нашу документацију о подешавању упозорења преко кука.','To Phone Number'=>'Број телефона примаоца','From Phone Number'=>'Број телефона пошиљаоца','Twilio Auth Token'=>'Twilio токен за потврђивање идентитета','Twilio Account ID'=>'Twilio ID налога','SMS via Twilio Alerts'=>'SMS упозорења преко Twilio-а','To receive SMS alerts, you’ll need a Twilio account. Read our documentation to learn how to set up Twilio SMS, then enter your connection details below.'=>'Да бисте добијали SMS упозорења, потребан вам је Twilio налог. Прочитајте нашу документацију да бисте сазнали како да подесите Twilio SMS, а затим унесите податке о вези испод.','SMS via Twilio'=>'SMS преко Twilio-а','Webhook URL'=>'URL куке','Slack Alerts'=>'Slack упозорења','Paste in the Slack webhook URL you’d like to use to receive alerts when email sending fails. Read our documentation on setting up Slack alerts.'=>'Убаците URL Slack куке који желите да користите за добијање упозорења када слање е-поште не успе. Прочитајте нашу документацију о подешавању Slack упозорења.','Slack'=>'Slack','Email Alerts'=>'Упозорења е-поштом','Enter the email addresses (3 max) you’d like to use to receive alerts when email sending fails. Read our documentation on setting up email alerts.'=>'Унесите е-адресе (највише 3) које желите да користите за добијање упозорења када слање е-поште не успе. Прочитајте нашу документацију о подешавању упозорења е-поштом.','Webhook'=>'Веб кука','Alerts'=>'Упозорења','There was an error while processing the authentication request. The authorization code is missing. Please try again.'=>'Дошло је до грешке при обради захтева за потврђивање идентитета. Недостаје кôд за овлашћење. Покушајте поново.','There was an error while processing the authentication request. The nonce is invalid. Please try again.'=>'Дошло је до грешке при обради захтева за потврђивање идентитета. Nonce није исправан. Покушајте поново.','Follow this link to get an API Key from SendLayer: %s.'=>'Пратите ову везу да бисте добили API кључ од SendLayer-а: %s.','SendLayer'=>'SendLayer','Verify your domain Region is correct.'=>'Проверите да ли је регион вашег домена тачан.','Docs'=>'Документи','Go to WPMailSMTP.com documentation page'=>'Иди на страницу документације WPMailSMTP.com','Get WP Mail SMTP Pro'=>'Набави WP Mail SMTP Pro','Get Started with SendLayer'=>'Почните са SendLayer-ом','Read how to set up SendLayer'=>'Прочитајте како да подесите SendLayer','%1$sFollow this link%2$s to get an API Key for SendLayer.'=>'%1$sПратите ову везу%2$s да бисте добили API кључ за SendLayer.','Read how to set up SendGrid'=>'Прочитајте како да подесите SendGrid','%1$sFollow this link%2$s to get an API Key for MailerSend.'=>'%1$sПратите ову везу%2$s да бисте добили API кључ за MailerSend.','Verify your <a href="%1$s" target="_blank" rel="noopener noreferrer">Domain Name</a> is correct.'=>'Проверите да ли је ваше <a href="%1$s" target="_blank" rel="noopener noreferrer">име домена</a> тачно.','Go to your Mailgun account and verify that your <a href="%1$s" target="_blank" rel="noopener noreferrer">Mailgun API Key</a> is correct.'=>'Идите на свој Mailgun налог и проверите да ли је ваш <a href="%1$s" target="_blank" rel="noopener noreferrer">Mailgun API кључ</a> тачан.','If you create a test email on this page, it will still be sent.'=>'Ако направите пробну е-поруку на овој страници, она ће ипак бити послата.','Could not install the plugin. You don\'t have permission to activate plugins.'=>'Није могуће поставити додатак. Немате дозволу да укључујете додатке.','Or enable "Do not change email sender by default" setting in Settings > Email template > Sender (tab).'=>'Или укључите подешавање „Do not change email sender by default“ у Settings > Email template > Sender (језичак).','On this page, you can view different plugin debugging events and email sending errors.'=>'На овој страници можете прегледати разне догађаје за отклањање грешака додатка и грешке слања е-поште.','A simple & powerful event calendar plugin for WordPress that comes with all the event management features including payments, scheduling, timezones, ticketing, recurring events, and more.'=>'Једноставан и моћан додатак за календар догађаја за Вордпрес са свим могућностима управљања догађајима, укључујући плаћања, заказивање, временске зоне, продају улазница, понављајуће догађаје и друго.','The best WordPress eCommerce plugin for selling digital downloads. Start selling eBooks, software, music, digital art, and more within minutes. Accept payments, manage subscriptions, advanced access control, and more.'=>'Најбољи Вордпресов додатак за е-трговину за продају дигиталних преузимања. Почните да продајете е-књиге, софтвер, музику, дигиталну уметност и друго за неколико минута. Примајте плаћања, управљајте претплатама, напредна контрола приступа и друго.','<strong>WP Mail SMTP plugin is disabled</strong> on your site until WordPress is updated to the required version.'=>'<strong>Додатак WP Mail SMTP је искључен</strong> на вашем сајту док се Вордпрес не ажурира на потребно издање.','Your site is running an <strong>old version</strong> of WordPress that is no longer supported by WP Mail SMTP. Please update your WordPress site to at least version <strong>%s</strong>.'=>'Ваш сајт користи <strong>старо издање</strong> Вордпреса које WP Mail SMTP више не подржава. Ажурирајте свој Вордпресов сајт бар на издање <strong>%s</strong>.','Visit <a href="%s" target="_blank" rel="noopener noreferrer">our documentation</a> for additional tips on how to resolve this error.'=>'Посетите <a href="%s" target="_blank" rel="noopener noreferrer">нашу документацију</a> за додатне савете о томе како да решите ову грешку.','The #1 Stripe payments plugin for WordPress. Start accepting one-time and recurring payments on your WordPress site without setting up a shopping cart. No code required.'=>'Додатак бр. 1 за Stripe плаћања за Вордпрес. Почните да примате једнократна и понављајућа плаћања на свом Вордпресовом сајту без подешавања корпе. Није потребан кôд.','The #1 affiliate management plugin for WordPress. Easily create an affiliate program for your eCommerce store or membership site within minutes and start growing your sales with the power of referral marketing.'=>'Додатак бр. 1 за управљање партнерским програмима за Вордпрес. Лако направите партнерски програм за своју продавницу или сајт за чланство за неколико минута и почните да повећавате продају снагом маркетинга препорука.','The most advanced WordPress search plugin. Customize your WordPress search algorithm, reorder search results, track search metrics, and everything you need to leverage search to grow your business.'=>'Најнапреднији Вордпресов додатак за претрагу. Прилагодите алгоритам претраге у Вордпресу, преуредите резултате претраге, пратите мере претраге и све што вам треба да искористите претрагу за раст посла.','Visit Site'=>'Посети сајт','Select your SparkPost account region.'=>'Изаберите регион свог SparkPost налога.','Follow this link to get an API Key from SparkPost: %s.'=>'Пратите ову везу да бисте добили API кључ од SparkPost-а: %s.','SparkPost'=>'SparkPost','<a href="%s" rel="" target="_blank">More information</a> on SparkPost.'=>'<a href="%s" rel="" target="_blank">Више података</a> о SparkPost-у.','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">SparkPost documentation</a>.'=>'Да бисте почели, прочитајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију за SparkPost</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">SparkPost</a> is a transactional email provider that\'s trusted by big brands and small businesses. It sends more than 4 trillion emails each year and reports 99.9%% uptime. You can get started with the free test account that lets you send up to 500 emails per month.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">SparkPost</a> је пружалац трансакционе е-поште коме верују велики брендови и мала предузећа. Шаље више од 4 билиона е-порука годишње и пријављује 99,9%% доступности. Можете почети са бесплатним пробним налогом који вам омогућава слање до 500 е-порука месечно.','365 / Outlook'=>'365 / Outlook','API Key:'=>'API кључ:','Region:'=>'Регион:','Google / Gmail'=>'Google / Gmail','Verify that your SparkPost account region is selected in WP Mail SMTP settings.'=>'Проверите да ли је регион вашег SparkPost налога изабран у WP Mail SMTP подешавањима.','Verify that your API key has "Transmissions: Read/Write" permission.'=>'Проверите да ли ваш API кључ има дозволу „Transmissions: Read/Write“.','SparkPost API failed.'=>'SparkPost API није успео.','Go to your <a href="%1$s" target="_blank" rel="noopener noreferrer">SparkPost account</a> or <a href="%2$s" target="_blank" rel="noopener noreferrer">SparkPost EU account</a> and verify that your API key is correct.'=>'Идите на свој <a href="%1$s" target="_blank" rel="noopener noreferrer">SparkPost налог</a> или <a href="%2$s" target="_blank" rel="noopener noreferrer">SparkPost EU налог</a> и проверите да ли је ваш API кључ тачан.','Your mailer is already configured in a WP Mail SMTP constant, so the options below have been disabled. To change your mailer, please edit or remove the <code>WPMS_MAILER</code> constant in your <code>wp-config.php</code> file.'=>'Ваша услуга слања је већ подешена у WP Mail SMTP константи, па су могућности испод искључене. Да бисте променили услугу слања, уредите или уклоните константу <code>WPMS_MAILER</code> у датотеци <code>wp-config.php</code>.','This setting is already configured with the WP Mail SMTP constant. To change it, please edit or remove the <code></code> constant in your <code>wp-config.php</code> file.'=>'Ово подешавање је већ подешено WP Mail SMTP константом. Да бисте га променили, уредите или уклоните константу <code></code> у датотеци <code>wp-config.php</code>.','FluentSMTP'=>'FluentSMTP','Microsoft 365 / Outlook'=>'Microsoft 365 / Outlook','Select your SparkPost account region. %1$sMore information%2$s on SparkPost.'=>'Изаберите регион свог SparkPost налога. %1$sВише података%2$s о SparkPost-у.','%1$sFollow this link%2$s to get an API Key for SparkPost.'=>'%1$sПратите ову везу%2$s да бисте добили API кључ за SparkPost.','Read how to set up SparkPost'=>'Прочитајте како да подесите SparkPost','To get started, read our <a href="%s" target="_blank" rel="noopener noreferrer">SMTP.com documentation</a>.'=>'Да бисте почели, прочитајте нашу <a href="%s" target="_blank" rel="noopener noreferrer">документацију за SMTP.com</a>.','<strong><a href="%s" target="_blank" rel="noopener noreferrer">SMTP.com</a> is one of our recommended mailers.</strong> It\'s a transactional email provider that\'s currently used by 100,000+ businesses. SMTP.com is an established brand that\'s been offering email services for more than 20 years.<br><br>SMTP.com offers a free 30-day trial that allows you to send up to 50,000 emails.'=>'<strong><a href="%s" target="_blank" rel="noopener noreferrer">SMTP.com</a> је једна од наших препоручених услуга слања.</strong> То је пружалац трансакционе е-поште који тренутно користи више од 100.000 предузећа. SMTP.com је етаблиран бренд који нуди услуге е-поште више од 20 година.<br><br>SMTP.com нуди бесплатну пробу од 30 дана која вам омогућава слање до 50.000 е-порука.','The Other SMTP option lets you send emails through an SMTP server instead of using a provider\'s API. This is easy and convenient, but it\'s less secure than the other mailers. Please note that your provider may not allow you to send a large number of emails. In that case, please use a different mailer.<br><br>To get started, read our <a href="%s" target="_blank" rel="noopener noreferrer">Other SMTP documentation</a>.'=>'Могућност „Други SMTP“ вам омогућава да шаљете е-поруке преко SMTP сервера уместо преко API-ја пружаоца услуге. Ово је лако и згодно, али је мање безбедно од других услуга слања. Имајте на уму да вам пружалац можда неће дозволити слање великог броја е-порука. У том случају користите другу услугу слања.<br><br>Да бисте почели, прочитајте нашу <a href="%s" target="_blank" rel="noopener noreferrer">документацију за Други SMTP</a>.','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Brevo documentation</a>.'=>'Да бисте почели, прочитајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију за Brevo</a>.','<strong><a href="%1$s" target="_blank" rel="noopener noreferrer">Brevo</a> (formerly Sendinblue) is one of our recommended mailers.</strong> It\'s a transactional email provider with scalable price plans, so it\'s suitable for any size of business.<br><br>If you\'re just starting out, you can use Brevo\'s free plan to send up to 300 emails a day. You don\'t need to use a credit card to try it out. When you\'re ready, you can upgrade to a higher plan to increase your sending limits.'=>'<strong><a href="%1$s" target="_blank" rel="noopener noreferrer">Brevo</a> (раније Sendinblue) је једна од наших препоручених услуга слања.</strong> То је пружалац трансакционе е-поште са скалабилним плановима цена, па је погодан за предузећа било које величине.<br><br>Ако тек почињете, можете користити бесплатни Brevo план за слање до 300 е-порука дневно. Не морате да користите кредитну картицу да бисте га испробали. Када будете спремни, можете надоградити на виши план да бисте повећали ограничења слања.','<a href="%1$s" target="_blank" rel="noopener noreferrer">SendGrid</a> is a popular transactional email provider that sends more than 35 billion emails every month. If you\'re just starting out, the free plan allows you to send up to 100 emails each day without entering your credit card details.<br><br>To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">SendGrid documentation</a>.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">SendGrid</a> је популаран пружалац трансакционе е-поште који шаље више од 35 милијарди е-порука месечно. Ако тек почињете, бесплатни план вам омогућава слање до 100 е-порука дневно без уноса података о кредитној картици.<br><br>Да бисте почели, прочитајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију за SendGrid</a>.','Get Server API Token'=>'Набави API токен сервера','Follow this link to get a Server API Token from Postmark: %s.'=>'Пратите ову везу да бисте добили API токен сервера од Postmark-а: %s.','Postmark'=>'Postmark','To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Postmark documentation</a>.'=>'Да бисте почели, прочитајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију за Postmark</a>.','Message Stream ID is <strong>optional</strong>. By default <strong>outbound</strong> (Default Transactional Stream) will be used. More information can be found in our <a href="%s" target="_blank" rel="noopener noreferrer">Postmark documentation</a>.'=>'Message Stream ID је <strong>необавезан</strong>. Подразумевано ће се користити <strong>outbound</strong> (подразумевани трансакциони ток). Више података можете пронаћи у нашој <a href="%s" target="_blank" rel="noopener noreferrer">документацији за Postmark</a>.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Postmark</a> is a transactional email provider that offers great deliverability and accessible pricing for any business. You can start out with the free trial that allows you to send 100 test emails each month via its secure API.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Postmark</a> је пружалац трансакционе е-поште који нуди одличну испоручивост и приступачне цене за свако предузеће. Можете почети са бесплатном пробом која вам омогућава слање 100 пробних е-порука месечно преко безбедног API-ја.','Message Stream ID:'=>'Message Stream ID:','Server API Token:'=>'API токен сервера:','<a href="%1$s" target="_blank" rel="noopener noreferrer">Mailgun</a> is a transactional email provider that offers a generous 3-month free trial. After that, it offers a \'Pay As You Grow\' plan that allows you to pay for what you use without committing to a fixed monthly rate.<br><br>To get started, read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Mailgun documentation</a>.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Mailgun</a> је пружалац трансакционе е-поште који нуди великодушну бесплатну пробу од 3 месеца. После тога нуди план „Pay As You Grow“ који вам омогућава да плаћате оно што користите без обавезе на фиксну месечну цену.<br><br>Да бисте почели, прочитајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију за Mailgun</a>.','Hide the WP Mail SMTP Dashboard Widget.'=>'Сакриј WP Mail SMTP виџет контролне табле.','Hide warnings alerting of email delivery errors.'=>'Сакриј упозорења о грешкама испоруке е-поште.','Hide plugin announcements and update details.'=>'Сакриј објаве додатка и детаље ажурирања.','Stop sending all emails'=>'Заустави слање свих е-порука','Export logs to CSV, XLSX, or EML'=>'Извезите дневнике у CSV, XLSX или EML','User activated their new site, or site was added from Network Admin -> Sites -> Add New. Sent to Site Admin.'=>'Корисник је укључио свој нови сајт или је сајт додат из Администрација мреже -> Сајтови -> Додај нови. Шаље се администратору сајта.','Site Admin: Activated / Added Site'=>'Администратор сајта: укључен / додат сајт','User activated their new site, or site was added from Network Admin -> Sites -> Add New. Sent to Network Admin.'=>'Корисник је укључио свој нови сајт или је сајт додат из Администрација мреже -> Сајтови -> Додај нови. Шаље се администратору мреже.','Network Admin: User Activated / Added Site'=>'Администратор мреже: корисник је укључио / додао сајт','User registered for a new site. Sent to the site admin.'=>'Регистрација корисника за нови сајт. Шаље се администратору сајта.','User Created Site'=>'Корисник је направио сајт','New Site'=>'Нови сајт','A user has been added, or their account activation has been successful. Sent to the user, that has been added/activated.'=>'Корисник је додат или је његов налог успешно укључен. Шаље се кориснику који је додат/укључен.','Added / Activated on Site'=>'Додат / укључен на сајту','A new user account was created. Sent to Network Admin.'=>'Направљен је нови кориснички налог. Шаље се администратору мреже.','Created On Site'=>'Направљен на сајту','A new user was invited to a site from Users -> Add New -> Add New User. Sent to the invited user.'=>'Нови корисник је позван на сајт из Корисници -> Додај новог -> Додај новог корисника. Шаље се позваном кориснику.','Invited To Site'=>'Позван на сајт','A new user was created. Sent to the new user.'=>'Направљен је нови корисник. Шаље се новом кориснику.','Created (User)'=>'Направљен (корисник)','A new user was created. Sent to the site admin.'=>'Направљен је нови корисник. Шаље се администратору сајта.','Created (Admin)'=>'Направљен (администратор)','New User'=>'Нови корисник','Full log of background update results which includes information about WordPress core, plugins, themes, and translations updates. Only sent when you are using a development version of WordPress. Sent to the site or network admin.'=>'Потпун дневник резултата ажурирања у позадини, који садржи податке о ажурирањима основе Вордпреса, додатака, тема и превода. Шаље се само када користите развојно издање Вордпреса. Шаље се администратору сајта или мреже.','Full Log'=>'Потпун дневник','Completion or failure of a background automatic core update. Sent to the site or network admin.'=>'Завршетак или неуспех аутоматског ажурирања основе у позадини. Шаље се администратору сајта или мреже.','Completion or failure of a background automatic theme update. Sent to the site or network admin.'=>'Завршетак или неуспех аутоматског ажурирања теме у позадини. Шаље се администратору сајта или мреже.','WP Core Status'=>'Стање WP основе','Theme Status'=>'Стање теме','Completion or failure of a background automatic plugin update. Sent to the site or network admin.'=>'Завршетак или неуспех аутоматског ажурирања додатка у позадини. Шаље се администратору сајта или мреже.','Plugin Status'=>'Стање додатка','Automatic Updates'=>'Аутоматска ажурирања','Disabling this option will block users from being able to export their personal data, as they will not receive an email with a link.'=>'Искључивање ове могућности спречиће кориснике да извезу своје личне податке, јер неће добити е-поруку са везом.','Site admin clicked "Email Data" button next to a confirmed data export request. Sent to the requester email address.'=>'Администратор сајта је притиснуо дугме „Пошаљи податке е-поштом“ поред потврђеног захтева за извоз података. Шаље се на е-адресу подносиоца захтева.','Admin Sent Link to Export Data'=>'Администратор је послао везу за извоз података','Site admin clicked "Erase Personal Data" button next to a confirmed data erasure request. Sent to the requester email address.'=>'Администратор сајта је притиснуо дугме „Избриши личне податке“ поред потврђеног захтева за брисање података. Шаље се на е-адресу подносиоца захтева.','Admin Erased Data'=>'Администратор је избрисао податке','User clicked a confirmation link in personal data export or erasure request email. Sent to the site or network admin.'=>'Корисник је притиснуо везу за потврду у е-поруци захтева за извоз или брисање личних података. Шаље се администратору сајта или мреже.','User Confirmed Export / Erasure Request'=>'Корисник је потврдио захтев за извоз / брисање','Personal Data Requests'=>'Захтеви за личне податке','User changed their email address. Sent to the user.'=>'Корисник је променио своју е-адресу. Шаље се кориснику.','Email Changed'=>'Е-адреса је промењена','User attempted to change their email address. Sent to the proposed new email address.'=>'Корисник је покушао да промени своју е-адресу. Шаље се на предложену нову е-адресу.','Email Change Attempt'=>'Покушај промене е-адресе','User changed their password. Sent to the user.'=>'Корисник је променио своју лозинку. Шаље се кориснику.','Password Changed'=>'Лозинка је промењена','User reset their password from the password reset link. Sent to the site admin.'=>'Корисник је променио своју лозинку преко везе за промену лозинке. Шаље се администратору сајта.','Password Reset Successfully'=>'Лозинка је успешно промењена','Reset Password Request'=>'Захтев за промену лозинке','User requested a password reset via "Lost your password?". Sent to the user.'=>'Корисник је затражио промену лозинке преко „Изгубили сте лозинку?“. Шаље се кориснику.','Change of User Email or Password'=>'Промена е-адресе или лозинке корисника','Network admin email address was changed. Sent to the old network admin email address.'=>'Е-адреса администратора мреже је промењена. Шаље се на стару е-адресу администратора мреже.','Change of network admin email address was attempted. Sent to the proposed new email address.'=>'Покушана је промена е-адресе администратора мреже. Шаље се на предложену нову е-адресу.','Network Admin Email Changed'=>'Е-адреса администратора мреже је промењена','Network Admin Email Change Attempt'=>'Покушај промене е-адресе администратора мреже','Site admin email address was changed. Sent to the old site admin email address.'=>'Е-адреса администратора сајта је промењена. Шаље се на стару е-адресу администратора сајта.','Site Admin Email Changed'=>'Е-адреса администратора сајта је промењена','Change of site admin email address was attempted. Sent to the proposed new email address.'=>'Покушана је промена е-адресе администратора сајта. Шаље се на предложену нову е-адресу.','Site Admin Email Change Attempt'=>'Покушај промене е-адресе администратора сајта','Change of Admin Email'=>'Промена е-адресе администратора','Published'=>'Објављено','Comment has been published. Sent to the post author.'=>'Коментар је објављен. Шаље се аутору чланка.','Comment is awaiting moderation. Sent to the site admin and post author if they can edit comments.'=>'Коментар чека модерацију. Шаље се администратору сајта и аутору чланка ако може да уређује коментаре.','Awaiting Moderation'=>'Чека модерацију','Outlook / 365 requires an SSL certificate, and so is not currently compatible with your site. Please contact your host to request a SSL certificate, or check out '=>'Outlook / 365 захтева SSL сертификат, па тренутно није усаглашен са вашим сајтом. Обратите се свом хостингу да затражите SSL сертификат или погледајте ','Comments'=>'Коментари','If you\'d prefer not to set up SSL, or need an SMTP solution in the meantime, please go back and select a different mailer option.'=>'Ако не желите да подесите SSL или вам у међувремену треба SMTP решење, вратите се и изаберите другу услугу слања.','WPBeginner\'s tutorial on how to set up SSL'=>'WPBeginner-ово упутство о томе како да подесите SSL','Amazon SES requires an SSL certificate, and so is not currently compatible with your site. Please contact your host to request a SSL certificate, or check out '=>'Amazon SES захтева SSL сертификат, па тренутно није усаглашен са вашим сајтом. Обратите се свом хостингу да затражите SSL сертификат или погледајте ','Read how to set up Postmark'=>'Прочитајте како да подесите Postmark','%1$sFollow this link%2$s to get a Server API Token for Postmark.'=>'%1$sПратите ову везу%2$s да бисте добили API токен сервера за Postmark.','Message Stream ID'=>'Message Stream ID','Server API Token'=>'API токен сервера','Message Stream ID is <strong>optional</strong>. By default <strong>outbound</strong> (Default Transactional Stream) will be used. More information can be found in our %1$sPostmark documentation%2$s.'=>'Message Stream ID је <strong>необавезан</strong>. Подразумевано ће се користити <strong>outbound</strong> (подразумевани трансакциони ток). Више података можете пронаћи у нашој %1$sдокументацији за Postmark%2$s.','WP Core'=>'WP основа','Want More Stats?'=>'Желите више статистике?','Last week'=>'Прошла недеља','Total Emails'=>'Укупно е-порука','Reports'=>'Извештаји','Hi there,'=>'Здраво,','WP Mail SMTP Logo'=>'WP Mail SMTP логотип','WP Mail SMTP Weekly Email Summary'=>'WP Mail SMTP недељни сажетак е-поште','Your Weekly WP Mail SMTP Summary for %s'=>'Ваш недељни WP Mail SMTP сажетак за %s','Upgrade to <b>WP Mail SMTP Pro</b> and unlock <u>Email Log</u> and advanced <u>Email Reports</u>. Start measuring the success of your emails today!'=>'Надоградите на <b>WP Mail SMTP Pro</b> и откључајте <u>дневник е-поште</u> и напредне <u>извештаје о е-пошти</u>. Почните да мерите успех својих е-порука већ данас!','You currently have the <strong>Default (none)</strong> mailer selected, which won\'t improve email deliverability. Please select <a href="%1$s" target="_blank" rel="noopener noreferrer">any other email provider</a> and use the easy <a href="%2$s">Setup Wizard</a> to configure it.'=>'Тренутно имате изабрану услугу слања <strong>Подразумевано (ништа)</strong>, која неће побољшати испоручивост е-поште. Изаберите <a href="%1$s" target="_blank" rel="noopener noreferrer">било ког другог пружаоца е-поште</a> и користите једноставан <a href="%2$s">чаробњак за подешавање</a> да бисте га подесили.','An email request was sent to the Gmail API.'=>'Захтев за е-поруку послат је Gmail API-ју.','An error occurred when trying to get Gmail aliases: %s'=>'Дошло је до грешке при покушају добијања Gmail алијаса: %s','There was an error while processing Google authorization: missing code or scope parameter.'=>'Дошло је до грешке при обради Google овлашћења: недостаје параметар code или scope.','There was an error while upgrading the %1$s database. Please contact %2$s support with this information: %3$s.'=>'Дошло је до грешке при надоградњи базе података %1$s. Обратите се подршци за %2$s са овим подацима: %3$s.','There was an error while processing Google authorization: %s'=>'Дошло је до грешке при обради Google овлашћења: %s','An email request was sent.'=>'Захтев за е-поруку је послат.','Send Another Test Email'=>'Пошаљи још једну пробну е-поруку','View Email Summary Example'=>'Погледај пример сажетка е-поште','Disable Email Summaries weekly delivery.'=>'Искључи недељно слање сажетака е-поште.','Disable Email Summaries'=>'Искључи сажетке е-поште','Print email logs or save as PDF'=>'Штампајте дневнике е-поште или их сачувајте као PDF','Track email opens and clicks'=>'Пратите отварања и притиске е-порука','Resend emails and attachments'=>'Поново шаљите е-поруке и прилоге','See sent and failed emails'=>'Погледајте послате и неуспеле е-поруке','Save detailed email headers'=>'Сачувајте детаљна заглавља е-порука','Unlock these awesome logging features:'=>'Откључајте ове сјајне могућности бележења:','Individual Email Log'=>'Појединачни дневник е-поште','Email Log Index'=>'Попис дневника е-поште','See email report graphs in WordPress'=>'Погледајте графиконе извештаја о е-пошти у Вордпресу','Spot failed emails quickly'=>'Брзо уочите неуспеле е-поруке','Measure open rate and click through rates'=>'Мерите стопу отварања и стопу притисака','Track total emails sent each week'=>'Пратите укупан број послатих е-порука сваке недеље','View stats grouped by subject line'=>'Погледајте статистику груписану по наслову','Get weekly deliverability reports'=>'Добијајте недељне извештаје о испоручивости','Unlock these awesome reporting features:'=>'Откључајте ове сјајне могућности извештавања:','Weekly Email Report'=>'Недељни извештај о е-пошти','Detailed Stats by Subject Line'=>'Детаљна статистика по наслову','Stats at a Glance'=>'Статистика на први поглед','Email Reports'=>'Извештаји о е-пошти','Debug Events are Not Installed Correctly'=>'Догађаји за отклањање грешака нису исправно постављени','For some reason the database table was not installed correctly. Please contact plugin support team to diagnose and fix the issue.'=>'Из неког разлога табела базе података није исправно постављена. Обратите се тиму подршке додатка ради утврђивања и решавања проблема.','between %1$s and %2$s'=>'између %1$s и %2$s','on %s'=>'дана %s','Search Events'=>'Претражи догађаје','where event contains "%s"'=>'где догађај садржи „%s“','Check this if you would like to debug the email sending process. Once enabled, all debug events will be logged in the table below. This setting should only be enabled for shorter debugging periods and disabled afterwards.'=>'Означите ово ако желите да отклањате грешке у поступку слања е-поште. Када се укључи, сви догађаји за отклањање грешака биће забележени у табели испод. Ово подешавање треба укључивати само на краће периоде отклањања грешака и затим га искључити.','Found <strong>%1$s %2$s event</strong>'=>'Пронађен је <strong>%1$s %2$s догађај</strong>' . "\0" . 'Пронађена су <strong>%1$s %2$s догађаја</strong>' . "\0" . 'Пронађено је <strong>%1$s %2$s догађаја</strong>','Debug Email Sending'=>'Отклањање грешака при слању е-поште','This debug event is always enabled and will record any email sending errors in the table below.'=>'Овај догађај за отклањање грешака увек је укључен и бележиће све грешке слања е-поште у табели испод.','Email Sending Errors'=>'Грешке слања е-поште','Event Types'=>'Врсте догађаја','On this page, you can view and configure different plugin debugging events. View email sending errors and enable debugging events, allowing you to detect email sending issues.'=>'На овој страници можете прегледати и подесити разне догађаје за отклањање грешака додатка. Прегледајте грешке слања е-поште и укључите догађаје за отклањање грешака, што вам омогућава да откријете проблеме са слањем е-поште.','An error occurred!'=>'Дошло је до грешке!','Close'=>'Затвори','Are you sure you want to permanently delete all debug events?'=>'Да ли сигурно желите да трајно избришете све догађаје за отклањање грешака?','Debug Events'=>'Догађаји за отклањање грешака','Follow on Facebook'=>'Пратите на Facebook-у','Suggest a Feature'=>'Предложите могућност','Support & Docs'=>'Подршка и документација','See Quick Links'=>'Погледај брзе везе','Filter'=>'Филтрирај','Delete All Events'=>'Избриши све догађаје','No events have been logged for now.'=>'За сада није забележен ниједан догађај.','No events found.'=>'Није пронађен ниједан догађај.','Event'=>'Догађај','All'=>'Сви','%1$s (line: %2$s)'=>'%1$s (ред: %2$s)','Email Source: %s'=>'Извор е-поруке: %s','Content'=>'Садржај','Date'=>'Датум','Debug Event Details'=>'Детаљи догађаја за отклањање грешака','N/A'=>'-','Event #%d'=>'Догађај бр. %d','Number of events per page:'=>'Број догађаја по страници:','No Debug Event ID provided!'=>'Није наведен ID догађаја за отклањање грешака!','There was an issue while trying to delete all debug event entries. Error message: %s'=>'Дошло је до проблема при покушају брисања свих уноса догађаја за отклањање грешака. Порука о грешци: %s','All debug event entries were deleted successfully.'=>'Сви уноси догађаја за отклањање грешака успешно су избрисани.','You don\'t have the capability to perform this action.'=>'Немате способност да извршите ову радњу.','Weekly Email Summaries have been enabled'=>'Недељни сажеци е-поште су укључени','Access rejected.'=>'Приступ је одбијен.','View Example'=>'Погледај пример','Transparency and Disclosure'=>'Транспарентност и обелодањивање','We believe in full transparency. The Sendinblue links above are tracking links as part of our partnership with Sendinblue. We can recommend just about any SMTP service, but we only recommend products that we believe will add value to our users.'=>'Верујемо у потпуну транспарентност. Sendinblue везе изнад су везе за праћење као део нашег партнерства са Sendinblue-ом. Можемо да препоручимо скоро сваку SMTP услугу, али препоручујемо само производе за које верујемо да ће донети вредност нашим корисницима.','We believe in full transparency. The SMTP.com links above are tracking links as part of our partnership with SMTP (j2 Global). We can recommend just about any SMTP service, but we only recommend products that we believe will add value to our users.'=>'Верујемо у потпуну транспарентност. SMTP.com везе изнад су везе за праћење као део нашег партнерства са SMTP (j2 Global). Можемо да препоручимо скоро сваку SMTP услугу, али препоручујемо само производе за које верујемо да ће донети вредност нашим корисницима.','Enhanced Weekly Email Summary'=>'Побољшани недељни сажетак е-поште','Get statistics about emails you\'ve sent.'=>'Добијте статистику о е-порукама које сте послали.','Weekly Email Summary'=>'Недељни сажетак е-поште','Read how to set up Microsoft Outlook / 365'=>'Прочитајте како да подесите Microsoft Outlook / 365','<b>NEW!</b> Enable Weekly Email Summaries'=>'<b>НОВО!</b> Укључите недељне сажетке е-поште','Or disable the Sendinblue email sending setting in WooCommerce > Settings > Sendinblue (tab) > Email Options (tab) > Enable Sendinblue to send WooCommerce emails.'=>'Или искључите подешавање слања е-поште преко Sendinblue-а у WooCommerce > Settings > Sendinblue (језичак) > Email Options (језичак) > Enable Sendinblue to send WooCommerce emails.','Hide Dashboard Widget'=>'Сакриј виџет контролне табле','Email Addresses'=>'Е-адресе','Search'=>'Претрага','Select a date range'=>'Изаберите распон датума','Custom Date Range'=>'Произвољан опсег датума','Email log ID'=>'ID дневника е-поште','Headers'=>'Заглавља','Error Details'=>'Детаљи грешке','Blind Carbon Copy (BCC)'=>'Скривена копија (BCC)','Carbon Copy (CC)'=>'Копија (CC)','Additional Information'=>'Додатне информације','Attachments'=>'Прилози','Number of Attachments'=>'Број прилога','Created Date'=>'Датум прављења','Body'=>'Тело','Subject'=>'Подређено','From Address'=>'Адреса пошиљаоца','To Address'=>'Адреса примаоца','Common Information'=>'Општи подаци','Export in EML (.eml)'=>'Извези у EML (.eml)','Export in Microsoft Excel (.xlsx)'=>'Извези у Microsoft Excel (.xlsx)','Export in CSV (.csv)'=>'Извези у CSV (.csv)','Export Type'=>'Врста извоза','Export Email Logs'=>'Извези дневнике е-поште','Action Scheduler library is also used by other plugins, like WPForms and WooCommerce, so you might see tasks that are not related to our plugin in the table below.'=>'Библиотеку Action Scheduler користе и други додаци, као што су WPForms и WooCommerce, па у табели испод можете видети задатке који нису повезани са нашим додатком.','Search results for <strong>%s</strong>'=>'Резултати претраге за <strong>%s</strong>','WP Mail SMTP is using the <a href="%s" target="_blank" rel="noopener noreferrer">Action Scheduler</a> library, which allows it to queue and process bigger tasks in the background without making your site slower for your visitors. Below you can see the list of all tasks and their status. This table can be very useful when debugging certain issues.'=>'WP Mail SMTP користи библиотеку <a href="%s" target="_blank" rel="noopener noreferrer">Action Scheduler</a>, која му омогућава да ставља у ред и обрађује веће задатке у позадини без успоравања сајта за посетиоце. Испод можете видети списак свих задатака и њихово стање. Ова табела може бити веома корисна при отклањању одређених проблема.','Export'=>'Извези','Scheduled Actions'=>'Заказане акције','Notifications'=>'Обавештења','Sent %s'=>'Послато: %s','Failed %s'=>'Неуспело: %s','Unconfirmed %s'=>'Непотврђено: %s','Confirmed %s'=>'Потврђено: %s','%d total'=>'Укупно: %d','Table cell icon'=>'Иконица ћелије табеле','WordPress'=>'Вордпрес','Color Scheme'=>'Шема боја','Line'=>'LINE','Bar'=>'Трака','Graph Style'=>'Стил графикона','All Emails'=>'Све е-поруке','Select email type'=>'Изаберите врсту е-поруке','Sent Emails'=>'Послате е-поруке','Failed Emails'=>'Неуспеле е-поруке','Unconfirmed Emails'=>'Непотврђене е-поруке','Confirmed Emails'=>'Потврђене е-поруке','Last %d day'=>'Последњи %d дан' . "\0" . 'Последња %d дана' . "\0" . 'Последњих %d дана','All Time'=>'Све време','Select timespan'=>'Изаберите временски распон','Automatically keep track of every email sent from your WordPress site and view valuable statistics right here in your dashboard.'=>'Аутоматски пратите сваку е-поруку послату са вашег Вордпресовог сајта и прегледајте драгоцену статистику директно овде на контролној табли.','View Detailed Email Stats'=>'Погледај детаљну статистику е-поште','There was an error while processing the authentication request. Please recheck your Region, Client ID and Client Secret and try again.'=>'Дошло је до грешке при обради захтева за потврђивање идентитета. Поново проверите регион, Client ID и Client Secret и покушајте поново.','<a href="%s" target="_blank" rel="noopener noreferrer">Upgrade to Pro</a> for detailed stats, email logs, and more!'=>'<a href="%s" target="_blank" rel="noopener noreferrer">Надоградите на Pro</a> за детаљну статистику, дневнике е-поште и друго!','Email domain issues detected'=>'Откривени су проблеми са доменом е-поште','Email domain is configured correctly'=>'Домен е-поште је исправно подешен','All checks for your email domain were successful. It looks like everything is configured correctly.'=>'Све провере вашег домена е-поште су успеле. Изгледа да је све исправно подешено.','Current from email domain'=>'Тренутни домен е-адресе пошиљаоца','Is email domain configured properly?'=>'Да ли је домен е-поште исправно подешен?','Unable to write in WPMailSMTP upload directory %s. Is it writable by the server?'=>'Није могуће уписивати у фасциклу отпремања WPMailSMTP %s. Да ли сервер може да уписује у њу?','Unable to create directory %s. Is its parent directory writable by the server?'=>'Не могу да начиним директоријум %s. Да ли је родитељски директоријум уписив за сервер?','Tools'=>'Алатке','You can also send emails with different From Email addresses, by disabling the Force From Email setting and using registered aliases throughout your WordPress site as the From Email addresses.'=>'Можете слати е-поруке и са различитих е-адреса пошиљаоца тако што ћете искључити подешавање „Наметни е-адресу пошиљаоца“ и користити регистроване алијасе на свом Вордпресовом сајту као е-адресе пошиљаоца.','We\'ll guide you through each step needed to get WP Mail SMTP fully set up on your site.'=>'Провешћемо вас кроз сваки корак потребан да се WP Mail SMTP потпуно подеси на вашем сајту.','Launch Setup Wizard'=>'Покрени чаробњак за подешавање','Boost your sales and conversions by up to 15% with real-time social proof notifications. TrustPulse helps you show live user activity and purchases to help convince other users to purchase.'=>'Повећајте продају и конверзије до 15% помоћу обавештења о друштвеном доказу у стварном времену. TrustPulse вам помаже да прикажете активност корисника и куповине уживо како бисте убедили друге кориснике да купе.','Easily display Twitter content in WordPress without writing any code. Comes with multiple layouts, ability to combine multiple Twitter feeds, Twitter card support, tweet moderation, and more.'=>'Лако прикажите Twitter садржај у Вордпресу без писања кода. Долази са више распореда, могућношћу комбиновања више Twitter фидова, подршком за Twitter картице, модерацијом твитова и другим.','Easily display YouTube videos on your WordPress site without writing any code. Comes with multiple layouts, ability to embed live streams, video filtering, ability to combine multiple channel videos, and more.'=>'Лако прикажите YouTube видео-снимке на свом Вордпресовом сајту без писања кода. Долази са више распореда, могућношћу уграђивања преноса уживо, филтрирањем видео-снимака, могућношћу комбиновања видео-снимака са више канала и другим.','Easily display Facebook content on your WordPress site without writing any code. Comes with multiple templates, ability to embed albums, group content, reviews, live videos, comments, and reactions.'=>'Лако прикажите Facebook садржај на свом Вордпресовом сајту без писања кода. Долази са више шаблона, могућношћу уграђивања албума, садржаја група, рецензија, видео-снимака уживо, коментара и реакција.','Easily display Instagram content on your WordPress site without writing any code. Comes with multiple templates, ability to show content from multiple accounts, hashtags, and more. Trusted by 1 million websites.'=>'Лако прикажите Instagram садржај на свом Вордпресовом сајту без писања кода. Долази са више шаблона, могућношћу приказа садржаја са више налога, хештеговима и другим. Верује му милион веб сајтова.','Connect with your visitors after they leave your website with the leading web push notification software. Over 10,000+ businesses worldwide use PushEngage to send 15 billion notifications each month.'=>'Повежите се са посетиоцима када напусте ваш веб сајт помоћу водећег софтвера за веб push обавештења. Више од 10.000 предузећа широм света користи PushEngage за слање 15 милијарди обавештења месечно.','Turn your website visitors into brand ambassadors! Easily grow your email list, website traffic, and social media followers with the most powerful giveaways & contests plugin for WordPress.'=>'Претворите посетиоце веб сајта у амбасадоре бренда! Лако повећајте списак е-адреса, саобраћај на веб сајту и пратиоце на друштвеним мрежама уз најмоћнији додатак за наградне игре и такмичења за Вордпрес.','The fastest drag & drop landing page builder for WordPress. Create custom landing pages without writing code, connect them with your CRM, collect subscribers, and grow your audience. Trusted by 1 million sites.'=>'Најбржи градитељ одредишних страница превлачењем за Вордпрес. Правите произвољне одредишне странице без писања кода, повежите их са CRM-ом, прикупљајте претплатнике и повећајте публику. Верује му милион сајтова.','The original WordPress SEO plugin and toolkit that improves your website’s search rankings. Comes with all the SEO features like Local SEO, WooCommerce SEO, sitemaps, SEO optimizer, schema, and more.'=>'Изворни Вордпресов SEO додатак и скуп алата који побољшава позицију вашег веб сајта у претрази. Долази са свим SEO могућностима као што су локални SEO, WooCommerce SEO, мапе сајта, SEO оптимизатор, шема и друго.','The leading WordPress analytics plugin that shows you how people find and use your website, so you can make data driven decisions to grow your business. Properly set up Google Analytics without writing code.'=>'Водећи Вордпресов додатак за аналитику који вам показује како људи проналазе и користе ваш веб сајт, да бисте доносили одлуке засноване на подацима и развијали посао. Исправно подесите Google Analytics без писања кода.','The best drag & drop WordPress form builder. Easily create beautiful contact forms, surveys, payment forms, and more with our 600+ form templates. Trusted by over 5 million websites as the best forms plugin.'=>'Најбољи Вордпресов градитељ образаца са превлачењем. Лако правите лепе обрасце за контакт, анкете, обрасце за плаћање и друго уз више од 600 шаблона образаца. Више од 5 милиона веб сајтова му верује као најбољем додатку за обрасце.','Instantly get more subscribers, leads, and sales with the #1 conversion optimization toolkit. Create high converting popups, announcement bars, spin a wheel, and more with smart targeting and personalization.'=>'Одмах добијте више претплатника, потенцијалних купаца и продаје уз скуп алата бр. 1 за оптимизацију конверзије. Правите искачуће прозоре са високом конверзијом, траке са објавама, точак среће и друго уз паметно циљање и персонализацију.','Copy error log'=>'Умножи дневник грешака','You have successfully linked the current site with your Microsoft API project. Now you can start sending emails through Outlook.'=>'Успешно сте повезали тренутни сајт са својим Microsoft API пројектом. Сада можете почети да шаљете е-поруке преко Outlook-а.','Already purchased? Enter your license key below to connect with %1$sWP Mail SMTP Pro%2$s!'=>'Већ сте купили? Унесите лиценцни кључ испод да бисте се повезали са %1$sWP Mail SMTP Pro%2$s!','Please input the sending domain/subdomain you configured in your Sendinblue dashboard. More information can be found in our %1$sSendinblue documentation%2$s'=>'Унесите домен/поддомен за слање који сте подесили на Sendinblue контролној табли. Више података можете пронаћи у нашој %1$sдокументацији за Sendinblue%2$s','The following plugin will be installed for free: WPForms'=>'Следећи додатак биће бесплатно постављен: WPForms','You\'re currently using %1$sWP Mail SMTP Lite%2$s - no license needed. Enjoy!'=>'Тренутно користите %1$sWP Mail SMTP Lite%2$s – лиценца није потребна. Уживајте!','Please input the sending domain/subdomain you configured in your SendGrid dashboard. More information can be found in our %1$sSendGrid documentation%2$s'=>'Унесите домен/поддомен за слање који сте подесили на SendGrid контролној табли. Више података можете пронаћи у нашој %1$sдокументацији за SendGrid%2$s','Continue'=>'Настави','Return to Plugin Settings'=>'Врати се на подешавања додатка','Paste your license key here'=>'Убаците свој лиценцни кључ овде','Before continuing, you\'ll need to allow this plugin to send emails using your %s account.'=>'Пре него што наставите, морате дозволити овом додатку да шаље е-поруке помоћу вашег %s налога.','Upgrade Failed!'=>'Надоградња није успела!','Verification Error!'=>'Грешка провере!','Successful Verification!'=>'Провера је успела!','Successful Upgrade!'=>'Надоградња је успела!','Successful Authorization'=>'Овлашћење је успело','%1$s, %2$s'=>'%1$s, %2$s','Authorization Error!'=>'Грешка овлашћења!','Which mailer would you like to use to send emails? Not sure which mailer to choose? Check out our %1$scomplete mailer guide%2$s for details on each option.'=>'Коју услугу слања желите да користите за слање е-порука? Не знате коју да изаберете? Погледајте наш %1$sпотпуни водич за услуге слања%2$s за детаље о свакој могућности.','Error Message:'=>'Порука о грешци:','Installed'=>'Инсталирано','Please fill out all the required fields to continue.'=>'Попуните сва обавезна поља да бисте наставили.','Value has to be a round number'=>'Вредност мора бити цео број','Please enter a value between %1$s and %2$s'=>'Унесите вредност између %1$s и %2$s','It looks like we can\'t retrieve Amazon SES Identities.'=>'Изгледа да не можемо да преузмемо Amazon SES идентитете.','Can\'t retrieve Amazon SES Identities.'=>'Није могуће преузети Amazon SES идентитете.','Can\'t register the Amazon SES Identity'=>'Није могуће регистровати Amazon SES идентитет','It looks like we can\'t load the settings.'=>'Изгледа да не можемо да учитамо подешавања.','It looks like we can\'t load authentication details.'=>'Изгледа да не можемо да учитамо детаље потврђивања идентитета.','It looks like we can\'t import the plugin settings.'=>'Изгледа да не можемо да увеземо подешавања додатка.','Network error encountered. SMTP plugin import failed!'=>'Дошло је до грешке мреже. Увоз SMTP додатка није успео!','Network error encountered. Settings not saved.'=>'Дошло је до грешке мреже. Подешавања нису сачувана.','It looks like we can\'t save the settings.'=>'Изгледа да не можемо да сачувамо подешавања.','Pro badge'=>'Pro значка','License key input'=>'Унос лиценцног кључа','Your license was successfully verified! You are ready for the next step.'=>'Ваша лиценца је успешно потврђена! Спремни сте за следећи корак.','Verify License Key'=>'Провери лиценцни кључ','The License Key format is incorrect. Please enter a valid key and try again.'=>'Облик лиценцног кључа није исправан. Унесите исправан кључ и покушајте поново.','Enter your license key below to unlock plugin updates!'=>'Унесите лиценцни кључ испод да бисте откључали ажурирања додатка!','To unlock selected features, %1$sUpgrade to Pro%2$s and enter your license key below.'=>'Да бисте откључали изабране могућности, %1$sнадоградите на Pro%2$s и унесите лиценцни кључ испод.','Purchase Now'=>'Купи сада','I\'ll do it later'=>'Урадићу то касније','Enter your WP Mail SMTP License Key'=>'Унесите свој WP Mail SMTP лиценцни кључ','These features are available as part of WP Mail SMTP Pro plan.'=>'Ове могућности су доступне као део WP Mail SMTP Pro плана.','Help us spread the word %1$sby giving WP Mail SMTP a 5-star rating %3$s(%4$s) on WordPress.org%2$s. Thanks for your support and we look forward to bringing you more awesome features.'=>'Помозите нам да се прочује %1$sтако што ћете WP Mail SMTP-у дати оцену од 5 звездица %3$s(%4$s) на WordPress.org%2$s. Хвала на подршци, радујемо се што ћемо вам донети још сјајних могућности.','Rate on WordPress.org'=>'Оцени на WordPress.org','Would you like to purchase the following features now?'=>'Да ли желите да сада купите следеће могућности?','Thanks for the feedback!'=>'Хвала на утисцима!','Star icon'=>'Иконица звездице','%1$sBonus:%2$s You can upgrade to the Pro plan and %3$ssave %5$s today%4$s, automatically applied at checkout.'=>'%1$sБонус:%2$s можете надоградити на Pro план и %3$sуштедети %5$s већ данас%4$s, аутоматски примењено при плаћању.','Upgrade to Pro Today'=>'Надоградите на Pro већ данас','Upgrade to WP Mail SMTP Pro to unlock more awesome features and experience why WP Mail SMTP is used by over 4,000,000 websites.'=>'Надоградите на WP Mail SMTP Pro да бисте откључали још сјајних могућности и искусили зашто WP Mail SMTP користи више од 4.000.000 веб сајтова.','Upgrade to Unlock Powerful SMTP Features'=>'Надоградите да бисте откључали моћне SMTP могућности','Check out our other free WordPress plugins:'=>'Погледајте наше друге бесплатне Вордпресове додатке:','Here’s what to do next:'=>'Ево шта следеће да урадите:','Congrats, you’ve successfully set up WP Mail SMTP!'=>'Честитамо, успешно сте подесили WP Mail SMTP!','Our goal is to make your SMTP setup as simple and straightforward as possible. We\'d love to know how this process went for you!'=>'Наш циљ је да подешавање SMTP-а буде што једноставније и јасније. Волели бисмо да знамо како је овај поступак прошао за вас!','Submit Feedback'=>'Пошаљи повратне податке','How was your WP Mail SMTP setup experience?'=>'Какво је било ваше искуство подешавања WP Mail SMTP?','Yes, I give WP Mail SMTP permission to contact me for any follow up questions.'=>'Да, дајем WP Mail SMTP-у дозволу да ме контактира због додатних питања.','What could we do to improve?'=>'Шта бисмо могли да побољшамо?','We\'re sorry things didn\'t go smoothly for you, and want to keep improving. Please let us know any specific parts of this process that you think could be better. We really appreciate any details you\'re willing to share!'=>'Жао нам је што није све прошло глатко и желимо да наставимо да се побољшавамо. Јавите нам које делове овог поступка мислите да би требало побољшати. Заиста ценимо све детаље које сте спремни да поделите!','Save time with powerful WordPress Multisite controls.'=>'Уштедите време уз моћне контроле Вордпресове мреже сајтова.','Multisite Network Settings'=>'Подешавања мреже сајтова','Manage Default Notifications'=>'Управљај подразумеваним обавештењима','Control which email notifications your WordPress site sends.'=>'Одредите која обавештења е-поштом ваш Вордпресов сајт шаље.','Keep records of every email that\'s sent out from your website.'=>'Водите евиденцију о свакој е-поруци послатој са вашег веб сајта.','Detailed Email Logs'=>'Детаљни дневници е-поште','Smart Contact Form'=>'Паметан образац за контакт','Easily spot errors causing delivery issues.'=>'Лако уочите грешке које изазивају проблеме са испоруком.','Create beautiful contact forms with just a few clicks.'=>'Правите лепе обрасце за контакт у само неколико притисака.','Email Error Tracking'=>'Праћење грешака е-поште','Ensure your emails are sent successfully and reliably.'=>'Обезбедите да се ваше е-поруке шаљу успешно и поуздано.','Make sure you\'re getting the most out of WP Mail SMTP. Just check all of the features you\'d like to use, and we\'ll go ahead and enable those for you.'=>'Уверите се да извлачите највише из WP Mail SMTP. Само означите све могућности које желите да користите, а ми ћемо их укључити уместо вас.','Improved Email Deliverability'=>'Побољшана испоручивост е-поште','Which email features do you want to enable?'=>'Које могућности е-поште желите да укључите?','Help make WP Mail SMTP better for everyone'=>'Помозите да WP Mail SMTP буде бољи за све','Yes, count me in'=>'Да, рачунајте на мене','Enable Auto TLS'=>'Укључи аутоматски TLS','Your email is needed, so you can receive recommendations.'=>'Потребна је ваша е-адреса да бисте могли да добијате препоруке.','Help Improve WP Mail SMTP + Smart Recommendations'=>'Помозите да се побољша WP Mail SMTP + паметне препоруке','Get helpful suggestions from WP Mail SMTP on how to optimize your email deliverability and grow your business.'=>'Добијајте корисне предлоге од WP Mail SMTP о томе како да оптимизујете испоручивост е-поште и развијете посао.','Your Email Address'=>'Ваша е-адреса','Below, we\'ll show you all of the settings required to set up this mailer.'=>'Испод ћемо вам приказати сва подешавања потребна за подешавање ове услуге слања.','Configure Mailer Settings'=>'Подеси услугу слања','We\'re running some tests in the background to make sure everything is set up properly.'=>'У позадини покрећемо неке тестове да бисмо се уверили да је све исправно подешено.','Checking mailer configuration image'=>'Слика провере подешавања услуге слања','Checking Mailer Configuration'=>'Провера подешавања услуге слања','You appear to be offline. Plugin information not retrieved.'=>'Изгледа да нисте на мрежи. Подаци о додатку нису преузети.','It looks like we can\'t fetch plugins information.'=>'Изгледа да не можемо да преузмемо податке о додацима.','Can\'t fetch plugins information.'=>'Није могуће преузети податке о додацима.','You appear to be offline. Plugin not installed.'=>'Изгледа да нисте на мрежи. Додатак није постављен.','You appear to be offline.'=>'Изгледа да нисте на мрежи.','It looks like the plugin installation failed!'=>'Изгледа да постављање додатка није успело!','It looks like we can\'t install the plugin.'=>'Изгледа да не можемо да поставимо додатак.','It looks like we can\'t send the feedback.'=>'Изгледа да не можемо да пошаљемо утиске.','It looks like we can\'t perform the mailer configuration check.'=>'Изгледа да не можемо да извршимо проверу подешавања услуге слања.','Enter the domain name to verify it on Amazon SES and generate the required DNS CNAME records.'=>'Унесите име домена да бисте га потврдили на Amazon SES и направили потребне DNS CNAME записе.','Enter a valid email address. A verification email will be sent to the email address you entered.'=>'Унесите исправну е-адресу. На е-адресу коју сте унели биће послата е-порука за проверу.','Please enter a valid email address'=>'Унесите исправну адресу е-поште','Verify Email Address'=>'Потврди е-адресу','Verify Domain'=>'Потврди домен','Please enter a domain'=>'Унесите домен','Please add these CNAME records to your domain\'s DNS settings. For information on how to add CNAME DNS records, please refer to the %1$sAmazon SES documentation%2$s.'=>'Додајте ове CNAME записе у DNS подешавања свог домена. За податке о томе како да додате CNAME DNS записе погледајте %1$sдокументацију за Amazon SES%2$s.','Value'=>'Вредност','Add New SES Identity'=>'Додај нови SES идентитет','Name'=>'Име','Verify SES Identity'=>'Потврди SES идентитет','Here are the domains and email addresses that have been verified and can be used as the From Email.'=>'Ево домена и е-адреса које су потврђене и могу да се користе као е-адреса пошиљаоца.','Resend'=>'Пошаљи поново','View DNS'=>'Погледај DNS','You will not be able to send emails until you verify at least one domain or email address for the selected Amazon SES Region.'=>'Нећете моћи да шаљете е-поруке док не потврдите бар један домен или е-адресу за изабрани Amazon SES регион.','No registered domains or emails.'=>'Нема регистрованих домена или е-адреса.','Verify Email'=>'Потврди е-пошту','Connected as'=>'Повезано као','Removing this OAuth connection will give you the ability to redo the OAuth connection or connect to different %s account.'=>'Уклањање ове OAuth везе омогућиће вам да поново успоставите OAuth везу или се повежете са другим %s налогом.','If you want to use a different From Email address you can setup a Google email alias. %1$sFollow these instructions%2$s, then select the alias in the From Email section below.'=>'Ако желите да користите другу е-адресу пошиљаоца, можете подесити Google алијас е-адресе. %1$sПратите ова упутства%2$s, а затим изаберите алијас у одељку е-адресе пошиљаоца испод.','Connect to %s'=>'Повежи се са %s','There was an error while processing the authentication request. Please recheck your Client ID and Client Secret and try again.'=>'Дошло је до грешке при обради захтева за потврђивање идентитета. Поново проверите Client ID и Client Secret и покушајте поново.','Copied!'=>'Умножено!','The value entered does not match the required format'=>'Унета вредност не одговара захтеваном облику','Copy input value'=>'Умножи унету вредност','Step %1$s of %2$s'=>'Корак %1$s од %2$s','It looks like we can\'t register the Amazon SES Identity.'=>'Изгледа да не можемо да региструјемо Amazon SES идентитет.','It looks like we can\'t load oAuth redirect.'=>'Изгледа да не можемо да учитамо oAuth преусмеравање.','It looks like we can\'t retrieve the Amazon SES Identities.'=>'Изгледа да не можемо да преузмемо Amazon SES идентитете.','It looks like we can\'t remove oAuth connection.'=>'Изгледа да не можемо да уклонимо oAuth везу.','It looks like we can\'t load existing settings.'=>'Изгледа да не можемо да учитамо постојећа подешавања.','It looks like we can\'t load oAuth connected data.'=>'Изгледа да не можемо да учитамо податке oAuth везе.','Read how to set up Sendgrid'=>'Прочитајте како да подесите Sendgrid','To send emails you will need only a %1$sMail Send%2$s access level for this API key.'=>'За слање е-порука потребан вам је само ниво приступа %1$sMail Send%2$s за овај API кључ.','%1$sFollow this link%2$s to get an API Key for Sendgrid.'=>'%1$sПратите ову везу%2$s да бисте добили API кључ за Sendgrid.','Read how to set up Amazon SES'=>'Прочитајте како да подесите Amazon SES','Please select the Amazon SES API region which is the closest to where your website is hosted. This can help to decrease network latency between your site and Amazon SES, which will speed up email sending.'=>'Изаберите Amazon SES API регион који је најближи месту где је ваш веб сајт хостован. То може да смањи мрежно кашњење између вашег сајта и Amazon SES-а, што ће убрзати слање е-поште.','SES Identities'=>'SES идентитети','Secret Access Key'=>'Тајни приступни кључ','Access Key ID'=>'ID приступног кључа','Recommended Mailers'=>'Препоручене услуге слања','Save and Continue'=>'Сачувај и настави','Choose Your SMTP Mailer'=>'Изаберите своју SMTP услугу слања','is a PRO Feature'=>'је PRO могућност','Choose a Different Mailer'=>'Изабери другу услугу слања','I Understand, Continue'=>'Разумем, настави','Read how to set up the Gmail mailer'=>'Прочитајте како да подесите Gmail услугу слања','Select which email address you would like to send your emails from.'=>'Изаберите са које е-адресе желите да шаљете своје е-поруке.','Authorized Redirect URI'=>'Овлашћени URI за преусмеравање','Application Password'=>'Лозинка апликације','Application ID'=>'ID апликације','Read how to set up Mailgun'=>'Прочитајте како да подесите Mailgun','Define which endpoint you want to use for sending messages. If you are operating under EU laws, you may be required to use EU region. %1$sMore information%2$s on Mailgun.com.'=>'Одредите коју крајњу тачку желите да користите за слање порука. Ако пословање подлеже законима ЕУ, можда ћете морати да користите регион ЕУ. %1$sВише података%2$s на Mailgun.com.','%1$sFollow this link%2$s to get a Domain Name from Mailgun.'=>'%1$sПратите ову везу%2$s да бисте добили име домена од Mailgun-а.','Read how to set up Zoho Mail'=>'Прочитајте како да подесите Zoho Mail','%1$sFollow this link%2$s to get an API Key for Brevo.'=>'%1$sПратите ову везу%2$s да бисте добили API кључ за Brevo.','Redirect URI'=>'URI за преусмеравање','The data center location used by your Zoho account.'=>'Локација центра података коју користи ваш Zoho налог.','Get Started with Sendinblue'=>'Почните са Sendinblue-ом','Read how to set up Sendinblue'=>'Прочитајте како да подесите Sendinblue','%1$sFollow this link%2$s to get an API Key for Sendinblue.'=>'%1$sПратите ову везу%2$s да бисте добили API кључ за Sendinblue.','Read how to set up SMTP.com'=>'Прочитајте како да подесите SMTP.com','If enabled, the From Email setting above will be used for all emails, ignoring values set by other plugins.'=>'Ако је укључено, подешавање е-адресе пошиљаоца изнад користиће се за све е-поруке, уз занемаривање вредности које постављају други додаци.','If enabled, the From Name setting above will be used for all emails, ignoring values set by other plugins.'=>'Ако је укључено, подешавање имена пошиљаоца изнад користиће се за све е-поруке, уз занемаривање вредности које постављају други додаци.','%1$sFollow this link%2$s to get an API Key for SMTP.com.'=>'%1$sПратите ову везу%2$s да бисте добили API кључ за SMTP.com.','%1$sFollow this link%2$s to get a Sender Name for SMTP.com.'=>'%1$sПратите ову везу%2$s да бисте добили име пошиљаоца за SMTP.com.','Finish Setup'=>'Заврши подешавање','Send us Feedback'=>'Пошаљите нам утиске','Start Troubleshooting'=>'Почни решавање проблема','We just tried to send a test email, but something prevented that from working. To see more details about the issue we detected, as well as our suggestions to fix it, please start troubleshooting.'=>'Управо смо покушали да пошаљемо пробну е-поруку, али нешто је то спречило. Да бисте видели више детаља о проблему који смо открили, као и наше предлоге за решење, започните решавање проблема.','Whoops, looks like things aren’t configured properly.'=>'Упс, изгледа да ствари нису исправно подешене.','WP SMTP'=>'WP SMTP','SMTP Mailer'=>'SMTP Mailer','Post SMTP Mailer'=>'Post SMTP Mailer','Easy WP SMTP'=>'Easy WP SMTP','Previous Step'=>'Претходни корак','Skip this Step'=>'Прескочи овај корак','Import Data and Continue'=>'Увези податке и настави','We have detected other SMTP plugins installed on your website. Select which plugin\'s data you would like to import to WP Mail SMTP.'=>'Открили смо друге SMTP додатке постављене на вашем веб сајту. Изаберите податке ког додатка желите да увезете у WP Mail SMTP.','Import data from your current plugins'=>'Увезите податке из тренутних додатака','Close and exit the Setup Wizard'=>'Затвори и изађи из чаробњака за подешавање','Let\'s Get Started'=>'Хајде да почнемо','Welcome to the WP Mail SMTP Setup Wizard!'=>'Добро дошли у чаробњак за подешавање WP Mail SMTP!','Whoops, we found an issue!'=>'Упс, пронашли смо проблем!','It looks like something went wrong...'=>'Изгледа да нешто није у реду...','Could Not Save Changes'=>'Није могуће сачувати измене','Return to Mailer Settings'=>'Врати се на подешавања услуге слања','Settings Updated'=>'Подешавања су ажурирана','Yikes! WordPress Update Required'=>'Упс! Потребно је ажурирање Вордпреса','WP Mail SMTP has detected that your site is running an outdated version of WordPress (%s). WP Mail SMTP requires at least WordPress version 4.9.'=>'WP Mail SMTP је открио да ваш сајт користи застарело издање Вордпреса (%s). WP Mail SMTP захтева најмање Вордпрес издање 4.9.','WP Mail SMTP has detected that your site is running an outdated, insecure version of PHP (%1$s). Some mailers require at least PHP version 5.6. Updating to the recommended version (PHP %2$s) only takes a few minutes and will make your website significantly faster and more secure.'=>'WP Mail SMTP је открио да ваш сајт користи застарело, небезбедно издање PHP-а (%1$s). Неке услуге слања захтевају најмање PHP издање 5.6. Ажурирање на препоручено издање (PHP %2$s) траје само неколико минута и учиниће ваш веб сајт знатно бржим и безбеднијим.','Please check the inbox of <b>%s</b> for a confirmation email.'=>'Проверите сандуче <b>%s</b> за е-поруку потврде.','Yikes! PHP Update Required'=>'Упс! Потребно је ажурирање PHP-а','WP Mail SMTP has detected that your site is running an outdated, insecure version of PHP (%1$s), which could be putting your site at risk for being hacked. WordPress stopped supporting your PHP version in April, 2019. Updating to the recommended version (PHP %2$s) only takes a few minutes and will make your website significantly faster and more secure.'=>'WP Mail SMTP је открио да ваш сајт користи застарело, небезбедно издање PHP-а (%1$s), што може изложити ваш сајт ризику од хаковања. Вордпрес је престао да подржава ваше издање PHP-а у априлу 2019. Ажурирање на препоручено издање (PHP %2$s) траје само неколико минута и учиниће ваш веб сајт знатно бржим и безбеднијим.','Something went wrong. Please try again later.'=>'Нешто није у реду. Покушајте поново касније.','Upgrade functionality not available!'=>'Функционалност надоградње није доступна!','Please enter a valid license key!'=>'Унесите исправан лиценцни кључ!','You don\'t have the permission to perform this action.'=>'Немате дозволу да извршите ову радњу.','You are already using the WP Mail SMTP PRO version. Please refresh this page and verify your license key.'=>'Већ користите WP Mail SMTP PRO издање. Освежите ову страницу и потврдите свој лиценцни кључ.','WP Call Button'=>'WP Call Button','SeedProd Landing Page Builder'=>'SeedProd Landing Page Builder','Smash Balloon Social Photo Feed'=>'Smash Balloon Social Photo Feed','Giveaways by RafflePress'=>'Наградне игре помоћу RafflePress','All in One SEO'=>'All in One SEO','Google Analytics by MonsterInsights'=>'Google Analytics помоћу MonsterInsights','Could not install the plugin. WP Plugin installer initialization failed.'=>'Није могуће поставити додатак. Покретање WP инсталатера додатака није успело.','Could not install the plugin. Plugin slug is missing.'=>'Није могуће поставити додатак. Недостаје кратко име додатка.','Could not install the plugin. You don\'t have permission to install plugins.'=>'Није могуће поставити додатак. Немате дозволу да постављате додатке.','You don\'t have permission to change options for this WP site!'=>'Немате дозволу да мењате могућности за овај WP сајт!','Copy the error message above and paste it in a message to the WP Mail SMTP support team.'=>'Умножите поруку о грешци изнад и убаците је у поруку тиму подршке WP Mail SMTP.','Contact Us'=>'Обратите нам се','If you\'ve checked each of these details and are still running into issues, then please get in touch with our support team. We’d be happy to help!'=>'Ако сте проверили сваки од ових детаља и и даље имате проблема, обратите се нашем тиму подршке. Радо ћемо помоћи!','Confirm that your browser is updated to the latest version.'=>'Потврдите да је ваш прегледач ажуриран на најновије издање.','If you aren\'t already using Chrome, Firefox, Safari, or Edge, then please try switching to one of these popular browsers.'=>'Ако већ не користите Chrome, Firefox, Safari или Edge, покушајте да пређете на неки од ових популарних прегледача.','If you are using an ad blocker, please disable it or whitelist the current page.'=>'Ако користите блокатор огласа, искључите га или ставите тренутну страницу на списак дозвољених.','In order to fix this issue, please check each of the items below:'=>'Да бисте решили овај проблем, проверите сваку од ставки испод:','It looks like something is preventing JavaScript from loading on your website. WP Mail SMTP requires JavaScript in order to give you the best possible experience.'=>'Изгледа да нешто спречава учитавање JavaScript-а на вашем веб сајту. WP Mail SMTP захтева JavaScript да би вам пружио најбоље могуће искуство.','WP Mail SMTP logo'=>'WP Mail SMTP логотип','Whoops, something\'s not working.'=>'Упс, нешто не ради.','Go back to the Dashboard'=>'Врати се на контролну таблу','WP Mail SMTP &rsaquo; Setup Wizard'=>'WP Mail SMTP &rsaquo; чаробњак за подешавање','We\'re sorry, the %mailer% mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Нажалост, услуга слања %mailer% није доступна у вашем плану. Надоградите на PRO план да бисте откључали све ове сјајне могућности.','Setup Wizard'=>'Чаробњак за подешавање','%s icon'=>'%s иконица','Domain Check Results'=>'Резултати провере домена','The test email might have sent, but its deliverability should be improved.'=>'Пробна е-порука је можда послата, али њену испоручивост треба побољшати.','If updating the API Key doesn\'t resolve this issue, please contact our support.'=>'Ако ажурирање API кључа не реши овај проблем, обратите се нашој подршци.','Make sure your API Key in the SendGrid mailer settings is correct and valid.'=>'Уверите се да је ваш API кључ у подешавањима услуге слања SendGrid тачан и исправан.','Save the plugin settings.'=>'Сачувајте подешавања додатка.','Invalid SendGrid API key.'=>'Неисправан SendGrid API кључ.','Connect'=>'Повежи','Already purchased? Simply enter your license key below to connect with WP Mail SMTP Pro!'=>'Већ сте купили? Само унесите лиценцни кључ испод да бисте се повезали са WP Mail SMTP Pro!','<strong>Bonus:</strong> WP Mail SMTP users get <span class="highlight">%s off</span> regular price,<br>applied at checkout.'=>'<strong>Бонус:</strong> корисници WP Mail SMTP добијају <span class="highlight">%s попуста</span> на редовну цену,<br>примењено при плаћању.','Pro version installed but needs to be activated on the Plugins page.'=>'Pro издање је постављено, али мора да се укључи на страници додатака.','There was an error while installing an upgrade. Please try again.'=>'Дошло је до грешке при постављању надоградње. Покушајте поново.','There was an error while installing an upgrade. Please check file system permissions and try again. Also, you can download the plugin from wpmailsmtp.com and install it manually.'=>'Дошло је до грешке при постављању надоградње. Проверите дозволе система датотека и покушајте поново. Можете и да преузмете додатак са wpmailsmtp.com и поставите га ручно.','There was an error while generating an upgrade URL. Please try again.'=>'Дошло је до грешке при прављењу URL-а за надоградњу. Покушајте поново.','There was an error while installing an upgrade. Please download the plugin from wpmailsmtp.com and install it manually.'=>'Дошло је до грешке при постављању надоградње. Преузмите додатак са wpmailsmtp.com и поставите га ручно.','Only the Lite version can be upgraded.'=>'Само Lite издање може да се надогради.','Please enter your license key to connect.'=>'Унесите лиценцни кључ да бисте се повезали.','You are not allowed to install plugins.'=>'Није вам дозвољено да постављате додатке.','OK'=>'У реду','Please input the sending domain/subdomain you configured in your Brevo (formerly Sendinblue) dashboard. More information can be found in our <a href="%s" target="_blank" rel="noopener noreferrer">Brevo documentation</a>.'=>'Унесите домен/поддомен за слање који сте подесили на Brevo (раније Sendinblue) контролној табли. Више података можете пронаћи у нашој <a href="%s" target="_blank" rel="noopener noreferrer">документацији за Brevo</a>.','Please input the sending domain/subdomain you configured in your SendGrid dashboard. More information can be found in our <a href="%s" target="_blank" rel="noopener noreferrer">SendGrid documentation</a>.'=>'Унесите домен/поддомен за слање који сте подесили на SendGrid контролној табли. Више података можете пронаћи у нашој <a href="%s" target="_blank" rel="noopener noreferrer">документацији за SendGrid</a>.','Sending Domain'=>'Домен за слање','Please make sure your Google Client ID and Secret in the plugin settings are valid. Save the settings and try the Authorization again.'=>'Уверите се да су ваш Google Client ID и Secret у подешавањима додатка исправни. Сачувајте подешавања и поново покушајте овлашћење.','The email message ID is missing.'=>'Недостаје ID е-поруке.','The response object is invalid (missing getId method).'=>'Објекат одговора није исправан (недостаје метода getId).','The password is encrypted in the database, but for improved security we recommend using your site\'s WordPress configuration file to set your password.'=>'Лозинка је шифрована у бази података, али ради веће безбедности препоручујемо да лозинку поставите у Вордпресовој датотеци подешавања свог сајта.','If enabled, these global settings will manage email sending for all subsites of this multisite.'=>'Ако је укључено, ова општа подешавања управљаће слањем е-поште за све подсајтове ове мреже сајтова.','If disabled, each subsite of this multisite will have its own WP Mail SMTP settings page that has to be configured separately.'=>'Ако је искључено, сваки подсајт ове мреже сајтова имаће сопствену страницу WP Mail SMTP подешавања која мора да се подеси засебно.','Make the plugin settings global network-wide'=>'Учини подешавања додатка општим за целу мрежу','Settings control'=>'Управљање подешавањима','Simply enable network-wide settings and every site on your network will inherit the same SMTP settings. Save time and only configure your SMTP provider once.'=>'Само укључите подешавања за целу мрежу и сваки сајт у вашој мрежи наследиће иста SMTP подешавања. Уштедите време и подесите свог SMTP пружаоца само једном.','Pro+ badge icon'=>'Иконица Pro+ значке','Multisite'=>'Мрежа сајтова','Loading'=>'Учитавање','None selected'=>'Ништа није изабрано','M j, Y @ g:ia'=>'j. F Y. @ G:i','Lite install date'=>'Датум постављања Lite издања','We\'re sorry, the Zoho Mail mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Нажалост, услуга слања Zoho Mail није доступна у вашем плану. Надоградите на PRO план да бисте откључали све ове сјајне могућности.','Zoho Mail'=>'Zoho Mail','By allowing us to track usage data we can better help you because we know with which WordPress configurations, themes and plugins we should test.'=>'Ако нам дозволите да пратимо податке о коришћењу, можемо вам боље помоћи јер ћемо знати са којим Вордпресовим конфигурацијама, темама и додацима треба да испробавамо.','Allow Usage Tracking'=>'Дозволи праћење коришћења','Dismiss this message.'=>'Одбаци ову поруку.','Next message'=>'Следећа порука','Previous message'=>'Претходна порука','Dismiss this message'=>'Одбаци ову поруку','Plugin icon'=>'Иконица додатка','Missing table: %s'=>'Недостаје табела: %s' . "\0" . 'Недостају табеле: %s' . "\0" . 'Недостају табеле: %s','WP Mail SMTP DB tables check has failed'=>'Провера табела базе података WP Mail SMTP није успела','WP Mail SMTP DB tables are created'=>'Табеле базе података WP Mail SMTP су направљене','WP Mail SMTP is using custom database tables for some of its features. In order to work properly, the custom tables should be created, and it looks like they exist in your database.'=>'WP Mail SMTP користи произвољне табеле базе података за неке своје могућности. Да би исправно радио, произвољне табеле морају бити направљене, а изгледа да постоје у вашој бази података.','DB tables'=>'Табеле базе података','No DB tables found.'=>'Нису пронађене табеле базе података.','Do WP Mail SMTP DB tables exist?'=>'Да ли постоје табеле базе података WP Mail SMTP?','If you want to use a different From Email address you can set up a Google email alias. <a href="%s" target="_blank" rel="noopener noreferrer">Follow these instructions</a> and then select the From Email at the top of this page.'=>'Ако желите да користите другу е-адресу пошиљаоца, можете подесити Google алијас е-адресе. <a href="%s" target="_blank" rel="noopener noreferrer">Пратите ова упутства</a>, а затим изаберите е-адресу пошиљаоца на врху ове странице.','General error'=>'Општа грешка','Error'=>'Грешка','There was an error while upgrading the database. Please contact %1$s support with this information: %2$s.'=>'Дошло је до грешке при надоградњи базе података. Обратите се подршци за %1$s са овим подацима: %2$s.','Warning icon'=>'Иконица упозорења','Cancel'=>'Одустани','<p>The Default (PHP) mailer is currently selected, but is not recommended because in most cases it does not resolve email delivery issues.</p><p>Please consider selecting and configuring one of the other mailers.</p>'=>'<p>Тренутно је изабрана подразумевана (PHP) услуга слања, али се не препоручује јер у већини случајева не решава проблеме са испоруком е-поште.</p><p>Размислите о избору и подешавању неке друге услуге слања.</p>','Heads up!'=>'Пажња!','I already did'=>'Оцена је већ дата','No, maybe later'=>'Не, можда касније','No thanks'=>'Не, хвала','We\'re sorry to hear you aren\'t enjoying WP Mail SMTP. We would love a chance to improve. Could you take a minute and let us know what we can do better?'=>'Жао нам је што не уживате у WP Mail SMTP. Волели бисмо прилику да се побољшамо. Можете ли да одвојите минут и кажете нам шта можемо боље да урадимо?','Yes'=>'Да','Are you enjoying WP Mail SMTP?'=>'Да ли уживате у WP Mail SMTP?','PCRE library issue.'=>'Проблем са PCRE библиотеком.','GuzzleHttp requirements.'=>'Захтеви за GuzzleHttp.','Edit your php.ini file on your hosting server.'=>'Измените датотеку php.ini на серверу хостинга.','Please make sure you entered an accurate Sender Name in WP Mail SMTP plugin settings.'=>'Уверите се да сте унели тачно име пошиљаоца у подешавањима додатка WP Mail SMTP.','SMTP.com API Error.'=>'SMTP.com API грешка.','Verify that the host\'s SSL certificate is valid.'=>'Проверите да ли је SSL сертификат домаћина исправан.','Misconfigured server certificate.'=>'Погрешно подешен сертификат сервера.','Then click the “Allow plugin to send emails using your Google account” button and re-enable access.'=>'Затим притисните дугме „Дозволи додатку да шаље е-поруке помоћу вашег Google налога“ и поново укључите приступ.','Go to WP Mail SMTP plugin settings page. Click the “Remove OAuth Connection” button.'=>'Идите на страницу подешавања додатка WP Mail SMTP. Притисните дугме „Уклони OAuth везу“.','Please re-grant Google app permissions!'=>'Поново доделите дозволе Google апликацији!','Please read this <a href="%s" target="_blank" rel="noopener noreferrer">support article</a> if you want to enable this option using constants.'=>'Прочитајте овај <a href="%s" target="_blank" rel="noopener noreferrer">чланак подршке</a> ако желите да укључите ову могућност помоћу константи.','If you\'d prefer not to set up SSL, or need an SMTP solution in the meantime, please select a different mailer option.'=>'Ако не желите да подесите SSL или вам у међувремену треба SMTP решење, изаберите другу услугу слања.','%s requires an SSL certificate, and so is not currently compatible with your site. Please contact your host to request a SSL certificate, or check out <a href="https://www.wpbeginner.com/wp-tutorials/how-to-add-ssl-and-https-in-wordpress/" target="_blank">WPBeginner\'s tutorial on how to set up SSL</a>.'=>'%s захтева SSL сертификат, па тренутно није усаглашен са вашим сајтом. Обратите се свом хостингу да затражите SSL сертификат или погледајте <a href="https://www.wpbeginner.com/wp-tutorials/how-to-add-ssl-and-https-in-wordpress/" target="_blank">WPBeginner-ово упутство о томе како да подесите SSL</a>.','Learn More'=>'Сазнајте више','Get Started with Pepipost'=>'Почните са Pepipost-ом','Get Sender Name'=>'Набави име пошиљаоца','Follow this link to get a Sender Name from SMTP.com: %s.'=>'Пратите ову везу да бисте добили име пошиљаоца од SMTP.com: %s.','Sender Name'=>'Име пошиљаоца','Get API Key'=>'Набави API кључ','Follow this link to get an API Key from SMTP.com: %s.'=>'Пратите ову везу да бисте добили API кључ од SMTP.com: %s.','SMTP.com'=>'SMTP.com','Get Started with SMTP.com'=>'Почните са SMTP.com','Channel:'=>'Канал:','Go to WP Mail SMTP Settings page'=>'Иди на страницу WP Mail SMTP подешавања','Don\'t see what you\'re looking for?'=>'Не видите оно што тражите?','The WP Mail SMTP plugin mailer setup is incomplete. Please click on the link below to access plugin settings and configure the mailer.'=>'Подешавање услуге слања додатка WP Mail SMTP није довршено. Притисните везу испод да бисте приступили подешавањима додатка и подесили услугу слања.','Configure mailer'=>'Подеси услугу слања','WP Mail SMTP mailer setup is incomplete'=>'Подешавање WP Mail SMTP услуге слања није довршено','The WP Mail SMTP plugin mailer setup is complete. You can send a test email, to make sure it\'s working properly.'=>'Подешавање услуге слања додатка WP Mail SMTP је довршено. Можете послати пробну е-поруку да бисте се уверили да исправно ради.','Test email sending'=>'Испробај слање е-поште','You currently have the default mailer selected, which means that you haven’t set up SMTP yet.'=>'Тренутно имате изабрану подразумевану услугу слања, што значи да још нисте подесили SMTP.','WP Mail SMTP mailer setup is complete'=>'Подешавање WP Mail SMTP услуге слања је довршено','Current mailer'=>'Тренутна услуга слања','No debug notices found.'=>'Нису пронађена обавештења за отклањање грешака.','License key type'=>'Врста лиценцног кључа','Changes that you made to the settings are not saved!'=>'Измене које сте направили у подешавањима нису сачуване!','Is WP Mail SMTP mailer setup complete?'=>'Да ли је подешавање WP Mail SMTP услуге слања довршено?','Debug'=>'Отклањање квара','WP Mail SMTP is brought to you by the same team that\'s behind the most user friendly WordPress forms, <a href="%1$s" target="_blank" rel="noopener noreferrer">WPForms</a>, the largest WordPress resource site, <a href="%2$s" target="_blank" rel="noopener noreferrer">WPBeginner</a>, the most popular lead-generation software, <a href="%3$s" target="_blank" rel="noopener noreferrer">OptinMonster</a>, the best WordPress analytics plugin, <a href="%4$s" target="_blank" rel="noopener noreferrer">MonsterInsights</a>, and <a href="%5$s" target="_blank" rel="noopener noreferrer">more</a>.'=>'WP Mail SMTP вам доноси исти тим који стоји иза Вордпресових образаца најлакших за коришћење, <a href="%1$s" target="_blank" rel="noopener noreferrer">WPForms</a>, највећег Вордпресовог сајта са ресурсима, <a href="%2$s" target="_blank" rel="noopener noreferrer">WPBeginner</a>, најпопуларнијег софтвера за прикупљање потенцијалних купаца, <a href="%3$s" target="_blank" rel="noopener noreferrer">OptinMonster</a>, најбољег Вордпресовог додатка за аналитику, <a href="%4$s" target="_blank" rel="noopener noreferrer">MonsterInsights</a>, и <a href="%5$s" target="_blank" rel="noopener noreferrer">других</a>.','Pepipost SMTP'=>'Pepipost SMTP','Suggest a Mailer'=>'Предложите услугу слања','Get the API Key'=>'Набави API кључ','Read our <a href="%2$s" target="_blank" rel="noopener noreferrer">Pepipost documentation</a> to learn how to configure Pepipost and improve your email deliverability.'=>'Прочитајте нашу <a href="%2$s" target="_blank" rel="noopener noreferrer">документацију за Pepipost</a> да бисте сазнали како да подесите Pepipost и побољшате испоручивост е-поште.','<a href="%1$s" target="_blank" rel="noopener noreferrer">Pepipost</a> is a transactional email service. Every month Pepipost delivers over 8 billion emails from 20,000+ customers. Their mission is to reliably send emails in the most efficient way and at the most disruptive pricing ever. Pepipost provides users 30,000 free emails the first 30 days.'=>'<a href="%1$s" target="_blank" rel="noopener noreferrer">Pepipost</a> је услуга трансакционе е-поште. Pepipost сваког месеца испоручи више од 8 милијарди е-порука за више од 20.000 купаца. Мисија им је да поуздано шаљу е-поруке на најделотворнији начин и по најповољнијим ценама. Pepipost корисницима пружа 30.000 бесплатних е-порука у првих 30 дана.','Download'=>'Преузми','To send emails, change the value of the %1$s constant to %2$s.'=>'Да бисте слали е-поруке, промените вредност константе %1$s на %2$s.','We\'re sorry, the Amazon SES mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Нажалост, услуга слања Amazon SES није доступна у вашем плану. Надоградите на PRO план да бисте откључали све ове сјајне могућности.','Amazon SES'=>'Amazon SES','We\'re sorry, the Microsoft Outlook mailer is not available on your plan. Please upgrade to the PRO plan to unlock all these awesome features.'=>'Нажалост, услуга слања Microsoft Outlook није доступна у вашем плану. Надоградите на PRO план да бисте откључали све ове сјајне могућности.','Outlook'=>'Outlook','To send emails, go to plugin <a href="%s">Misc settings</a> and disable the "Do Not Send" option.'=>'Да бисте слали е-поруке, идите у <a href="%s">подешавања „Разно“</a> додатка и искључите могућност „Не шаљи“.','<strong>EMAILING DISABLED:</strong> The %s is currently blocking all emails from being sent.'=>'<strong>СЛАЊЕ Е-ПОШТЕ ЈЕ ИСКЉУЧЕНО:</strong> %s тренутно блокира слање свих е-порука.','Already purchased?'=>'Већ сте купили?','Upgrade to Pro'=>'Надоградите на Pro','%name% is a Pro Feature'=>'%name% је Pro функција','Educational notice for this mailer was successfully dismissed.'=>'Образовно обавештење за ову услугу слања успешно је одбачено.','Email Delivery Errors were disabled using a %s filter.'=>'Грешке испоруке е-поште искључене су помоћу филтера %s.','Hide Email Delivery Errors'=>'Сакриј грешке испоруке е-поште','<strong>This is not recommended</strong> and should only be done for staging or development sites.'=>'<strong>Ово се не препоручује</strong> и треба радити само за пробне или развојне сајтове.','Get v3 API Key'=>'Набави v3 API кључ','Follow this link to get an API Key: %s.'=>'Пратите ову везу да бисте добили API кључ: %s.','The Gmail mailer works well for sites that send low numbers of emails. However, Gmail\'s API has rate limitations and a number of additional restrictions that can lead to challenges during setup.<br><br>If you expect to send a high volume of emails, or if you find that your web host is not compatible with the Gmail API restrictions, then we recommend considering a different mailer option.'=>'Gmail услуга слања добро ради за сајтове који шаљу мали број е-порука. Међутим, Gmail API има ограничења учесталости и низ додатних ограничења која могу изазвати тешкоће током подешавања.<br><br>Ако очекујете да шаљете велики обим е-порука или ако утврдите да ваш хостинг није усаглашен са ограничењима Gmail API-ја, препоручујемо да размислите о другој услузи слања.','Meanwhile you can switch to some other mailers.'=>'У међувремену можете прећи на неку другу услугу слања.','https://wpmailsmtp.com/'=>'https://wpmailsmtp.com/','You have successfully linked the current site with your Google API project. Now you can start sending emails through Gmail.'=>'Успешно сте повезали тренутни сајт са својим Google API пројектом. Сада можете почети да шаљете е-поруке преко Gmail-а.','Activate'=>'Укључи','<strong>WP Mail SMTP plugin is disabled</strong> on your site until you fix the issue. <a href="%s" target="_blank" rel="noopener noreferrer">Read more for additional information.</a>'=>'<strong>Додатак WP Mail SMTP је искључен</strong> на вашем сајту док не решите проблем. <a href="%s" target="_blank" rel="noopener noreferrer">Прочитајте више за додатне податке.</a>','Your site is running an <strong>insecure version</strong> of PHP that is no longer supported. Please contact your web hosting provider to update your PHP version or switch to a <a href="%1$s" target="_blank" rel="noopener noreferrer">recommended WordPress hosting company</a>.'=>'Ваш сајт користи <strong>небезбедно издање</strong> PHP-а које више није подржано. Обратите се свом пружаоцу хостинга да ажурира издање PHP-а или пређите на <a href="%1$s" target="_blank" rel="noopener noreferrer">препоручену компанију за Вордпресов хостинг</a>.','WP Mail SMTP Pro related message was successfully dismissed.'=>'Порука у вези са WP Mail SMTP Pro успешно је одбачена.','Install and Activate'=>'Постави и укључи','Processing...'=>'У обради...','Current provider doesn\'t support setting and forcing From Name. Emails will be sent on behalf of the account name used to setup the OAuth connection below.'=>'Тренутни пружалац не подржава постављање и наметање имена пошиљаоца. Е-поруке ће бити слате у име налога коришћеног за подешавање OAuth везе испод.','Current provider will automatically force From Email to be the email address that you use to set up the OAuth connection below.'=>'Тренутни пружалац ће аутоматски наметнути да е-адреса пошиљаоца буде е-адреса коју користите за подешавање OAuth везе испод.','License Key'=>'Лиценцни кључ','License'=>'Дозвола','Could not install the plugin. Please download it from WordPress.org and install it manually.'=>'Није могуће поставити додатак. Преузмите га са WordPress.org и поставите ручно.','Check the inbox you used to create your Mailgun account and click the activation link in the email from Mailgun.'=>'Проверите сандуче које сте користили за прављење Mailgun налога и притисните везу за укључивање у е-поруци од Mailgun-а.','Enter email address where test email will be sent.'=>'Унесите е-адресу на коју ће бити послата пробна е-порука.','Email Controls'=>'Контроле е-поште','Feature'=>'Могућност','Pro'=>'Pro','Get the most out of WP Mail SMTP by upgrading to Pro and unlocking all of the powerful features.'=>'Извуците највише из WP Mail SMTP надоградњом на Pro и откључавањем свих моћних могућности.','Plugin installed & activated.'=>'Додатак је постављен и укључен.','Plugin installed.'=>'Додатак је постављен.','Could not install the plugin.'=>'Није могуће поставити додатак.','Plugin activated.'=>'Додатак је укључен.','Could not activate the plugin. Please activate it from the Plugins page.'=>'Није могуће укључити додатак. Укључите га са странице додатака.','Contact Forms by WPForms'=>'Обрасци за контакт помоћу WPForms','Inactive'=>'Искључено','Status: %s'=>'Стање: %s','The WPForms Team'=>'WPForms тим','The WPForms Team photo'=>'Фотографија WPForms тима','Yup, we know a thing or two about building awesome products that customers love.'=>'Да, знамо понешто о прављењу сјајних производа које купци воле.','Priority Support'=>'Приоритетна подршка','Email deliverability has been a well-documented problem for all WordPress websites. However as WPForms grew, we became more aware of this painful issue that affects our users and the larger WordPress community. So we decided to solve this problem and make a solution that\'s beginner friendly.'=>'Испоручивост е-поште је добро документован проблем за све Вордпресове веб сајтове. Међутим, како је WPForms растао, постали смо свеснији овог болног проблема који погађа наше кориснике и ширу Вордпресову заједницу. Зато смо одлучили да решимо овај проблем и направимо решење прилагођено почетницима.','Our goal is to make reliable email deliverability easy for WordPress.'=>'Наш циљ је да поуздану испоручивост е-поште учинимо лаком за Вордпрес.','Hello and welcome to WP Mail SMTP, the easiest and most popular WordPress SMTP plugin. We build software that helps your site reliably deliver emails every time.'=>'Здраво и добро дошли у WP Mail SMTP, најлакши и најпопуларнији SMTP додатак за Вордпрес. Правимо софтвер који помаже вашем сајту да сваки пут поуздано испоручи е-поруке.','About Us'=>'О нама','Email Log'=>'Дневник е-поште','%1$s \\a\\t %2$s'=>'%1$s у %2$s','You need to save settings with Client ID and Client Secret before you can proceed.'=>'Морате сачувати подешавања са Client ID и Client Secret пре него што наставите.','Connected as %s'=>'Повезивање као: %s','Please copy this URL into the "Authorized redirect URIs" field of your Google web application.'=>'Умножите овај URL у поље „Authorized redirect URIs“ своје Google веб апликације.','Upgrade to WP Mail SMTP Pro'=>'Надоградите на WP Mail SMTP Pro','The value of this field was set using a constant %1$s most likely inside %2$s of your WordPress installation.'=>'Вредност овог поља постављена је помоћу константе %1$s, највероватније у %2$s ваше Вордпресове инсталације.','All the defined constants will stop working and you will be able to change all the values on this page.'=>'Све дефинисане константе престаће да раде и моћи ћете да промените све вредности на овој страници.','If you want to disable the use of constants, find in %1$s file the constant %2$s and turn if off:'=>'Ако желите да искључите коришћење константи, пронађите у датотеци %1$s константу %2$s и искључите је:','To change the password you need to change the value of the constant there: %s'=>'Да бисте променили лозинку, морате тамо да промените вредност константе: %s','Please deactivate the free version of the WP Mail SMTP plugin before activating WP Mail SMTP Pro.'=>'Искључите бесплатно издање додатка WP Mail SMTP пре укључивања WP Mail SMTP Pro.','Pepipost'=>'Pepipost','Removing the OAuth connection will give you an ability to redo the OAuth connection or link to another Google account.'=>'Уклањање OAuth везе омогућиће вам да поново успоставите OAuth везу или се повежете са другим Google налогом.','Click the button above to confirm authorization.'=>'Притисните дугме изнад да бисте потврдили овлашћење.','Allow plugin to send emails using your Google account'=>'Дозволи додатку да шаље е-поруке помоћу вашег Google налога','Are you sure you want to reset the current provider connection? You will need to immediately create a new one to be able to send emails.'=>'Да ли сигурно желите да поништите тренутну везу са пружаоцем? Мораћете одмах да направите нову да бисте могли да шаљете е-поруке.','Copy URL to clipboard'=>'Умножи URL у оставу','Authorized redirect URI'=>'Овлашћени URI за преусмеравање','Client Secret'=>'Client Secret','Client ID'=>'Client ID','%1$s requires PHP %2$s to work and does not support your current PHP version %3$s. Please contact your host and request a PHP upgrade to the latest one.'=>'%1$s захтева PHP %2$s за рад и не подржава ваше тренутно PHP издање %3$s. Обратите се свом хостингу и затражите надоградњу PHP-а на најновије издање.','SMTP Password'=>'SMTP лозинка','SMTP Username'=>'SMTP корисничко име','By default, TLS encryption is automatically used if the server supports it (recommended). In some cases, due to server misconfigurations, this can cause issues and may need to be disabled.'=>'Подразумевано се TLS шифровање аутоматски користи ако га сервер подржава (препоручено). У неким случајевима, због погрешних подешавања сервера, ово може изазвати проблеме и можда ће морати да се искључи.','Auto TLS'=>'Аутоматски TLS','TLS'=>'TLS','For most servers TLS is the recommended option. If your SMTP provider offers both SSL and TLS options, we recommend using TLS.'=>'За већину сервера TLS је препоручена могућност. Ако ваш SMTP пружалац нуди и SSL и TLS, препоручујемо коришћење TLS-а.','SSL'=>'SSL','None'=>'Нема','If you are operating under EU laws, you may be required to use EU region.'=>'Ако пословање подлеже законима ЕУ, можда ћете морати да користите регион ЕУ.','Define which endpoint you want to use for sending messages.'=>'Одредите коју крајњу тачку желите да користите за слање порука.','EU'=>'ЕУ','US'=>'САД','Region'=>'Регион','Get a Domain Name'=>'Набави име домена','Follow this link to get a Domain Name from Mailgun: %s.'=>'Пратите ову везу да бисте добили име домена од Mailgun-а: %s.','Domain Name'=>'Име домена','Private API Key'=>'Приватни API кључ','Mailgun'=>'Mailgun','Default (none)'=>'Подразумевано (ништа)','To send emails you will need only a %s access level for this API key.'=>'За слање е-порука потребан вам је само ниво приступа %s за овај API кључ.','Create API Key'=>'Направи API кључ','Follow this link to get an API Key from SendGrid: %s.'=>'Пратите ову везу да бисте добили API кључ од SendGrid-а: %s.','API Key'=>'API кључ','SendGrid'=>'SendGrid','Other SMTP'=>'Други SMTP','Heads up! WP Mail SMTP has detected %1$s is activated. Please deactivate %1$s to prevent conflicts.'=>'Пажња! WP Mail SMTP је открио да је %1$s укључен. Искључите %1$s да бисте спречили сукобе.','Activated'=>'Укључено','Activate %s'=>'Укључи %s','Status'=>'Стање','Type'=>'Врста','Source'=>'Извор','Not Installed'=>'Није постављено','Recommended'=>'Препоручено','Required.'=>'Обавезно.','Dismiss this notice'=>'Занемари ову напомену','Install Plugin'=>'Постави додатак','Thanks for using WP Mail SMTP! To complete the plugin setup and start sending emails, <strong>please select and configure your <a href="%s">Mailer</a></strong>.'=>'Хвала што користите WP Mail SMTP! Да бисте довршили подешавање додатка и почели да шаљете е-поруке, <strong>изаберите и подесите своју <a href="%s">услугу слања</a></strong>.','You have successfully linked the current site with your Zoho Mail API project. Now you can start sending emails through Zoho Mail.'=>'Успешно сте повезали тренутни сајт са својим Zoho Mail API пројектом. Сада можете почети да шаљете е-поруке преко Zoho Mail-а.','There was an error while processing the authentication request. Please make sure that you have Client ID and Client Secret both valid and saved.'=>'Дошло је до грешке при обради захтева за потврђивање идентитета. Уверите се да су и Client ID и Client Secret исправни и сачувани.','There was an error while processing the authentication request. Please try again.'=>'Дошло је до грешке при обради захтева за потврђивање идентитета. Покушајте поново.','There was an error while processing the authentication request: %s. Please try again.'=>'Дошло је до грешке при обради захтева за потврђивање идентитета: %s. Покушајте поново.','If unchecked, bounce messages may be lost.'=>'Ако није означено, поруке о одбијању могу бити изгубљене.','Return Path indicates where non-delivery receipts - or bounce messages - are to be sent.'=>'Return Path означава где треба слати потврде о неиспоруци – односно поруке о одбијању.','If checked, the From Name setting above will be used for all emails, ignoring values set by other plugins.'=>'Ако је означено, подешавање имена пошиљаоца изнад користиће се за све е-поруке, уз занемаривање вредности које постављају други додаци.','The name that emails are sent from.'=>'Име са којим се шаљу е-поруке.','Force From Name'=>'Наметни име пошиљаоца','If checked, the From Email setting above will be used for all emails, ignoring values set by other plugins.'=>'Ако је означено, подешавање е-адресе пошиљаоца изнад користиће се за све е-поруке, уз занемаривање вредности које постављају други додаци.','Force From Email'=>'Наметни е-адресу пошиљаоца','Please note that other plugins can change this, to prevent this use the setting below.'=>'Имајте на уму да други додаци могу ово да промене; да бисте то спречили, користите подешавање испод.','If you\'re using an email provider (Yahoo, Outlook.com, etc) this should be your email address for that account.'=>'Ако користите пружаоца е-поште (Yahoo, Outlook.com итд.), ово треба да буде ваша е-адреса за тај налог.','The email address that emails are sent from.'=>'Е-адреса са које се шаљу е-поруке.','Mail'=>'Пошта','Your host is rejecting the connection.'=>'Ваш хостинг одбија везу.','Contact your web hosting provider and ask them to verify your server can make outside connections, and whether a firewall or security policy may be blocking them. Many shared hosts block certain ports. <strong>Note: this is the most common cause of this issue.</strong>'=>'Обратите се свом пружаоцу хостинга и замолите га да провери да ли ваш сервер може да успоставља спољне везе и да ли их можда блокира заштитни зид или безбедносна политика. Многи дељени хостинзи блокирају одређене портове. <strong>Напомена: ово је најчешћи узрок овог проблема.</strong>','Your plugin settings are incorrect (wrong SMTP settings, invalid Mailer configuration, etc.).'=>'Подешавања додатка нису исправна (погрешна SMTP подешавања, неисправно подешавање услуге слања итд.).','An issue was detected.'=>'Откривен је проблем.','Reinstall the plugin with clean plugin data enabled on the Misc page. This will remove all plugin options so you can safely retry.'=>'Поново поставите додатак уз укључено чишћење података додатка на страници „Разно“. Ово ће уклонити све могућности додатка да бисте могли безбедно поново да покушате.','Google API Error.'=>'Google API грешка.','Complete the steps in section "2. Verify Your Domain".'=>'Довршите кораке у одељку „2. Verify Your Domain“.','Mailgun failed.'=>'Mailgun није успео.','Contact your web hosting provider and ask them to verify your server can connect to your SMTP host on the configured port and encryption, and whether a firewall or security policy may be blocking the connection. Many shared hosts block certain ports. <strong>Note: this is the most common cause of this issue.</strong>'=>'Обратите се свом пружаоцу хостинга и замолите га да провери да ли ваш сервер може да се повеже са SMTP домаћином на подешеном порту и шифровању и да ли можда заштитни зид или безбедносна политика блокира везу. Многи дељени хостинзи блокирају одређене портове. <strong>Напомена: ово је најчешћи узрок овог проблема.</strong>','Your web server is blocking the connection.'=>'Ваш веб сервер блокира везу.','Your SMTP host is rejecting the connection.'=>'Ваш SMTP домаћин одбија везу.','Your SMTP settings are incorrect (wrong port, security setting, or host).'=>'Ваша SMTP подешавања нису исправна (погрешан порт, безбедносно подешавање или домаћин).','Typically this error is returned for one of the following reasons:'=>'Обично се ова грешка враћа из неког од следећих разлога:','Could not connect to the SMTP host.'=>'Није могуће повезати се са SMTP домаћином.','Enter the correct SMTP Username (usually an email address) and Password in the appropriate fields.'=>'Унесите тачно SMTP корисничко име (обично е-адреса) и лозинку у одговарајућа поља.','Enable Authentication'=>'Укључи потврђивање идентитета','Go to the WP Mail SMTP plugin Settings page.'=>'Идите на страницу подешавања додатка WP Mail SMTP.','Unauthenticated senders are not allowed.'=>'Пошиљаоци без потврђеног идентитета нису дозвољени.','Verify with them that your SMTP account is in good standing and has not been flagged.'=>'Проверите са њима да ли је ваш SMTP налог у добром стању и да ли није означен.','Contact your SMTP host to ask about sending and rate limits.'=>'Обратите се свом SMTP домаћину да питате о ограничењима слања и учесталости.','Error due to unsolicited and/or bulk e-mail.'=>'Грешка због нежељене и/или масовне е-поште.','Verify with your SMTP host that your account has permissions to send emails using outside connections.'=>'Проверите са SMTP домаћином да ли ваш налог има дозволе за слање е-порука преко спољних веза.','Contact your SMTP host to confirm you are using the correct username and password.'=>'Обратите се свом SMTP домаћину да потврдите да користите тачно корисничко име и лозинку.','Triple-check your SMTP settings including host address, email, and password. If you have recently reset your password you will need to update the settings.'=>'Трипут проверите своја SMTP подешавања, укључујући адресу домаћина, е-адресу и лозинку. Ако сте недавно променили лозинку, мораћете да ажурирате подешавања.','Could not authenticate your SMTP account.'=>'Није могуће потврдити идентитет вашег SMTP налога.','Contact your web hosting provider and inform them you are having issues making outbound connections.'=>'Обратите се свом пружаоцу хостинга и обавестите га да имате проблема са успостављањем одлазних веза.','Could not connect to your host.'=>'Није могуће повезати се са вашим домаћином.','Could not connect to host.'=>'Није могуће повезати се са домаћином.','Contact your web hosting provider and inform them your site has an issue with SSL certificates.'=>'Обратите се свом пружаоцу хостинга и обавестите га да ваш сајт има проблем са SSL сертификатима.','SSL certificate issue.'=>'Проблем са SSL сертификатом.','Test failed. Please use a valid email address and try to resend the test email.'=>'Проба није успела. Користите исправну е-адресу и покушајте поново да пошаљете пробну е-поруку.','Send Email'=>'Пошаљи е-поруку','You cannot send an email. Mailer is not properly configured. Please check your settings.'=>'Не можете да пошаљете е-поруку. Услуга слања није исправно подешена. Проверите подешавања.','Send this email in HTML or in plain text format.'=>'Пошаљите ову е-поруку у HTML облику или као обичан текст.','Off'=>'Искључено','Send To'=>'Пошаљи на','HTML'=>'HTML','On'=>'На дан','Email Test'=>'Проба е-поште','Save Settings'=>'Сачувај подешавања','Uninstall WP Mail SMTP'=>'Уклони WP Mail SMTP','Settings were successfully saved.'=>'Подешавања су успешно сачувана.','Hide Announcements'=>'Сакриј објаве','You will need to consult with their documentation to switch them to use default WordPress email delivery.'=>'Мораћете да погледате њихову документацију да бисте их пребацили на подразумевану Вордпресову испоруку е-поште.','Test emails are allowed to be sent, regardless of this option.'=>'Пробне е-поруке могу да се шаљу без обзира на ову могућност.','Some plugins, like BuddyPress and Events Manager, are using their own email delivery solutions. By default, this option does not block their emails, as those plugins do not use default <code>wp_mail()</code> function to send emails.'=>'Неки додаци, као што су BuddyPress и Events Manager, користе сопствена решења за испоруку е-поште. Подразумевано ова могућност не блокира њихове е-поруке, јер ти додаци не користе подразумевану функцију <code>wp_mail()</code> за слање е-порука.','Do Not Send'=>'Не шаљи','General'=>'Опште','WPForms'=>'WPForms','Misc'=>'Разно','<a href="%s" rel="" target="_blank">More information</a> on Mailgun.com.'=>'<a href="%s" rel="" target="_blank">Више података</a> на Mailgun.com.','Please rate <strong>WP Mail SMTP</strong> <a href="%1$s" target="_blank" rel="noopener noreferrer">&#9733;&#9733;&#9733;&#9733;&#9733;</a> on <a href="%2$s" target="_blank" rel="noopener noreferrer">WordPress.org</a> to help us spread the word. Thank you from the WP Mail SMTP team!'=>'Оцените <strong>WP Mail SMTP</strong> са <a href="%1$s" target="_blank" rel="noopener noreferrer">&#9733;&#9733;&#9733;&#9733;&#9733;</a> на <a href="%2$s" target="_blank" rel="noopener noreferrer">WordPress.org</a> да бисте нам помогли да се прочује. Хвала од WP Mail SMTP тима!','Go to our how-to guide for setting up <a href="%s" target="_blank" rel="noopener noreferrer">Mailgun with WP Mail SMTP</a>.'=>'Идите на наш водич за подешавање <a href="%s" target="_blank" rel="noopener noreferrer">Mailgun-а уз WP Mail SMTP</a>.','To'=>'До','Remove Connection'=>'Уклони везу','Active'=>'Укључено','Authorization'=>'Ауторизација','Install'=>'Инсталирај','Version'=>'Верзија','Settings'=>'Подешавања','Save Changes'=>'Сачувајте промене','WP Mail SMTP'=>'WP Mail SMTP','Send a Test Email'=>'Пошаљи пробну е-поруку','Authentication'=>'Потврђивање идентитета','Email'=>'Е-пошта','SMTP Host'=>'SMTP домаћин','Return Path'=>'Return Path','SMTP Port'=>'SMTP порт','Mailer'=>'Услуга слања','From Name'=>'Име пошиљаоца','From Email'=>'Е-адреса пошиљаоца','Password'=>'Лозинка','Username'=>'Корисничко име','Encryption'=>'Енкрипција']];